window.ZEBUR_DATA = [{"id":1,"name":"1. Mezmur","verses":[{"n":"1","t":"Ne mutlu o insana ki, kötülerin öğüdüyle yürümez, Günahkârların yolunda durmaz, Alaycıların arasında oturmaz."},{"n":"2","t":"Ancak zevkini RAB'bin Yasası'ndan alır Ve gece gündüz onun üzerinde derin derin düşünür."},{"n":"3","t":"Böylesi akarsu kıyılarına dikilmiş ağaca benzer, Meyvesini mevsiminde verir, Yaprağı hiç solmaz. Yaptığı her işi başarır."},{"n":"4","t":"Kötüler böyle değil, Rüzgarın savurduğu saman çöpüne benzerler."},{"n":"5","t":"Bu yüzden yargılanınca aklanamaz, Doğrular topluluğunda yer bulamaz günahkârlar."},{"n":"6","t":"Çünkü RAB doğruların yolunu gözetir, Kötülerin yolu ise ölüme götürür."}]},{"id":2,"name":"2. Mezmur","verses":[{"n":"1","t":"Nedir uluslar arasındaki bu kargaşa, Neden boş düzenler kurar bu halklar?"},{"n":"2","t":"Dünyanın kralları saf bağlıyor, Hükümdarlar birleşiyor RAB'be ve meshettiği* krala*fa* karşı.D"},{"n":"2","t":"\"Meshettiği krala\": İbranice \"Meshettiğine\"."},{"n":"3","t":"\"Koparalım onların kayışlarını\" diyorlar, \"Atalım üzerimizden bağlarını.\""},{"n":"4","t":"Göklerde oturan Rab gülüyor, Onlarla eğleniyor."},{"n":"5","t":"Sonra öfkeyle uyarıyor onları, Gazabıyla dehşete düşürüyor"},{"n":"6","t":"Ve, \"Ben kralımı Kutsal dağım Siyon'a oturttum\" diyor."},{"n":"7","t":"RAB'bin bildirisini ilan edeceğim: Bana, \"Sen benim oğlumsun\" dedi, \"Bugün ben sana baba oldum."},{"n":"8","t":"Dile benden, miras olarak sana ulusları, Mülk olarak yeryüzünün dört bucağını vereyim."},{"n":"9","t":"Demir çomakla kıracaksın*fb* onları, Çömlek gibi parçalayacaksın.\"D"},{"n":"9","t":"Masoretik metin \"Kıracaksın\", Septuaginta, Süryanice\"Güdeceksin\"."},{"n":"10","t":"Ey krallar, akıllı olun! Ey dünya önderleri, ders alın!"},{"n":"11","t":"RAB'be korkuyla hizmet edin, Titreyerek sevinin."},{"n":"12","t":"Oğulu öpün ki öfkelenmesin, Yoksa izlediğiniz yolda mahvolursunuz. Çünkü öfkesi bir anda alevleniverir. Ne mutlu O'na sığınanlara!"}]},{"id":3,"name":"3. Mezmur Davut'un oğlu Avşalom'dan kaçtığı zaman yazdığı mezmur","verses":[{"n":"1","t":"Ya RAB, düşmanlarım ne kadar çoğaldı, Hele bana karşı ayaklananlar!"},{"n":"2","t":"Birçoğu benim için: \"Tanrı katında ona kurtuluş yok!\" diyor. *fc*D"},{"n":"2","t":"\"Sela\": Müzikte duruş ifade eden bir terim olduğusanılıyor."},{"n":"3","t":"Ama sen, ya RAB, çevremde kalkansın, Onurum, başımı yukarı kaldıran sensin."},{"n":"4","t":"RAB'be seslenirim, Yanıtlar beni kutsal dağından."},{"n":"5","t":"Yatar uyurum, Uyanır kalkarım, RAB destektir bana."},{"n":"6","t":"Korkum yok Çevremi saran binlerce düşmandan."},{"n":"7","t":"Ya RAB, kalk, ey Tanrım, kurtar beni! Vur bütün düşmanlarımın çenesine, Kır kötülerin dişlerini."},{"n":"8","t":"Kurtuluş RAB'dedir, Halkının üzerinde olsun bereketin!"}]},{"id":4,"name":"4. Mezmur Müzik şefi için - Telli sazlarla - Davut'un mezmuru","verses":[{"n":"1","t":"Sana seslenince yanıtla beni, Ey adil Tanrım! Ferahlat beni sıkıntıya düştüğümde, Lütfet bana, kulak ver duama."},{"n":"2","t":"Ey insanlar, ne zamana dek Onurumu utanca çevireceksiniz? Ne zamana dek boş şeylere gönül verecek, Yalan peşinde koşacaksınız?"},{"n":"3","t":"Bilin ki, RAB sadık kulunu kendine ayırmıştır, Ne zaman seslensem, duyar beni."},{"n":"4","t":"Öfkelenebilirsiniz, ama günah işlemeyin; İyi düşünün yatağınızda, susun."},{"n":"5","t":"Doğruluk kurbanları sunun RAB'be, O'na güvenin."},{"n":"6","t":"\"Kim bize iyilik yapacak?\" diyen çok. Ya RAB, yüzünün ışığıyla bizi aydınlat!"},{"n":"7","t":"Öyle bir sevinç verdin ki bana, Onların bol tahıl ve yeni şaraptan aldığı sevinçten fazla."},{"n":"8","t":"Esenlik içinde yatar uyurum, Çünkü yalnız sen, ya RAB, Güvenlik içinde tutarsın beni."}]},{"id":5,"name":"5. Mezmur Müzik şefi için - Ney için - Davut'un mezmuru","verses":[{"n":"1","t":"Sözlerime kulak ver, ya RAB, İniltilerimi işit."},{"n":"2","t":"Feryadımı dinle, ey Kralım ve Tanrım! Duam sanadır."},{"n":"3","t":"Sabah sesimi duyarsın, ya RAB, Her sabah sana duamı sunar, umutla beklerim."},{"n":"4","t":"Çünkü sen kötülükten hoşlanan Tanrı değilsin, Kötülük senin yanında barınmaz."},{"n":"5","t":"Böbürlenenler önünde duramaz, Bütün suç işleyenlerden nefret duyar,"},{"n":"6","t":"Yalan söyleyenleri yok edersin; Ya RAB, sen eli kanlılardan, Aldatıcılardan tiksinirsin."},{"n":"7","t":"Bense bol sevgin sayesinde Kutsal tapınağına gireceğim; Oraya doğru saygıyla eğileceğim."},{"n":"8","t":"Yol göster bana doğruluğunla, ya RAB, Düşmanlarıma karşı! Yolunu önümde düzle."},{"n":"9","t":"Çünkü onların sözüne güvenilmez, Yürekleri yıkım dolu. Ağızları açık birer mezardır, Yaltaklanır dururlar."},{"n":"10","t":"Ey Tanrı, onları suçlu çıkar! Kurdukları düzen yıkımlarına yol açsın. Kov onları sayısız isyanları yüzünden. Çünkü sana karşı ayaklandılar."},{"n":"11","t":"Sevinsin sana sığınan herkes, Sevinç çığlıkları atsın sürekli, Kanat ger üzerlerine; Sevinçle coşsun adını sevenler sende."},{"n":"12","t":"Çünkü sen doğru kişiyi kutsarsın, ya RAB, Çevresini kalkan gibi lütfunla sararsın."}]},{"id":6,"name":"6. Mezmur Müzik şefi için - Sekiz telli sazlarla*fç*Davut'un mezmuru","verses":[{"n":"1","t":"Ya RAB, öfkeyle azarlama beni, Gazapla yola getirme.D Not \"Sekiz telli sazlarla\": İbranice \"Sekizinciye göre\", anlamıkesin olarak bilinmiyor."},{"n":"2","t":"Lütfet bana, ya RAB, bitkinim; Şifa ver bana, ya RAB, kemiklerim sızlıyor,"},{"n":"3","t":"Çok acı çekiyorum. Ah, ya RAB! Ne zamana dek sürecek bu?"},{"n":"4","t":"Gel, ya RAB, kurtar beni, Yardım et sevginden dolayı."},{"n":"5","t":"Çünkü ölüler arasında kimse seni anmaz, Kim şükür sunar sana ölüler diyarından?"},{"n":"6","t":"İnleye inleye bittim, Döşeğim su içinde bütün gece ağlamaktan, Yatağım sırılsıklam gözyaşlarımdan."},{"n":"7","t":"Kederden gözlerimin feri sönüyor, Zayıflıyor gözlerim düşmanlarım yüzünden."},{"n":"8","t":"Ey kötülük yapanlar, Uzak durun benden, Çünkü RAB ağlayışımı işitti."},{"n":"9","t":"Yalvarışımı duydu, Duamı kabul etti."},{"n":"10","t":"Bütün düşmanlarım utanacak, Hepsini dehşet saracak, Ansızın geri dönecekler utanç içinde."}]},{"id":7,"name":"7. Mezmur Benyaminli Kûş'un sözlerine ilişkinDavut'un RAB'be okuduğu şigayon*fd*","verses":[{"n":"1","t":"Sana sığınıyorum, ya RAB Tanrım! Peşime düşenlerden kurtar beni, Özgür kıl."},{"n":"2","t":"Yoksa aslan gibi parçalayacaklar beni, Kurtaracak biri yok diye, Lime lime edecekler etimi."},{"n":"3","t":"Ya RAB Tanrım, eğer şunu yaptıysam: Birine haksızlık ettiysem,"},{"n":"4","t":"Dostuma ihanet ettiysem, Düşmanımı nedensiz soyduysam,"},{"n":"5","t":"Ardıma düşsün düşman, Yakalasın beni, Canımı yerde çiğnesin, Ayak altına alsın onurumu. *"},{"n":"6","t":"Öfkeyle kalk, ya RAB! Düşmanlarımın gazabına karşı çık! Benim için uyan! Buyur, adalet olsun."},{"n":"7","t":"Uluslar topluluğu çevreni sarsın, Onları yüce katından yönet."},{"n":"8","t":"RAB halkları yargılar; Beni de yargıla, ya RAB, Doğruluğuma, dürüstlüğüme göre."},{"n":"9","t":"Ey adil Tanrım! Kötülerin kötülüğü son bulsun, Doğrular güvene kavuşsun, Sen ki akılları, gönülleri sınarsın."},{"n":"10","t":"Tanrı kalkan gibi yanıbaşımda, Temiz yüreklileri O kurtarır."},{"n":"11","t":"Tanrı adil bir yargıçtır, Öyle bir Tanrı ki, her gün öfke saçar."},{"n":"12","t":"Kötüler yola gelmezse, Tanrı kılıcını biler, Yayını gerip hedefine kurar."},{"n":"13","t":"Hazır bekler ölümcül silahları, Alevli okları."},{"n":"14","t":"İşte kötü insan kötülük sancıları çekiyor, Fesada gebe kalmış, Yalan doğuruyor."},{"n":"15","t":"Bir kuyu açıp kazıyor, Kazdığı kuyuya kendisi düşüyor."},{"n":"16","t":"Kötülüğü kendi başına gelecek, Zorbalığı kendi tepesine inecek."},{"n":"17","t":"Şükredeyim doğruluğu için RAB'be, Yüce RAB'bin adını ilahilerle öveyim."}]},{"id":8,"name":"8. Mezmur Müzik şefi için - Gittit*fe* |iüzerine - Davut'un mezmuru","verses":[{"n":"1","t":"Ey Egemenimiz RAB, Ne yüce adın var yeryüzünün tümünde! Gökyüzünü görkeminle kapladın.D Not \"Gittit\": Bir müzik terimi ya da üzüm sıkma mevsimindeokunan bir ilahi olabilir."},{"n":"2","t":"Çocukların, hatta emziktekilerin sesiyle Set çektin hasımlarına, Düşmanı, öç alanı yok etmek için."},{"n":"3","t":"Seyrederken ellerinin eseri olan gökleri, Oraya koyduğun ayı ve yıldızları,"},{"n":"4","t":"Soruyorum kendi kendime: \"İnsan ne ki, onu anasın, Ya da insanoğlu ne ki, ona ilgi gösteresin?\""},{"n":"5","t":"Nerdeyse bir tanrı yaptın onu*ff*, Başına yücelik ve onur tacını koydun.D"},{"n":"5","t":"\"Nerdeyse bir tanrı yaptın onu\": İbranice \"Onu Tanrı'dan(tanrılardan) pek aşağı yaratmadın\" (bkz. Yar.1:26-28; İbr.2:6-8)."},{"n":"6","t":"Ellerinin yapıtları üzerine onu egemen kıldın, Her şeyi ayaklarının altına serdin;"},{"n":"7","t":"Davarları, sığırları, Yabanıl hayvanları,"},{"n":"8","t":"Gökteki kuşları, denizdeki balıkları, Denizde kıpırdaşan bütün canlıları."},{"n":"9","t":"Ey Egemenimiz RAB, Ne yüce adın var yeryüzünün tümünde!"}]},{"id":9,"name":"9. Mezmur Müzik şefi için - \"Oğulun Ölümü\" makamında -Davut'un mezmuru","verses":[{"n":"1","t":"Ya RAB, bütün yüreğimle sana şükredeceğim, Yaptığın harikaların hepsini anlatacağım.D Not Birçok İbranice elyazmasında 9. ve 10. Mezmur birleşikyazılır."},{"n":"2","t":"Sende sevinç bulacak, coşacağım, Adını ilahilerle öveceğim, ey Yüceler Yücesi!"},{"n":"3","t":"Düşmanlarım geri çekilirken, Sendeleyip ölüyorlar senin önünde."},{"n":"4","t":"Çünkü hakkımı, davamı sen savundun, Adil yargıç olarak tahta oturdun."},{"n":"5","t":"Ulusları azarladın, kötüleri yok ettin, Sonsuza dek adlarını sildin."},{"n":"6","t":"Yok olup gitti düşmanlar sonsuza dek, Kökünden söktün kentlerini, Anıları bile silinip gitti."},{"n":"7","t":"Oysa RAB sonsuza dek egemenlik sürer, Yargı için kurmuştur tahtını;"},{"n":"8","t":"O yönetir doğrulukla dünyayı, O yargılar adaletle halkları."},{"n":"9","t":"RAB ezilenler için bir sığınak, Sıkıntılı günlerde bir kaledir."},{"n":"10","t":"Seni tanıyanlar sana güvenir, Çünkü sana yönelenleri hiç terk etmedin, ya RAB."},{"n":"11","t":"Siyon'da oturan RAB'bi ilahilerle övün! Yaptıklarını halklar arasında duyurun!"},{"n":"12","t":"Çünkü dökülen kanın hesabını soran anımsar, Ezilenlerin feryadını unutmaz."},{"n":"13","t":"Acı bana, ya RAB! Ey beni ölümün eşiğinden kurtaran, Benden nefret edenler yüzünden çektiğim sıkıntıya bak!"},{"n":"14","t":"Öyle ki, övgüye değer işlerini anlatayım, Siyon Kenti'nin kapılarında Sağladığın kurtuluşla sevineyim."},{"n":"15","t":"Uluslar kendi kazdıkları kuyuya düştü, Ayakları gizledikleri ağa takıldı."},{"n":"16","t":"Adil yargılarıyla RAB kendini gösterdi, Kötüler kendi kurdukları tuzağa düştü. -Higayon*fh* *D"},{"n":"16","t":"\"Higayon\": Anlamı kesin olarak bilinmeyen bir müzikterimi."},{"n":"17","t":"Kötüler ölüler diyarına gidecek, Tanrı'yı unutan bütün uluslar..."},{"n":"18","t":"Ama yoksul büsbütün unutulmayacak, Mazlumun umudu sonsuza dek kırılmayacak."},{"n":"19","t":"Kalk, ya RAB! İnsan galip çıkmasın, Huzurunda yargılansın uluslar!"},{"n":"20","t":"Onlara dehşet saç, ya RAB! Sadece insan olduklarını bilsin uluslar."}]},{"id":10,"name":"10. Mezmur","verses":[{"n":"1","t":"Ya RAB, neden uzak duruyorsun, Sıkıntılı günlerde kendini gizliyorsun?"},{"n":"2","t":"Kötüler gururla mazlumları avlıyor, Mazlumlar kötülerin kurduğu tuzağa düşüyor."},{"n":"3","t":"Kötü insan içindeki isteklerle övünür, Açgözlü insan RAB'be lanet okur, O'nu hor görür."},{"n":"4","t":"Kendini beğenmiş kötü insan Tanrı'ya yönelmez, Hep, \"Tanrı yok!\" diye düşünür."},{"n":"5","t":"Kötülerin yolları her zaman başarıya götürür. Öyle yücedir ki senin yargıların, Kötüler anlayamaz, düşmanına burun kıvırır."},{"n":"6","t":"İçinden, \"Ben sarsılmam\" der, \"Hiçbir zaman sıkıntıya düşmem.\""},{"n":"7","t":"Ağzı lanet, hile ve zulüm dolu, Dilinin altında kötülük ve fesat saklı."},{"n":"8","t":"Köylerin çevresinde pusu kurar, Masumu gizli yerlerde öldürür, Çaresizi sinsice gözler."},{"n":"9","t":"Gizli yerlerde pusuya yatar Çalılıktaki aslan gibi, Kapmak için mazlumu bekler Ve ağına düşürüp yakalar."},{"n":"10","t":"Kurbanları çaresiz çöker, Saldıranın üstün gücü altında ezilir."},{"n":"11","t":"Kötü insan içinden, \"Tanrı unuttu\" der, \"Örttü yüzünü, asla göremez.\""},{"n":"12","t":"Kalk, ya RAB, kaldır elini, ey Tanrı! Mazlumları unutma!"},{"n":"13","t":"Neden kötü insan seni hor görsün, İçinden, \"Tanrı hesap sormaz\" desin?"},{"n":"14","t":"Oysa sen sıkıntı ve acı çekenleri görürsün, Yardım etmek için onları izlersin; Çaresizler sana dayanır, Öksüzün yardımcısı sensin."},{"n":"15","t":"Kötünün, haksızın kolunu kır, Sormadık hesap kalmasın yaptığı kötülükten."},{"n":"16","t":"RAB sonsuza dek kral kalacak, Uluslar O'nun ülkesinden temizlenecek."},{"n":"17","t":"Mazlumların dileğini duyarsın, ya RAB, Yüreklendirirsin onları, Kulağın hep üzerlerinde;"},{"n":"18","t":"Öksüze, düşküne hakkını vermek için, Bir daha dehşet saçmasın ölümlü insan."}]},{"id":11,"name":"11. Mezmur Müzik şefi için - Davut'un mezmuru","verses":[{"n":"1","t":"Ben RAB'be sığınırım, Nasıl dersiniz bana, \"Kuş gibi kaç dağlara."},{"n":"2","t":"Bak, kötüler yaylarını geriyor, Temiz yürekli insanları Karanlıkta vurmak için Oklarını kirişine koyuyor."},{"n":"3","t":"Temeller yıkılırsa, Ne yapabilir doğru insan?\""},{"n":"4","t":"RAB kutsal tapınağındadır, O'nun tahtı göklerdedir, Bütün insanları görür, Herkesi sınar."},{"n":"5","t":"RAB doğru insanı sınar, Kötüden, zorbalığı sevenden tiksinir."},{"n":"6","t":"Kötülerin üzerine kızgın korlar ve kükürt yağdıracak, Paylarına düşen kâse* kavurucu rüzgar olacak."},{"n":"7","t":"Çünkü RAB doğrudur, doğruları sever; Dürüst insanlar O'nun yüzünü görecek."}]},{"id":12,"name":"12. Mezmur Müzik şefi için - Sekiz telli sazlarla*fı* -Davut'un mezmuru","verses":[{"n":"1","t":"Kurtar beni, ya RAB, sadık kulun kalmadı, Güvenilir insanlar yok oldu."},{"n":"2","t":"Herkes birbirine yalan söylüyor, Dalkavukluk, ikiyüzlülük ediyor."},{"n":"3","t":"Sustursun RAB dalkavukların ağzını, Büyüklenen dilleri."},{"n":"4","t":"Onlar ki, \"Dilimizle kazanırız, Dudaklarımız emrimizde, Kim bize efendilik edebilir?\" derler."},{"n":"5","t":"\"Şimdi kalkacağım\" diyor RAB, \"Çünkü mazlumlar eziliyor, Yoksullar inliyor, Özledikleri kurtuluşu vereceğim onlara.\""},{"n":"6","t":"RAB'bin sözleri pak sözlerdir; Toprak ocakta eritilmiş, Yedi kez arıtılmış gümüşe benzer."},{"n":"7","t":"Sen onları koru, ya RAB, Bu kötü kuşaktan hep uzak tut!"},{"n":"8","t":"İnsanlar arasında alçaklık rağbet görünce, Kötüler her yanda dolaşır oldu."}]},{"id":13,"name":"13. Mezmur Müzik şefi için - Davut'un mezmuru","verses":[{"n":"1","t":"Ne zamana dek, ya RAB, Sonsuza dek mi beni unutacaksın? Ne zamana dek yüzünü benden gizleyeceksin?"},{"n":"2","t":"Ne zamana dek içimde tasa, Yüreğimde hep keder olacak? Ne zamana dek düşmanım bana üstün çıkacak?"},{"n":"3","t":"Gör halimi, ya RAB, yanıtla Tanrım, Gözlerimi aç, ölüm uykusuna dalmayayım."},{"n":"4","t":"Düşmanlarım, \"Onu yendik!\" demesin, Sarsıldığımda hasımlarım sevinmesin."},{"n":"5","t":"Ben senin sevgine güveniyorum, Yüreğim kurtarışınla coşsun."},{"n":"6","t":"Ezgiler söyleyeceğim sana, ya RAB, Çünkü iyilik ettin bana."}]},{"id":14,"name":"14. Mezmur (Mez.53) Müzik şefi için - Davut'un mezmuru","verses":[{"n":"1","t":"Akılsız içinden, \"Tanrı yok!\" der. İnsanlar bozuldu, iğrençlik aldı yürüdü, İyilik eden yok."},{"n":"2","t":"RAB göklerden bakar oldu insanlara, Akıllı, Tanrı'yı arayan biri var mı diye."},{"n":"3","t":"Hepsi saptı, Tümü yozlaştı, İyilik eden yok, Bir kişi bile!"},{"n":"4","t":"Suç işleyenlerin hiçbiri görmüyor mu? Halkımı ekmek yer gibi yiyor, RAB'be yakarmıyorlar."},{"n":"5","t":"Dehşete düşecekler yeryüzünde, Çünkü Tanrı doğruların yanındadır."},{"n":"6","t":"Mazlumun tasarılarını boşa çıkarırdınız, Ama RAB onun sığınağıdır."},{"n":"7","t":"Keşke İsrail'in kurtuluşu Siyon'dan gelse! RAB halkını eski gönencine kavuşturunca, Yakup soyu sevinecek, İsrail halkı coşacak."}]},{"id":15,"name":"15. Mezmur Davut'un mezmuru","verses":[{"n":"1","t":"Ya RAB, çadırına kim konuk olabilir? Kutsal dağında kim oturabilir?"},{"n":"2","t":"Kusursuz yaşam süren, adil davranan, Yürekten gerçeği söyleyen."},{"n":"3","t":"İftira etmez, Dostuna zarar vermez, Komşusuna kara çalmaz böylesi."},{"n":"4","t":"Aşağılık insanları hor görür, Ama RAB'den korkanlara saygı duyar. Kendi zararına ant içse bile, dönmez andından."},{"n":"5","t":"Parasını faize vermez, Suçsuza karşı rüşvet almaz. Böyle yaşayan asla sarsılmayacak."}]},{"id":16,"name":"16. Mezmur Davut'un Miktamı*fi*","verses":[{"n":"1","t":"Koru beni, ey Tanrı, Çünkü sana sığınıyorum."},{"n":"2","t":"RAB'be dedim ki, \"Efendim sensin. Senden öte mutluluk yok benim için.\""},{"n":"3","t":"Ülkedeki kutsallara gelince, Soyludur onlar, biricik zevkim onlardır."},{"n":"4","t":"Başka ilahların ardınca koşanların derdi artacak. Onların kan sunularını dökmeyeceğim, Adlarını ağzıma almayacağım."},{"n":"5","t":"Benim payıma, Benim kâseme düşen sensin, ya RAB; Yaşamım senin ellerinde."},{"n":"6","t":"Payıma ne güzel yerler düştü, Ne harika bir mirasım var!"},{"n":"7","t":"Övgüler sunarım bana öğüt veren RAB'be, Geceleri bile vicdanım uyarır beni."},{"n":"8","t":"Gözümü RAB'den ayırmam, Sağımda durduğu için sarsılmam."},{"n":"9","t":"Bu nedenle içim sevinç dolu, yüreğim coşuyor, Bedenim güven içinde."},{"n":"10","t":"Çünkü sen beni ölüler diyarına terk etmezsin, Sadık kulunun çürümesine izin vermezsin*fj*.D"},{"n":"10","t":"\"Sadık kulunun çürümesine izin vermezsin\" ya da \"Sadıkkulunun ölüm çukurunu görmesine izin vermezsin.\""},{"n":"11","t":"Yaşam yolunu bana bildirirsin. Bol sevinç vardır senin huzurunda, Sağ elinden mutluluk eksilmez."}]},{"id":17,"name":"17. Mezmur Davut'un duası","verses":[{"n":"1","t":"Haklı davamı dinle, ya RAB, Feryadımı işit! Hilesiz dudaklardan çıkan duama kulak ver!"},{"n":"2","t":"Haklı çıkar beni, Çünkü sen gerçeği görürsün."},{"n":"3","t":"Yüreğimi yokladın, Gece denedin, Sınadın beni, Kötü bir şey bulmadın; Kararlıyım, ağzımdan kötü söz çıkmaz,"},{"n":"4","t":"Başkalarının yaptıklarına gelince, Ben senin sözlerine uyarak Şiddet yollarından kaçındım."},{"n":"5","t":"Sıkı adımlarla senin yollarını tuttum, Kaymadı ayaklarım."},{"n":"6","t":"Sana yakarıyorum, ey Tanrı, Çünkü beni yanıtlarsın; Kulak ver bana, dinle söylediklerimi!"},{"n":"7","t":"Göster harika sevgini, Ey sana sığınanları saldırganlardan sağ eliyle kurtaran!"},{"n":"8","t":"Koru beni gözbebeği gibi; Kanatlarının gölgesine gizle"},{"n":"9","t":"Kötülerin saldırısından, Çevremi saran ölümcül düşmanlarımdan."},{"n":"10","t":"Yürekleri yağ bağlamış, Ağızları büyük laflar ediyor."},{"n":"11","t":"İzimi buldular, üzerime geliyorlar, Yere vurmak için gözetliyorlar."},{"n":"12","t":"Tıpkı parçalamak için sabırsızlanan bir aslan, Pusuya yatan genç bir aslan gibi."},{"n":"13","t":"Kalk, ya RAB, kes önlerini, eğ başlarını! Kılıcınla kurtar canımı kötülerden,"},{"n":"14","t":"Elinle bu insanlardan, ya RAB, Yaşam payı bu dünyada olan insanlardan. Varsın karınları vereceğin cezalara doysun, Çocukları da yiyip doysun, Artanı torunlarına kalsın!"},{"n":"15","t":"Ama ben doğruluk sayesinde yüzünü göreceğim senin, Uyanınca suretini görmeye doyacağım."}]},{"id":18,"name":"18. Mezmur (2Sa.22:1-51)Müzik şefi için - RAB'bin kulu Davut'un mezmuru - RAB kendisini bütün düşmanlarının pençesinden ve Saul'un elinden kurtardığı gün DavutRAB'be şu ezgiyi okudu:","verses":[{"n":"1","t":"Seni seviyorum, gücüm sensin, ya RAB!"},{"n":"2","t":"RAB benim kayam, sığınağım, kurtarıcımdır, Tanrım, kayam, sığınacak yerimdir, Kalkanım, güçlü kurtarıcım, korunağımdır!"},{"n":"3","t":"Övgüye değer RAB'be seslenir, Kurtulurum düşmanlarımdan."},{"n":"4","t":"Ölüm iplerine dolanmıştım, Yıkım selleri basmıştı beni,"},{"n":"5","t":"Ölüler diyarının bağları sarmıştı, Ölüm tuzakları çıkmıştı karşıma."},{"n":"6","t":"Sıkıntı içinde RAB'be yakardım,Yardıma çağırdım Tanrım'ı.Tapınağından sesimi duydu,Haykırışım kulaklarına ulaştı."},{"n":"7","t":"O zaman yeryüzü sarsılıp sallandı, Titreyip sarsıldı dağların temelleri, Çünkü RAB öfkelenmişti."},{"n":"8","t":"Burnundan duman yükseldi, Ağzından kavurucu ateş Ve korlar fışkırdı."},{"n":"9","t":"Kara buluta basarak Gökleri yarıp indi."},{"n":"10","t":"Bir Keruv'a* binip uçtu, Rüzgar kanatlar takarak hızla geldi."},{"n":"11","t":"Karanlığı örtündü, Kara bulutları kendine çardak yaptı."},{"n":"12","t":"Varlığının parıltısından, Bulutlardan dolu ve korlar savruluyordu."},{"n":"13","t":"RAB göklerden gürledi, Duyurdu sesini Yüceler Yücesi, Dolu ve alevli korlarla."},{"n":"14","t":"Savurup oklarını düşmanlarını dağıttı, Şimşek çaktırarak onları şaşkına çevirdi."},{"n":"15","t":"Denizin dibi göründü, Yeryüzünün temelleri açığa çıktı, ya RAB, Senin azarlamandan, Burnundan çıkan güçlü soluktan."},{"n":"16","t":"RAB yukarıdan elini uzatıp tuttu, Çıkardı beni derin sulardan."},{"n":"17","t":"Beni zorlu düşmanımdan, Benden nefret edenlerden kurtardı, Çünkü onlar benden güçlüydü."},{"n":"18","t":"Felaket günümde karşıma dikildiler, Ama RAB bana destek oldu."},{"n":"19","t":"Beni huzura kavuşturdu, Kurtardı, çünkü benden hoşnut kaldı."},{"n":"20","t":"RAB doğruluğumun karşılığını verdi, Beni temiz ellerime göre ödüllendirdi."},{"n":"21","t":"Çünkü RAB'bin yolunda yürüdüm, Tanrım'dan uzaklaşarak kötülük yapmadım."},{"n":"22","t":"O'nun bütün ilkelerini göz önünde tuttum, Kurallarından ayrılmadım."},{"n":"23","t":"O'nun gözünde kusursuzdum, Suç işlemekten sakındım."},{"n":"24","t":"Bu yüzden RAB beni doğruluğuma Ve gözünde pak olan ellerime göre ödüllendirdi."},{"n":"25","t":"Sadık kuluna sadakat gösterir, Kusursuz olana kusursuz davranırsın."},{"n":"26","t":"Pak olanla pak olur, Eğriye eğri davranırsın."},{"n":"27","t":"Alçakgönüllüleri kurtarır, Gururluların başını eğersin."},{"n":"28","t":"Işığımın kaynağı sensin, ya RAB, Tanrım! Karanlığımı aydınlatırsın."},{"n":"29","t":"Desteğinle akıncılara saldırır, Seninle surları aşarım, Tanrım."},{"n":"30","t":"Tanrı'nın yolu kusursuzdur, RAB'bin sözü arıdır. O kendisine sığınan herkesin kalkanıdır."},{"n":"31","t":"Var mı RAB'den başka tanrı? Tanrımız'dan başka kaya var mı?"},{"n":"32","t":"Tanrı beni güçle donatır, Yolumu kusursuz kılar."},{"n":"33","t":"Ayaklar verdi bana, geyiklerinki gibi, Doruklarda tutar beni."},{"n":"34","t":"Bana savaşmayı öğretti, Kollarımla tunç* bir yayı gereyim diye."},{"n":"35","t":"Bana zafer kalkanını bağışlarsın, Sağ elin destekler, Alçakgönüllülüğün yüceltir beni."},{"n":"36","t":"Bastığım yerleri genişletirsin, Burkulmaz bileklerim."},{"n":"37","t":"Kovalayıp yetiştim düşmanlarıma, Hepsi yok olmadan geri dönmedim."},{"n":"38","t":"Ezdim onları, kalkamaz oldular, Ayaklarımın altına serildiler."},{"n":"39","t":"Savaş için beni güçle donattın, Bana başkaldıranları önümde yere serdin."},{"n":"40","t":"Düşmanlarımı kaçmak zorunda bıraktın, Benden nefret edenleri yok ettim."},{"n":"41","t":"Feryat ettiler, ama kurtaran çıkmadı; RAB'bi çağırdılar, ama O yanıt vermedi."},{"n":"42","t":"Ezdim onları, rüzgarın savurduğu toza döndüler, Sokak çamuru gibi savurup attım."},{"n":"43","t":"Halkımın çekişmelerinden beni kurtardın, Ulusların önderi yaptın, Tanımadığım halklar bana kulluk ediyor."},{"n":"44","t":"Duyar duymaz sözümü dinlediler, Yabancılar bana yaltaklandılar."},{"n":"45","t":"Yabancıların betleri benizleri attı, Titreyerek çıktılar kalelerinden."},{"n":"46","t":"RAB yaşıyor! Kayam'a övgüler olsun! Yücelsin kurtarıcım Tanrı!"},{"n":"47","t":"O'dur öcümü alan, Halkları bana bağımlı kılan."},{"n":"48","t":"Düşmanlarımdan kurtarır, Başkaldıranlardan üstün kılar beni, Zorbaların elinden alır."},{"n":"49","t":"Bunun için uluslar arasında sana şükredeceğim, ya RAB, Adını ilahilerle öveceğim."},{"n":"50","t":"RAB kralını büyük zaferlere ulaştırır, Meshettiği* krala, Davut'a ve soyuna Sonsuza dek sevgi gösterir."}]},{"id":19,"name":"19. Mezmur Müzik şefi için - Davut'un mezmuru","verses":[{"n":"1","t":"Gökler Tanrı'nın görkemini açıklamakta, Gökkubbe ellerinin eserini duyurmakta."},{"n":"2","t":"Gün güne söz söyler, Gece geceye bilgi verir."},{"n":"3","t":"Ne söz geçer orada, ne de konuşma, Sesleri duyulmaz."},{"n":"4","t":"Ama sesleri yeryüzünü dolaşır, Sözleri dünyanın dört bucağına ulaşır. Güneş için göklerde çadır kurdu Tanrı."},{"n":"5","t":"Gerdekten çıkan güveye benzer güneş, Koşuya çıkacak atlet gibi sevinir."},{"n":"6","t":"Göğün bir ucundan çıkar, Öbür ucuna döner, Hiçbir şey gizlenmez sıcaklığından."},{"n":"7","t":"RAB'bin yasası yetkindir, cana can katar, RAB'bin buyrukları güvenilirdir, Saf adama bilgelik verir,"},{"n":"8","t":"RAB'bin kuralları doğrudur, yüreği sevindirir, RAB'bin buyrukları arıdır, gözleri aydınlatır."},{"n":"9","t":"RAB korkusu paktır, sonsuza dek kalır, RAB'bin ilkeleri gerçek, tamamen adildir."},{"n":"10","t":"Onlara altından, bol miktarda saf altından çok istekduyulur, Onlar baldan, süzme petek balından tatlıdır."},{"n":"11","t":"Uyarırlar kulunu, Onlara uyanların ödülü büyüktür."},{"n":"12","t":"Kim yanlışlarını görebilir? Bağışla göremediğim kusurlarımı,"},{"n":"13","t":"Bilerek işlenen günahlardan koru kulunu, İzin verme bana egemen olmalarına! O zaman büyük isyandan uzak, Kusursuz olurum."},{"n":"14","t":"Ağzımdan çıkan sözler, Yüreğimdeki düşünceler, Kabul görsün senin önünde, Ya RAB, kayam, kurtarıcım benim*fk*!D"},{"n":"14","t":"\"Kurtarıcım benim\": Kurtarıcı diye çevrilen İbranice\"Goel\" sözcüğü \"Yakın akraba\" anlamına gelir (bkz. Rut 2:20)."}]},{"id":20,"name":"20. Mezmur Müzik şefi için - Davut'un mezmuru","verses":[{"n":"1","t":"Sıkıntılı gününde RAB seni yanıtlasın, Yakup'un Tanrısı'nın adı seni korusun!"},{"n":"2","t":"Yardım göndersin sana kutsal yerden, Siyon'dan destek versin."},{"n":"3","t":"Bütün tahıl sunularını* anımsasın, Yakmalık sunularını* kabul etsin! *"},{"n":"4","t":"Gönlünce versin sana, Bütün tasarılarını gerçekleştirsin!"},{"n":"5","t":"O zaman zaferini sevinç çığlıklarıyla kutlayacağız, Tanrımız'ın adıyla sancaklarımızı dikeceğiz. RAB senin bütün dileklerini yerine getirsin."},{"n":"6","t":"Şimdi anladım ki, RAB meshettiği* kralı kurtarıyor, Sağ elinin kurtarıcı gücüyle Kutsal göklerinden ona yanıt veriyor."},{"n":"7","t":"Bazıları savaş arabalarına, Bazıları atlarına güvenir, Bizse Tanrımız RAB'be güveniriz."},{"n":"8","t":"Onlar çöküyor, düşüyorlar; Bizse kalkıyor, dimdik duruyoruz."},{"n":"9","t":"Ya RAB, kralı kurtar! Yanıtla bizi sana yakardığımız gün!"}]},{"id":21,"name":"21. Mezmur Müzik şefi için - Davut'un mezmuru","verses":[{"n":"1","t":"Ya RAB, kral seviniyor gösterdiğin güce. Sevinçten coşuyor verdiğin zaferle!"},{"n":"2","t":"Gönlünün istediğini verdin, Ağzından çıkan dileği geri çevirmedin. *"},{"n":"3","t":"Onu güzel armağanlarla karşıladın, Başına saf altından taç koydun."},{"n":"4","t":"Senden yaşam istedi, verdin ona: Uzun, sonsuz bir ömür."},{"n":"5","t":"Sağladığın zaferle büyük yüceliğe erişti, Onu görkem ve büyüklükle donattın."},{"n":"6","t":"Üzerine sürekli bereket yağdırdın, Varlığınla onu sevince boğdun."},{"n":"7","t":"Çünkü kral RAB'be güvenir, Yüceler Yücesi'nin sevgisi sayesinde sarsılmaz."},{"n":"8","t":"Elin bütün düşmanlarına erişecek, Sağ elin senden nefret edenlere uzanacak."},{"n":"9","t":"Öfkelendiğin an, ya RAB, Kızgın fırına döndüreceksin onları; Gazapla yutacak, Ateşle tüketeceksin."},{"n":"10","t":"Yok edeceksin çocuklarını yeryüzünden, Soylarını insanlar arasından."},{"n":"11","t":"Düzenler kursalar sana, Aldatmaya çalışsalar, Yine de başarılı olamazlar."},{"n":"12","t":"Çünkü sırtlarını döndüreceksin, Yayını yüzlerine doğru gerince."},{"n":"13","t":"Yüceliğini göster, ya RAB, gücünle! Ezgiler söyleyip ilahilerle öveceğiz kudretini."}]},{"id":22,"name":"22. Mezmur Müzik şefi için - \"Tan Geyiği\" makamında -Davut'un mezmuru","verses":[{"n":"1","t":"Tanrım, Tanrım, beni neden terk ettin? Niçin bana yardım etmekten, Haykırışıma kulak vermekten uzak duruyorsun?"},{"n":"2","t":"Ey Tanrım, gündüz sesleniyorum, yanıt vermiyorsun, Gece sesleniyorum, yine rahat yok bana."},{"n":"3","t":"Oysa sen kutsalsın, İsrail'in övgüleri üzerine taht kuran sensin."},{"n":"4","t":"Sana güvendiler atalarımız, Sana dayandılar, onları kurtardın."},{"n":"5","t":"Sana yakarıp kurtuldular, Sana güvendiler, aldanmadılar."},{"n":"6","t":"Ama ben insan değil, toprak kurduyum, İnsanlar beni küçümsüyor, halk hor görüyor."},{"n":"7","t":"Beni gören herkes alay ediyor, Sırıtıp baş sallayarak diyorlar ki,"},{"n":"8","t":"\"Sırtını RAB'be dayadı, kurtarsın bakalım onu, Madem onu seviyor, yardım etsin!\""},{"n":"9","t":"Oysa beni ana rahminden çıkaran, Ana kucağındayken sana güvenmeyi öğreten sensin."},{"n":"10","t":"Doğuşumdan beri sana teslim edildim, Ana rahminden beri Tanrım sensin."},{"n":"11","t":"Benden uzak durma! Çünkü sıkıntı yanıbaşımda, Yardım edecek kimse yok."},{"n":"12","t":"Boğalar kuşatıyor beni, Azgın Başan boğaları sarıyor çevremi."},{"n":"13","t":"Kükreyerek avını parçalayan aslanlar gibi Ağızlarını açıyorlar bana."},{"n":"14","t":"Su gibi dökülüyorum, Bütün kemiklerim oynaklarından çıkıyor; Yüreğim balmumu gibi içimde eriyor."},{"n":"15","t":"Gücüm çömlek parçası gibi kurudu, Dilim damağıma yapışıyor; Beni ölüm toprağına yatırdın."},{"n":"16","t":"Köpekler kuşatıyor beni, Kötüler sürüsü çevremi sarıyor, Ellerimi, ayaklarımı deliyorlar."},{"n":"17","t":"Bütün kemiklerimi sayar oldum, Gözlerini dikmiş, bana bakıyorlar."},{"n":"18","t":"Giysilerimi aralarında paylaşıyor, Elbisem için kura çekiyorlar."},{"n":"19","t":"Ama sen, ya RAB, uzak durma; Ey gücüm benim, yardımıma koş!"},{"n":"20","t":"Canımı kılıçtan, Biricik hayatımı köpeğin pençesinden kurtar!"},{"n":"21","t":"Kurtar beni aslanın ağzından, Yaban öküzlerinin boynuzundan. Yanıt ver bana!"},{"n":"22","t":"Adını kardeşlerime duyurayım, Topluluğun ortasında sana övgüler sunayım:"},{"n":"23","t":"Ey sizler, RAB'den korkanlar, O'na övgüler sunun! Ey Yakup soyu, O'nu yüceltin! Ey İsrail soyu, O'na saygı gösterin!"},{"n":"24","t":"Çünkü O mazlumun çektiği sıkıntıyı hafife almadı, Ondan tiksinmedi, yüz çevirmedi; Kendisini yardıma çağırdığında ona kulak verdi."},{"n":"25","t":"Övgü konum sen olacaksın büyük toplulukta, Senden korkanların önünde yerine getireceğim adaklarımı."},{"n":"26","t":"Yoksullar yiyip doyacak, RAB'be yönelenler O'na övgü sunacak. Sonsuza dek ömrünüz tükenmesin!"},{"n":"27","t":"Yeryüzünün dört bucağı anımsayıp RAB'be dönecek, Ulusların bütün soyları O'nun önünde yere kapanacak."},{"n":"28","t":"Çünkü egemenlik RAB'bindir, Ulusları O yönetir."},{"n":"29","t":"Yeryüzündeki bütün zenginler doyacak Ve O'nun önünde yere kapanacak, Toprağa gidenler, Ölümlerine engel olamayanlar, Eğilecekler O'nun önünde."},{"n":"30","t":"Gelecek kuşaklar O'na kulluk edecek, Rab yeni kuşaklara anlatılacak."},{"n":"31","t":"O'nun kurtarışını, \"Rab yaptı bunları\" diyerek, Henüz doğmamış bir halka duyuracaklar."}]},{"id":23,"name":"23. Mezmur Davut'un mezmuru","verses":[{"n":"1","t":"RAB çobanımdır, Eksiğim olmaz."},{"n":"2","t":"Beni yemyeşil çayırlarda yatırır, Sakin suların kıyısına götürür."},{"n":"3","t":"İçimi tazeler, Adı uğruna bana doğru yollarda öncülük eder."},{"n":"4","t":"Karanlık ölüm vadisinden geçsem bile, Kötülükten korkmam. Çünkü sen benimlesin. Çomağın, değneğin güven verir bana."},{"n":"5","t":"Düşmanlarımın önünde bana sofra kurarsın, Başıma yağ sürersin, Kâsem taşıyor."},{"n":"6","t":"Ömrüm boyunca yalnız iyilik ve sevgi izleyecek beni, Hep RAB'bin evinde oturacağım."}]},{"id":24,"name":"24. Mezmur Davut'un mezmuru","verses":[{"n":"1","t":"RAB'bindir yeryüzü ve içindeki her şey, Dünya ve üzerinde yaşayanlar;"},{"n":"2","t":"Çünkü O'dur denizler üzerinde onu kuran, Sular üzerinde durduran."},{"n":"3","t":"RAB'bin dağına kim çıkabilir, Kutsal yerinde kim durabilir?"},{"n":"4","t":"Elleri pak, yüreği temiz olan, Gönlünü putlara kaptırmayan, Yalan yere ant içmeyen."},{"n":"5","t":"RAB kutsar böylesini, Kurtarıcısı Tanrı aklar."},{"n":"6","t":"O'na yönelenler, Yakup'un Tanrısı'nın yüzünü arayanlar İşte böyledir. *"},{"n":"7","t":"Kaldırın başınızı, ey kapılar! Açılın, ey eski kapılar! Yüce Kral girsin içeri!"},{"n":"8","t":"Kimdir bu Yüce Kral? O RAB'dir, güçlü ve yiğit, Savaşta yiğit olan RAB."},{"n":"9","t":"Kaldırın başınızı, ey kapılar! Açılın, ey eski kapılar! Yüce Kral girsin içeri!"},{"n":"10","t":"Kimdir bu Yüce Kral? Her Şeye Egemen RAB'dir bu Yüce Kral!"}]},{"id":25,"name":"25. Mezmur Davut'un mezmuru","verses":[{"n":"1","t":"Ya RAB, bütün varlığımla sana yaklaşıyorum,"},{"n":"2","t":"Ey Tanrım, sana güveniyorum, utandırma beni, Düşmanlarım zafer kahkahası atmasın!"},{"n":"3","t":"Sana umut bağlayan hiç kimse utanca düşmez; Nedensiz hainlik edenler utanır."},{"n":"4","t":"Ya RAB, yollarını bana öğret, Yönlerini bildir."},{"n":"5","t":"Bana gerçek yolunda öncülük et, eğit beni; Çünkü beni kurtaran Tanrı sensin. Bütün gün umudum sende."},{"n":"6","t":"Ya RAB, sevecenliğini ve sevgini anımsa; Çünkü onlar öncesizlikten beri aynıdır."},{"n":"7","t":"Gençlik günahlarımı, isyanlarımı anımsama, Sevgine göre anımsa beni, Çünkü sen iyisin, ya RAB."},{"n":"8","t":"RAB iyi ve doğrudur, Onun için günahkârlara yol gösterir."},{"n":"9","t":"Alçakgönüllülere adalet yolunda öncülük eder, Kendi yolunu öğretir onlara."},{"n":"10","t":"RAB'bin bütün yolları sevgi ve sadakate dayanır Antlaşmasındaki buyruklara uyanlar için."},{"n":"11","t":"Ya RAB, adın uğruna Suçumu bağışla, çünkü suçum büyük."},{"n":"12","t":"Kim RAB'den korkarsa, RAB ona seçeceği yolu gösterir."},{"n":"13","t":"Gönenç içinde yaşayacak o insan, Soyu ülkeyi sahiplenecek."},{"n":"14","t":"RAB kendisinden korkanlarla paylaşır sırrını, Onlara açıklar antlaşmasını."},{"n":"15","t":"Gözlerim hep RAB'dedir, Çünkü ayaklarımı ağdan O çıkarır."},{"n":"16","t":"Halime bak, lütfet bana; Çünkü garip ve mazlumum."},{"n":"17","t":"Yüreğimdeki sıkıntılar artıyor, Kurtar beni dertlerimden!"},{"n":"18","t":"Üzüntüme, acılarıma bak, Bütün günahlarımı bağışla!"},{"n":"19","t":"Düşmanlarıma bak, ne kadar çoğaldılar, Nasıl da benden nefret ediyorlar!"},{"n":"20","t":"Canımı koru, kurtar beni! Hayal kırıklığına uğratma, çünkü sana sığınıyorum!"},{"n":"21","t":"Dürüstlük, doğruluk korusun beni, Çünkü umudum sendedir."},{"n":"22","t":"Ey Tanrı, kurtar İsrail'i Bütün sıkıntılarından!"}]},{"id":26,"name":"26. Mezmur Davut'un mezmuru","verses":[{"n":"1","t":"Beni haklı çıkar, ya RAB, Çünkü dürüst bir yaşam sürdüm; Sarsılmadan RAB'be güvendim."},{"n":"2","t":"Dene beni, ya RAB, sına; Duygularımı, düşüncelerimi yokla."},{"n":"3","t":"Çünkü sevgini hep göz önünde tutuyor, Senin gerçeğini yaşıyorum ben."},{"n":"4","t":"Yalancılarla oturmam, İkiyüzlülerin suyuna gitmem."},{"n":"5","t":"Kötülük yapanlar topluluğundan nefret ederim, Fesatçıların arasına girmem."},{"n":"6","t":"Suçsuzluğumu göstermek için ellerimi yıkar, Sunağının çevresinde dönerim, ya RAB,"},{"n":"7","t":"Yüksek sesle şükranımı duyurmak Ve bütün harikalarını anlatmak için."},{"n":"8","t":"Severim, ya RAB, yaşadığın evi, Görkeminin bulunduğu yeri."},{"n":"9","t":"Günahkârların, Eli kanlı adamların yanısıra canımı alma."},{"n":"10","t":"Onların elleri kötülük aletidir, Sağ elleri rüşvet doludur."},{"n":"11","t":"Ama ben dürüst yaşarım, Kurtar beni, lütfet bana!"},{"n":"12","t":"Ayağım emin yerde duruyor. Topluluk içinde sana övgüler sunacağım, ya RAB."}]},{"id":27,"name":"27. Mezmur Davut'un mezmuru","verses":[{"n":"1","t":"RAB benim ışığım, kurtuluşumdur, Kimseden korkmam. RAB yaşamımın kalesidir, Kimseden yılmam."},{"n":"2","t":"Hasımlarım, düşmanlarım olan kötüler, Beni yutmak için üzerime gelirken Tökezleyip düşerler."},{"n":"3","t":"Karşımda bir ordu konaklasa, Kılım kıpırdamaz, Bana karşı savaş açılsa, Yine güvenimi yitirmem."},{"n":"4","t":"RAB'den tek dileğim, tek isteğim şu: RAB'bin güzelliğini seyretmek, Tapınağında O'na hayran olmak için Ömrümün bütün günlerini O'nun evinde geçirmek."},{"n":"5","t":"Çünkü O kötü günde beni çardağında gizleyecek, Çadırının emin yerinde saklayacak, Yüksek bir kaya üzerine çıkaracak beni."},{"n":"6","t":"O zaman çevremi saran düşmanlarıma karşı Başım yukarı kalkacak, Sevinçle haykırarak kurbanlar sunacağım O'nun çadırında, O'nu ezgilerle, ilahilerle öveceğim."},{"n":"7","t":"Sana yakarıyorum, ya RAB, kulak ver sesime, Lütfet, yanıtla beni!"},{"n":"8","t":"Ya RAB, içimden bir ses duydum: \"Yüzümü ara!\" dedin, İşte yüzünü arıyorum."},{"n":"9","t":"Yüzünü benden gizleme, Kulunu öfkeyle geri çevirme! Bana hep yardımcı oldun; Bırakma, terk etme beni, Ey beni kurtaran Tanrı!"},{"n":"10","t":"Annemle babam beni terk etseler bile, RAB beni kabul eder."},{"n":"11","t":"Ya RAB, yolunu öğret bana, Düşmanlarıma karşı Düz yolda bana öncülük et."},{"n":"12","t":"Beni hasımlarımın keyfine bırakma, Çünkü yalancı tanıklar dikiliyor karşıma, Ağızları şiddet saçıyor."},{"n":"13","t":"Yaşam diyarında RAB'bin iyiliğini göreceğimden kuşkum yok."},{"n":"14","t":"Umudunu RAB'be bağla, Güçlü ve yürekli ol; Umudunu RAB'be bağla!"}]},{"id":28,"name":"28. MezmurDavut'un mezmuru","verses":[{"n":"1","t":"Ya RAB, sana yakarıyorum, Kayam benim, kulak tıkama sesime; Çünkü sen sessiz kalırsan, Ölüm çukuruna inen ölülere dönerim ben."},{"n":"2","t":"Seni yardıma çağırdığımda, Ellerimi kutsal konutuna doğru açtığımda, Kulak ver yalvarışlarıma."},{"n":"3","t":"Beni kötülerle, haksızlık yapanlarla Aynı kefeye koyup cezalandırma. Onlar komşularıyla dostça konuşur, Ama yüreklerinde kötülük beslerler."},{"n":"4","t":"Eylemlerine, yaptıkları kötülüklere göre onları yanıtla; Yaptıklarının, hak ettiklerinin karşılığını ver."},{"n":"5","t":"Onlar RAB'bin yaptıklarına, Ellerinin eserine önem vermezler; Bu yüzden RAB onları yıkacak, Bir daha ayağa kaldırmayacak."},{"n":"6","t":"RAB'be övgüler olsun! Çünkü yalvarışımı duydu."},{"n":"7","t":"RAB benim gücüm, kalkanımdır, O'na yürekten güveniyor ve yardım görüyorum. Yüreğim coşuyor, Ezgilerimle O'na şükrediyorum."},{"n":"8","t":"RAB halkının gücüdür, Meshettiği* kralın zafer kalesidir."},{"n":"9","t":"Halkını kurtar, kendi halkını kutsa; Çobanlık et onlara, sürekli destek ol!"}]},{"id":29,"name":"29. MezmurDavut'un mezmuru","verses":[{"n":"1","t":"Ey ilahi varlıklar, RAB'bi övün, RAB'bin gücünü, yüceliğini övün,"},{"n":"2","t":"RAB'bin görkemini adına yaraşır biçimde övün, Kutsal giysiler içinde RAB'be tapının!"},{"n":"3","t":"RAB'bin sesi sulara hükmediyor, Yüce Tanrı gürlüyor, RAB engin sulara hükmediyor."},{"n":"4","t":"RAB'bin sesi güçlüdür, RAB'bin sesi görkemlidir."},{"n":"5","t":"RAB'bin sesi sedir ağaçlarını kırar, Lübnan sedirlerini parçalar."},{"n":"6","t":"Lübnan'ı buzağı gibi, Siryon Dağı'nı yabanıl öküz yavrusu gibi sıçratır."},{"n":"7","t":"RAB'bin sesi şimşek gibi çakar,"},{"n":"8","t":"RAB'bin sesi çölü titretir, RAB Kadeş Çölü'nü sarsar."},{"n":"9","t":"RAB'bin sesi geyikleri doğurtur*fl*, Ormanları çıplak bırakır. O'nun tapınağında herkes \"Yücesin!\" diye haykırır.D"},{"n":"9","t":"\"Geyikleri doğurtur\" ya da \"Yabanıl fıstık ağaçlarını eğer\"."},{"n":"10","t":"RAB tufan üstünde taht kurdu, O sonsuza dek kral kalacak."},{"n":"11","t":"RAB halkına güç verir, Halkını esenlikle kutsar!"}]},{"id":30,"name":"30. MezmurTapınak adanırken söylenen bir ilahi -Davut'un mezmuru","verses":[{"n":"1","t":"Seni yüceltmek istiyorum, ya RAB, Çünkü beni kurtardın, Düşmanlarımı bana güldürmedin."},{"n":"2","t":"Ya RAB Tanrım, Sana yakardım, bana şifa verdin."},{"n":"3","t":"Ya RAB, beni ölüler diyarından çıkardın, Yaşam verdin bana, ölüm çukuruna düşürmedin."},{"n":"4","t":"Ey RAB'bin sadık kulları, O'nu ilahilerle övün, Kutsallığını anarak O'na şükredin."},{"n":"5","t":"Çünkü öfkesi bir an sürer, Lütfu ise bir ömür; Gözyaşlarınız belki bir gece akar, Ama sabahla sevinç doğar."},{"n":"6","t":"Huzur duyunca dedim ki, \"Asla sarsılmayacağım!\""},{"n":"7","t":"Ya RAB, lütfunla beni güçlü bir dağ gibi Sarsılmaz kıldın; Ama sen yüzünü gizleyince, Dehşete düştüm."},{"n":"8","t":"Ya RAB, sana sesleniyorum, Rab'be yalvarıyorum:"},{"n":"9","t":"\"Ne yararı olur senin için dökülen kanımın, Ölüm çukuruna inersem? Toprak sana övgüler sunar mı, Senin sadakatini ilan eder mi?"},{"n":"10","t":"Dinle, ya RAB, acı bana; Yardımcım ol, ya RAB!\""},{"n":"11","t":"Yasımı şenliğe döndürdün, Çulumu çıkarıp beni sevinçle kuşattın."},{"n":"12","t":"Öyle ki, gönlüm seni ilahilerle övsün, susmasın! Ya RAB Tanrım, sana sürekli şükredeceğim."}]},{"id":31,"name":"31. Mezmur(Mez.71:1-3)Müzik şefi için - Davut'un mezmuru","verses":[{"n":"1","t":"Ya RAB, sana sığınıyorum. Utandırma beni hiçbir zaman! Adaletinle kurtar beni!"},{"n":"2","t":"Kulak ver bana, Çabuk yetiş, kurtar beni; Bir kaya ol bana sığınmam için, Güçlü bir kale ol kurtulmam için!"},{"n":"3","t":"Madem kayam ve kalem sensin, Öncülük et, yol göster bana Kendi adın uğruna."},{"n":"4","t":"Bana kurdukları tuzaktan uzak tut beni, Çünkü sığınağım sensin."},{"n":"5","t":"Ruhumu ellerine bırakıyorum, Ya RAB, sadık Tanrı, kurtar beni."},{"n":"6","t":"Değersiz putlara bel bağlayanlardan tiksinirim, RAB'be güvenirim ben."},{"n":"7","t":"Sadakatinden ötürü sevinip coşacağım, Çünkü düşkün halimi görüyor, Çektiğim sıkıntıları biliyorsun,"},{"n":"8","t":"Beni düşman eline düşürmedin, Bastığım yerleri genişlettin."},{"n":"9","t":"Acı bana, ya RAB, sıkıntıdayım, Üzüntü gözümü, canımı, içimi kemiriyor."},{"n":"10","t":"Ömrüm acıyla, Yıllarım iniltiyle tükeniyor, Suçumdan ötürü gücüm zayıflıyor, Kemiklerim eriyor."},{"n":"11","t":"Düşmanlarım yüzünden rezil oldum, Özellikle komşularıma. Tanıdıklarıma dehşet salar oldum; Beni sokakta görenler benden kaçar oldu."},{"n":"12","t":"Gönülden çıkmış bir ölü gibi unutuldum, Kırılmış bir çömleğe döndüm."},{"n":"13","t":"Birçoğunun fısıldaştığını duyuyorum, Her yer dehşet içinde, Bana karşı anlaştılar, Canımı almak için düzen kurdular."},{"n":"14","t":"Ama ben sana güveniyorum, ya RAB, \"Tanrım sensin!\" diyorum."},{"n":"15","t":"Hayatım senin elinde, Kurtar beni düşmanlarımın pençesinden, Ardıma düşenlerden."},{"n":"16","t":"Yüzün kulunu aydınlatsın, Sevgi göster, kurtar beni!"},{"n":"17","t":"Utandırma beni, ya RAB, sana sesleniyorum; Kötüler utansın, ölüler diyarında sesleri kesilsin."},{"n":"18","t":"Sussun o yalancı dudaklar; Doğru insana karşı Gururla, tepeden bakarak, Küçümseyerek konuşan dudaklar."},{"n":"19","t":"İyiliğin ne büyüktür, ya RAB, Onu senden korkanlar için saklarsın, Herkesin gözü önünde, Sana sığınanlara iyi davranırsın."},{"n":"20","t":"İnsanların düzenlerine karşı, Koruyucu huzurunla üzerlerine kanat gerersin; Saldırgan dillere karşı Onları çardağında gizlersin."},{"n":"21","t":"RAB'be övgüler olsun, Kuşatılmış bir kentte Sevgisini bana harika biçimde gösterdi."},{"n":"22","t":"Telaş içinde demiştim ki, \"Huzurundan atıldım!\" Ama yardıma çağırınca seni, Yalvarışımı işittin."},{"n":"23","t":"RAB'bi sevin, ey O'nun sadık kulları! RAB kendisine bağlı olanları korur, Büyüklenenlerin ise tümüyle hakkından gelir."},{"n":"24","t":"Ey RAB'be umut bağlayanlar, Güçlü ve yürekli olun!"}]},{"id":32,"name":"32. MezmurDavut'un mezmuru - Maskil*fm*","verses":[{"n":"1","t":"Ne mutlu isyanı bağışlanan, Günahı örtülen insana!D Not \"Maskil\": Anlamı tam olarak bilinmeyen bir müzik veyaedebiyat terimi. \"Didaktik şiir\" anlamına gelebilir."},{"n":"2","t":"Suçu RAB tarafından sayılmayan, Ruhunda hile bulunmayan insana ne mutlu!"},{"n":"3","t":"Sustuğum sürece Kemiklerim eridi, Gün boyu inlemekten."},{"n":"4","t":"Çünkü gece gündüz Elin üzerimde ağırlaştı. Dermanım tükendi yaz sıcağında gibi. *"},{"n":"5","t":"Günahımı açıkladım sana, Suçumu gizlemedim. \"RAB'be isyanımı itiraf edeceğim\" deyince, Günahımı, suçumu bağışladın."},{"n":"6","t":"Bu nedenle her sadık kulun Ulaşılır olduğun zaman sana dua etsin. Engin sular taşsa bile ona erişemez."},{"n":"7","t":"Sığınağım sensin, Beni sıkıntıdan korur, Çevremi kurtuluş ilahileriyle kuşatırsın."},{"n":"8","t":"Eğiteceğim seni, gideceğin yolu göstereceğim, Öğüt vereceğim sana, Gözüm sendedir."},{"n":"9","t":"At ya da katır gibi anlayışsız olmayın; Onları idare etmek için gem ve dizgin gerekir, Yoksa sana yaklaşmazlar."},{"n":"10","t":"Kötülerin acısı çoktur, Ama RAB'be güvenenleri O'nun sevgisi kuşatır."},{"n":"11","t":"Ey doğru insanlar, sevinç kaynağınız RAB olsun, coşun; Ey yüreği temiz olanlar, Hepiniz sevinç çığlıkları atın!"}]},{"id":33,"name":"33. Mezmur","verses":[{"n":"1","t":"Ey doğru insanlar, RAB'be sevinçle haykırın! Dürüstlere O'nu övmek yaraşır."},{"n":"2","t":"Lir çalarak RAB'be şükredin, On telli çenk eşliğinde O'nu ilahilerle övün."},{"n":"3","t":"O'na yeni bir ezgi söyleyin, Sevinç çığlıklarıyla sazınızı konuşturun."},{"n":"4","t":"Çünkü RAB'bin sözü doğrudur, Her işi sadakatle yapar."},{"n":"5","t":"Doğruluğu, adaleti sever, RAB'bin sevgisi yeryüzünü doldurur."},{"n":"6","t":"Gökler RAB'bin sözüyle, Gök cisimleri ağzından çıkan solukla yaratıldı."},{"n":"7","t":"Deniz sularını bir araya toplar, Engin suları ambarlara depolar."},{"n":"8","t":"Bütün yeryüzü RAB'den korksun, Dünyada yaşayan herkes O'na saygı duysun."},{"n":"9","t":"Çünkü O söyleyince, her şey var oldu; O buyurunca, her şey belirdi."},{"n":"10","t":"RAB ulusların planlarını bozar, Halkların tasarılarını boşa çıkarır."},{"n":"11","t":"Ama RAB'bin planları sonsuza dek sürer, Yüreğindeki tasarılar kuşaklar boyunca değişmez."},{"n":"12","t":"Ne mutlu Tanrısı RAB olan ulusa, Kendisi için seçtiği halka!"},{"n":"13","t":"RAB göklerden bakar, Bütün insanları görür."},{"n":"14","t":"Oturduğu yerden, Yeryüzünde yaşayan herkesi gözler."},{"n":"15","t":"Herkesin yüreğini yaratan, Yaptıkları her şeyi tartan O'dur."},{"n":"16","t":"Ne büyük ordularıyla zafer kazanan kral var, Ne de büyük gücüyle kurtulan yiğit."},{"n":"17","t":"Zafer için at boş bir umuttur, Büyük gücüne karşın kimseyi kurtaramaz."},{"n":"18","t":"Ama RAB'bin gözü kendisinden korkanların, Sevgisine umut bağlayanların üzerindedir;"},{"n":"19","t":"Böylece onları ölümden kurtarır, Kıtlıkta yaşamalarını sağlar."},{"n":"20","t":"Umudumuz RAB'dedir, Yardımcımız, kalkanımız O'dur."},{"n":"21","t":"O'nda sevinç bulur yüreğimiz, Çünkü O'nun kutsal adına güveniriz."},{"n":"22","t":"Madem umudumuz sende, Sevgin üzerimizde olsun, ya RAB!"}]},{"id":34,"name":"34. MezmurDavut'un mezmuruAvimelek'in önünde kendini deli gösterip kovulduğu, gittiği zaman","verses":[{"n":"1","t":"Her zaman RAB'be övgüler sunacağım, Övgüsü dilimden düşmeyecek."},{"n":"2","t":"RAB'le övünürüm, Mazlumlar işitip sevinsin!"},{"n":"3","t":"Benimle birlikte RAB'bin büyüklüğünü duyurun, Adını birlikte yüceltelim."},{"n":"4","t":"RAB'be yöneldim, yanıt verdi bana, Bütün korkularımdan kurtardı beni."},{"n":"5","t":"O'na bakanların yüzü ışıl ışıl parlar, Yüzleri utançtan kızarmaz."},{"n":"6","t":"Bu mazlum yakardı, RAB duydu, Bütün sıkıntılarından kurtardı onu."},{"n":"7","t":"RAB'bin meleği O'ndan korkanların çevresine ordugah kurar, Kurtarır onları."},{"n":"8","t":"Tadın da görün, RAB ne iyidir, Ne mutlu O'na sığınan adama!"},{"n":"9","t":"RAB'den korkun, ey O'nun kutsalları, Çünkü O'ndan korkanın eksiği olmaz."},{"n":"10","t":"Genç aslanlar bile aç ve muhtaç olur; Ama RAB'be yönelenlerden hiçbir iyilik esirgenmez."},{"n":"11","t":"Gelin, ey çocuklar, dinleyin beni: Size RAB korkusunu öğreteyim."},{"n":"12","t":"Kim yaşamdan zevk almak, İyi günler görmek istiyorsa,"},{"n":"13","t":"Dilini kötülükten, Dudaklarını yalandan uzak tutsun."},{"n":"14","t":"Kötülükten sakının, iyilik yapın; Esenliği amaçlayın, ardınca gidin."},{"n":"15","t":"RAB'bin gözleri doğru kişilerin üzerindedir, Kulakları onların yakarışına açıktır."},{"n":"16","t":"RAB kötülük yapanlara karşıdır, Onların anısını yeryüzünden siler."},{"n":"17","t":"Doğrular yakarır, RAB duyar; Bütün sıkıntılarından kurtarır onları."},{"n":"18","t":"RAB gönlü kırıklara yakındır, Ruhu ezginleri kurtarır."},{"n":"19","t":"Doğrunun dertleri çoktur, Ama RAB hepsinden kurtarır onu."},{"n":"20","t":"Bütün kemiklerini korur, Hiçbiri kırılmaz."},{"n":"21","t":"Kötü insanın sonu kötülükle biter, Cezasını bulur doğrulardan nefret edenler."},{"n":"22","t":"RAB kullarını kurtarır, O'na sığınanların hiçbiri ceza görmez."}]},{"id":35,"name":"35. MezmurDavut'un mezmuru","verses":[{"n":"1","t":"Ya RAB, benimle uğraşanlarla sen uğraş, Benimle savaşanlarla sen savaş!"},{"n":"2","t":"Al küçük kalkanla büyük kalkanı,Yardımıma koş!"},{"n":"3","t":"Kaldır mızrağını, kargını beni kovalayanlara, \"Seni ben kurtarırım\" de bana!"},{"n":"4","t":"Canıma kastedenler utanıp rezil olsun! Utançla geri çekilsin bana kötülük düşünenler!"},{"n":"5","t":"Rüzgarın sürüklediği saman çöpüne dönsünler, RAB'bin meleği artlarına düşsün!"},{"n":"6","t":"Karanlık ve kaygan olsun yolları, RAB'bin meleği kovalasın onları!"},{"n":"7","t":"Madem neden yokken bana gizli ağlar kurdular, Nedensiz çukur kazdılar,"},{"n":"8","t":"Başlarına habersiz felaket gelsin, Gizledikleri ağa kendileri tutulsun, Felakete uğrasınlar."},{"n":"9","t":"O zaman RAB'de sevinç bulacağım, Beni kurtardığı için coşacağım."},{"n":"10","t":"Bütün varlığımla şöyle diyeceğim: \"Senin gibisi var mı, ya RAB, Mazlumu zorbanın elinden, Mazlumu ve yoksulu soyguncudan kurtaran?\""},{"n":"11","t":"Kötü niyetli tanıklar türüyor, Bilmediğim konuları soruyorlar."},{"n":"12","t":"İyiliğime karşı kötülük ediyor, Yalnızlığa itiyorlar beni."},{"n":"13-14","t":"Oysa onlar hastalanınca ben çula sarınır, Oruç* tutup alçakgönüllü olurdum. Duam yanıtsız kalınca, Bir dost, bir kardeş yitirmiş gibi dolaşırdım. Kederden belim bükülürdü, Annesi için yas tutan biri gibi."},{"n":"15","t":"Ama ben sendeleyince toplanıp sevindiler, Toplandı bana karşı tanımadığım alçaklar, Durmadan didiklediler beni."},{"n":"16","t":"Tanrıtanımaz, alaycı soytarılar gibi, Diş gıcırdattılar bana."},{"n":"17","t":"Ne zamana dek seyirci kalacaksın, ya Rab? Kurtar canımı bunların saldırısından, Hayatımı bu genç aslanlardan!"},{"n":"18","t":"Büyük toplantıda sana şükürler sunacağım, Kalabalığın ortasında sana övgüler dizeceğim."},{"n":"19","t":"Sevinmesin boş yere bana düşman olanlar, Göz kırpmasınlar birbirlerine Nedensiz benden nefret edenler."},{"n":"20","t":"Çünkü barış sözünü etmez onlar, Kurnazca düzen kurarlar ülkenin sakin insanlarına."},{"n":"21","t":"Beni suçlamak için ağızlarını ardına kadar açtılar: \"Oh! Oh!\" diyorlar, \"İşte kendi gözümüzle gördük yaptıklarını!\""},{"n":"22","t":"Olup biteni sen de gördün, ya RAB, sessiz kalma, Ya Rab, benden uzak durma!"},{"n":"23","t":"Uyan, kalk savun beni, Uğraş hakkım için, ey Tanrım ve Rab'bim!"},{"n":"24","t":"Adaletin uyarınca haklı çıkar beni, ya RAB, Tanrım benim! Gülmesinler halime!"},{"n":"25","t":"Demesinler içlerinden: \"Oh! İşte buydu dileğimiz!\", Konuşmasınlar ardımdan: \"Yedik başını!\" diye."},{"n":"26","t":"Utansın kötü halime sevinenler, Kızarsın yüzleri hepsinin; Gururla karşıma dikilenler Utanca, rezalete bürünsün."},{"n":"27","t":"Benim haklı çıkmamı isteyenler, Sevinç çığlıkları atıp coşsunlar; Şöyle desinler sürekli: \"Kulunun esenliğinden hoşlanan RAB yücelsin!\""},{"n":"28","t":"O zaman gün boyu adaletin, Övgülerin dilimden düşmeyecek."}]},{"id":36,"name":"36. MezmurMüzik şefi için - RAB'bin kulu Davut'un mezmuru","verses":[{"n":"1","t":"Günah fısıldar kötü insana, Yüreğinin dibinden: Tanrı korkusu yoktur onda."},{"n":"2","t":"Kendini öyle beğenmiş ki, Suçunu görmez, ondan tiksinmez."},{"n":"3","t":"Ağzından kötülük ve yalan akar, Akıllanmaktan, iyilik yapmaktan vazgeçmiş."},{"n":"4","t":"Yatağında bile fesat düşünür, Olumsuz yolda direnir, reddetmez kötülüğü."},{"n":"5","t":"Ya RAB, sevgin göklere, Sadakatin gökyüzüne erişir."},{"n":"6","t":"Doğruluğun ulu dağlara benzer, Adaletin uçsuz bucaksız enginlere. İnsanı da, hayvanı da koruyan sensin, ya RAB."},{"n":"7","t":"Sevgin ne değerli, ey Tanrı! Kanatlarının gölgesine sığınır insanoğlu."},{"n":"8","t":"Evindeki bolluğa doyarlar, Zevklerinin ırmağından içirirsin onlara."},{"n":"9","t":"Çünkü yaşam kaynağı sensin, Senin ışığınla aydınlanırız."},{"n":"10","t":"Sürekli göster Seni tanıyanlara sevgini, Yüreği temiz olanlara doğruluğunu."},{"n":"11","t":"Gururlunun ayağı bana varmasın, Kötülerin eli beni kovmasın."},{"n":"12","t":"Kötülük yapanlar oracıkta düştüler, Yıkıldılar, kalkamazlar artık."}]},{"id":37,"name":"37. MezmurDavut'un mezmuru","verses":[{"n":"1","t":"Kötülük edenlere kızıp üzülme, Suç işleyenlere özenme!"},{"n":"2","t":"Çünkü onlar ot gibi hemen solacak, Yeşil bitki gibi kuruyup gidecek."},{"n":"3","t":"Sen RAB'be güven, iyilik yap, Ülkede otur, sadakatle çalış."},{"n":"4","t":"RAB'den zevk al, O senin içindeki istekleri yerine getirecektir."},{"n":"5","t":"Her şeyi RAB'be bırak, O'na güven, O gerekeni yapar."},{"n":"6","t":"O senin doğruluğunu ışık gibi, Hakkını öğle güneşi gibi Aydınlığa çıkarır."},{"n":"7","t":"RAB'bin önünde sakin dur, sabırla bekle; Kızıp üzülme işi yolunda olanlara, Kötü amaçlarına kavuşanlara."},{"n":"8","t":"Kızmaktan kaçın, bırak öfkeyi, Üzülme, yalnız kötülüğe sürükler bu seni."},{"n":"9","t":"Çünkü kötülerin kökü kazınacak, Ama RAB'be umut bağlayanlar ülkeyi miras alacak."},{"n":"10","t":"Yakında kötünün sonu gelecek, Yerini arasan da bulunmayacak."},{"n":"11","t":"Ama alçakgönüllüler ülkeyi miras alacak, Derin bir huzurun zevkini tadacak."},{"n":"12","t":"Kötü insan doğru insana düzen kurar, Diş gıcırdatır."},{"n":"13","t":"Ama Rab kötüye güler, Çünkü bilir onun sonunun geldiğini."},{"n":"14","t":"Kılıç çekti kötüler, yaylarını gerdi, Mazlumu, yoksulu yıkmak, Doğru yolda olanları öldürmek için."},{"n":"15","t":"Ama kılıçları kendi yüreklerine saplanacak, Yayları kırılacak."},{"n":"16","t":"Doğrunun azıcık varlığı, Pek çok kötünün servetinden iyidir."},{"n":"17","t":"Çünkü kötülerin gücü kırılacak, Ama doğrulara RAB destek olacak."},{"n":"18","t":"RAB yetkinlerin her gününü gözetir, Onların mirası sonsuza dek sürecek."},{"n":"19","t":"Kötü günde utanmayacaklar, Kıtlıkta karınları doyacak."},{"n":"20","t":"Ama kötüler yıkıma uğrayacak; RAB'bin düşmanları kır çiçekleri gibi kuruyup gidecek, Duman gibi dağılıp yok olacak."},{"n":"21","t":"Kötüler ödünç alır, geri vermez; Doğrularsa cömertçe verir."},{"n":"22","t":"RAB'bin kutsadığı insanlar ülkeyi miras alacak, Lanetlediği insanların kökü kazınacak."},{"n":"23","t":"RAB insana sağlam adım attırır, İnsanın yolundan hoşnut olursa."},{"n":"24","t":"Düşse bile yıkılmaz insan, Çünkü elinden tutan RAB'dir."},{"n":"25","t":"Gençtim, ömrüm tükendi, Ama hiç görmedim doğru insanın terk edildiğini, Soyunun ekmek dilendiğini."},{"n":"26","t":"O hep cömertçe ödünç verir, Soyu kutsanır."},{"n":"27","t":"Kötülükten kaç, iyilik yap; Sonsuz yaşama kavuşursun."},{"n":"28","t":"Çünkü RAB doğruyu sever, Sadık kullarını terk etmez. Onlar sonsuza dek korunacak, Kötülerinse kökü kazınacak."},{"n":"29","t":"Doğrular ülkeyi miras alacak, Orada sonsuza dek yaşayacak."},{"n":"30","t":"Doğrunun ağzından bilgelik akar, Dilinden adalet damlar."},{"n":"31","t":"Tanrısı'nın yasası yüreğindedir, Ayakları kaymaz."},{"n":"32","t":"Kötü, doğruya pusu kurar, Onu öldürmeye çalışır."},{"n":"33","t":"Ama RAB onu kötünün eline düşürmez, Yargılanırken mahkûm etmez."},{"n":"34","t":"RAB'be umut bağla, O'nun yolunu tut, Ülkeyi miras almak üzere seni yükseltecektir. Kötülerin kökünün kazındığını göreceksin."},{"n":"35","t":"Kötü ve acımasız adamı gördüm, İlk dikildiği toprakta yeşeren ağaç gibi Dal budak salıyordu;"},{"n":"36","t":"Geçip gitti, yok oldu, Aradım, bulunmaz oldu."},{"n":"37","t":"Yetkin adamı gözle, doğru adama bak, Çünkü yarınlar barışseverindir."},{"n":"38","t":"Ama başkaldıranların hepsi yok olacak, Kötülerin kökü kazınacak."},{"n":"39","t":"Doğruların kurtuluşu RAB'den gelir, Sıkıntılı günde onlara kale olur."},{"n":"40","t":"RAB onlara yardım eder, kurtarır onları, Kötülerin elinden alıp özgür kılar, Çünkü kendisine sığınırlar."}]},{"id":38,"name":"BÖLÜM 38","verses":[{"n":"1","t":"Ya RAB, öfkelenip azarlama beni, Gazapla yola getirme!"},{"n":"2","t":"Okların içime saplandı, Elin üzerime indi."},{"n":"3","t":"Öfken yüzünden sağlığım bozuldu, Günahım yüzünden rahatım kaçtı."},{"n":"4","t":"Çünkü suçlarım başımdan aştı, Taşınmaz bir yük gibi sırtımda ağırlaştı."},{"n":"5","t":"Akılsızlığım yüzünden Yaralarım iğrenç, irinli."},{"n":"6","t":"Eğildim, iki büklüm oldum, Gün boyu yaslı dolaşıyorum."},{"n":"7","t":"Çünkü belim ateş içinde, Sağlığım bozuk."},{"n":"8","t":"Tükendim, ezildim alabildiğine, İnliyorum yüreğimin acısından."},{"n":"9","t":"Ya Rab, bütün özlemlerimi bilirsin, İniltilerim senden gizli değil."},{"n":"10","t":"Yüreğim çarpıyor, gücüm tükeniyor, Gözlerimin feri bile söndü."},{"n":"11","t":"Eşim dostum kaçar oldu derdimden, Yakınlarım uzak duruyor benden."},{"n":"12","t":"Canıma susayanlar bana tuzak kuruyor, Zararımı isteyenler kuyumu kazıyor, Gün boyu hileler düşünüyorlar."},{"n":"13","t":"Ama ben bir sağır gibi duymuyorum, Bir dilsiz gibi ağzımı açmıyorum;"},{"n":"14","t":"Duymaz, Ağzında yanıt bulunmaz bir adama döndüm."},{"n":"15","t":"Umudum sende, ya RAB, Sen yanıtlayacaksın, ya Rab, Tanrım benim!"},{"n":"16","t":"Çünkü dua ediyorum: \"Halime sevinmesinler, Ayağım kayınca böbürlenmesinler!\""},{"n":"17","t":"Düşmek üzereyim, Acım hep içimde."},{"n":"18","t":"Suçumu itiraf ediyorum, Günahım yüzünden kaygılanıyorum."},{"n":"19","t":"Ama düşmanlarım güçlü ve dinç, Yok yere benden nefret edenler çok."},{"n":"20","t":"İyiliğe karşı kötülük yapanlar bana karşı çıkar, İyiliğin peşinde olduğum için."},{"n":"21","t":"Beni terk etme, ya RAB! Ey Tanrım, benden uzak durma!"},{"n":"22","t":"Yardımıma koş, Ya Rab, kurtuluşum benim!"}]},{"id":39,"name":"BÖLÜM 39","verses":[{"n":"1","t":"Karar verdim: \"Adımlarıma dikkat edeceğim, Dilimi günahtan sakınacağım; Karşımda kötü biri oldukça, Ağzıma gem vuracağım.\""},{"n":"2","t":"Dilimi tutup sustum, Hep kaçındım konuşmaktan, yararı olsa bile. Acım alevlendi,"},{"n":"3","t":"Yüreğim tutuştu içimde, Ateş aldı derin derin düşünürken, Şu sözler döküldü dilimden:"},{"n":"4","t":"\"Bildir bana, ya RAB, sonumu, Sayılı günlerimi; Bileyim ömrümün ne kadar kısa olduğunu!"},{"n":"5","t":"Yalnız bir karış ömür verdin bana, Hiç kalır hayatım senin önünde. Her insan bir soluktur sadece, En güçlü çağında bile. *"},{"n":"6","t":"\"Bir gölge gibi dolaşır insan, Boş yere çırpınır, Mal biriktirir, kime kalacağını bilmeden."},{"n":"7","t":"\"Ne bekleyebilirim şimdi, ya Rab? Umudum sende."},{"n":"8","t":"Kurtar beni bütün isyanlarımdan, Aptalların hakaretine izin verme."},{"n":"9","t":"Sustum, açmayacağım ağzımı; Çünkü sensin bunu yapan."},{"n":"10","t":"Uzaklaştır üzerimden yumruklarını, Tokadının altında mahvoldum."},{"n":"11","t":"Sen insanı suçundan ötürü Azarlayarak yola getirirsin, Güve gibi tüketirsin sevdiği şeyleri. Her insan bir soluktur sadece."},{"n":"12","t":"\"Duamı işit, ya RAB, Kulak ver yakarışıma, Gözyaşlarıma kayıtsız kalma! Çünkü ben bir garibim senin yanında, Bir yabancı, atalarım gibi."},{"n":"13","t":"Uzaklaştır üzerimden bakışlarını, Göçüp yok olmadan mutlu olayım!\""}]},{"id":40,"name":"40. Mezmur(Mez.70:1-5)Müzik şefi için - Davut'un mezmuru","verses":[{"n":"1","t":"RAB'bi sabırla bekledim; Bana yönelip yakarışımı duydu."},{"n":"2","t":"Ölüm çukurundan, Balçıktan çıkardı beni, Ayaklarımı kaya üzerinde tuttu, Kaymayayım diye."},{"n":"3","t":"Ağzıma yeni bir ezgi, Tanrımız'a bir övgü ilahisi koydu. Çokları görüp korkacak Ve RAB'be güvenecekler."},{"n":"4","t":"Ne mutlu RAB'be güvenen insana, Gururluya, yalana sapana ilgi duymayana."},{"n":"5","t":"Ya RAB, Tanrım, Harikaların, düşüncelerin ne çoktur bizim için; Sana eş koşulmaz! Duyurmak, anlatmak istesem yaptıklarını, Saymakla bitmez."},{"n":"6","t":"Kurbandan, sunudan hoşnut olmadın, Ama kulaklarımı açtın. Yakmalık sunu*, günah sunusu* da istemedin."},{"n":"7-8","t":"O zaman şöyle dedim: \"İşte geldim; Kutsal Yazı tomarında benim için yazılmıştır. Ey Tanrım, senin isteğini yapmaktan zevk alırım ben, Yasan yüreğimin derinliğindedir.\""},{"n":"9","t":"Büyük toplantıda müjdelerim senin zaferini, Sözümü esirgemem, Ya RAB, bildiğin gibi!"},{"n":"10","t":"Zaferini içimde gizlemem, Bağlılığını ve kurtarışını duyururum, Sevgini, sadakatini saklamam büyük topluluktan."},{"n":"11","t":"Ya RAB, esirgeme sevecenliğini benden! Sevgin, sadakatin hep korusun beni!"},{"n":"12","t":"Sayısız belalar çevremi sardı, Suçlarım bana yetişti, önümü göremiyorum; Başımdaki saçlardan daha çoklar, Çaresiz kaldım."},{"n":"13","t":"Ne olur, ya RAB, kurtar beni! Yardımıma koş, ya RAB!"},{"n":"14","t":"Utansın canımı almaya çalışanlar, Yüzleri kızarsın! Geri dönsün zararımı isteyenler, Rezil olsunlar!"},{"n":"15","t":"Bana, \"Oh! Oh!\" çekenler Dehşete düşsün utançlarından!"},{"n":"16","t":"Sende neşe ve sevinç bulsun Bütün sana yönelenler! \"RAB yücedir!\" desin hep Senin kurtarışını özleyenler!"},{"n":"17","t":"Bense mazlum ve yoksulum, Düşün beni, ya Rab. Yardımcım ve kurtarıcım sensin, Geç kalma, ey Tanrım!"}]},{"id":41,"name":"41. MezmurMüzik şefi için - Davut'un mezmuru","verses":[{"n":"1","t":"Ne mutlu yoksulu düşünene! RAB kurtarır onu kötü günde."},{"n":"2","t":"Korur RAB, yaşatır onu, Ülkede mutlu kılar, Terk etmez düşmanlarının eline."},{"n":"3","t":"Destek olur RAB ona Yatağa düşünce; Hastalandığında sağlığa kavuşturur onu."},{"n":"4","t":"\"Acı bana, ya RAB!\" dedim, \"Şifa ver bana, çünkü sana karşı günah işledim!\""},{"n":"5","t":"Kötü konuşuyor düşmanlarım ardımdan: \"Ne zaman ölecek adı batası?\" diyorlar."},{"n":"6","t":"Biri beni görmeye geldi mi, boş laf ediyor, Fesat topluyor içinde, Sonra dışarı çıkıp fesadı yayıyor."},{"n":"7","t":"Benden nefret edenlerin hepsi Fısıldaşıyor aralarında bana karşı, Zararımı düşünüyorlar,"},{"n":"8","t":"\"Başına öyle kötü bir şey geldi ki\" diyorlar, \"Yatağından kalkamaz artık.\""},{"n":"9","t":"Ekmeğimi yiyen, güvendiğim yakın dostum bile İhanet etti bana."},{"n":"10","t":"Bari sen acı bana, ya RAB, kaldır beni. Bunların hakkından geleyim."},{"n":"11","t":"Düşmanım zafer çığlığı atmazsa, O zaman anlarım benden hoşnut kaldığını."},{"n":"12","t":"Dürüstlüğümden ötürü bana destek olur, Sonsuza dek beni huzurunda tutarsın."},{"n":"13","t":"Öncesizlikten sonsuza dek, Övgüler olsun İsrail'in Tanrısı RAB'be! Amin! Amin!"}]},{"id":42,"name":"42. Mezmur*fn*Müzik şefi için - Korahoğulları'nın Maskili","verses":[{"n":"1","t":"Geyik akarsuları nasıl özlerse, Canım da seni öyle özler, ey Tanrı!D Not Birçok İbranice elyazmasında 42. ve 43. Mezmur birleşik yazılır."},{"n":"2","t":"Canım Tanrı'ya, yaşayan Tanrı'ya susadı; Ne zaman görmeye gideceğim Tanrı'nın yüzünü?"},{"n":"3","t":"Gözyaşlarım ekmeğim oldu gece gündüz, Gün boyu, \"Nerede senin Tanrın?\" dedikleri için."},{"n":"4","t":"Anımsayınca içim içimi yiyor, Nasıl toplulukla birlikte yürür, Tanrı'nın evine kadar alaya öncülük ederdim, Sevinç ve şükran sesleri arasında, Bayram eden bir kalabalıkla birlikte."},{"n":"5","t":"Neden üzgünsün, ey gönlüm, Neden içim huzursuz? Tanrı'ya umut bağla, Çünkü O'na yine övgüler sunacağım; O benim kurtarıcım ve Tanrım'dır."},{"n":"6-7","t":"Gönlüm üzgün, Bu yüzden seni anımsıyorum, ey Tanrım. Şeria yöresinde, Hermon ve Misar dağlarında Çağlayanların gümbürdeyince, Enginler birbirine sesleniyor, Bütün dalgaların, sellerin üzerimden geçiyor."},{"n":"8","t":"Gündüz RAB sevgisini gösterir, Gece ilahi söyler, dua ederim Yaşamımın Tanrısı'na."},{"n":"9","t":"Kayam olan Tanrım'a diyorum ki, \"Neden beni unuttun? Niçin düşmanlarımın baskısı altında Yaslı gezeyim?\""},{"n":"10","t":"Gün boyu hasımlarım: \"Nerede senin Tanrın?\" diyerek Bana sataştıkça, Kemiklerim kırılıyor sanki."},{"n":"11","t":"Neden üzgünsün, ey gönlüm, Neden içim huzursuz? Tanrı'ya umut bağla, Çünkü O'na yine övgüler sunacağım; O benim kurtarıcım ve Tanrım'dır."}]},{"id":43,"name":"43. Mezmur","verses":[{"n":"1","t":"Hakkımı ara, ey Tanrı, Savun beni vefasız ulusa karşı, Kurtar hileci, haksız insandan."},{"n":"2","t":"Çünkü sen Tanrım, kalemsin; Neden beni reddettin? Niçin düşmanlarımın baskısı altında Yaslı gezeyim?"},{"n":"3","t":"Gönder ışığını, gerçeğini, Yol göstersinler bana, Senin kutsal dağına, konutuna götürsünler beni."},{"n":"4","t":"O zaman Tanrı'nın sunağına, Neşe, sevinç kaynağım Tanrı'ya gideceğim Ve sana, ey Tanrı, Tanrım benim, Lirle şükredeceğim."},{"n":"5","t":"Neden üzgünsün, ey gönlüm, Neden içim huzursuz? Tanrı'ya umut bağla, Çünkü O'na yine övgüler sunacağım; O benim kurtarıcım ve Tanrım'dır."}]},{"id":44,"name":"44. MezmurMüzik şefi için - Korahoğulları'nın Maskili","verses":[{"n":"1","t":"Ey Tanrı, kulaklarımızla duyduk, Atalarımız anlattı bize, Neler yaptığını onların gününde, eski günlerde."},{"n":"2","t":"Elinle ulusları kovdun, Ama atalarımıza yer verdin; Halkları kırdın, Ama atalarımızın yayılmasını sağladın."},{"n":"3","t":"Onlar ülkeyi kılıçla kazanmadılar, Kendi bilekleriyle zafere ulaşmadılar. Senin sağ elin, bileğin, yüzünün ışığı sayesinde oldu bu; Çünkü sen onları sevdin."},{"n":"4","t":"Ey Tanrı, kralım sensin, Buyruk ver de Yakup soyu kazansın!"},{"n":"5","t":"Senin sayende düşmanlarımızı püskürteceğiz, Senin adınla karşıtlarımızı ezeceğiz."},{"n":"6","t":"Çünkü ben yayıma güvenmem, Kılıcım da beni kurtarmaz;"},{"n":"7","t":"Ancak sensin bizi düşmanlarımızdan kurtaran, Bizden nefret edenleri utanca boğan."},{"n":"8","t":"Her gün Tanrı'yla övünür, Sonsuza dek adına şükran sunarız. *"},{"n":"9","t":"Ne var ki, reddettin bizi, aşağıladın, Artık ordularımızla savaşa çıkmıyorsun."},{"n":"10","t":"Düşman karşısında bizi gerilettin, Bizden tiksinenler bizi soydu."},{"n":"11","t":"Kasaplık koyuna çevirdin bizi, Ulusların arasına dağıttın."},{"n":"12","t":"Yok pahasına sattın halkını, Üstelik satıştan hiçbir şey kazanmadan."},{"n":"13","t":"Bizi komşularımızın yüzkarası, Çevremizdekilerin eğlencesi, alay konusu ettin."},{"n":"14","t":"Ulusların diline düşürdün bizi, Gülüyor halklar halimize."},{"n":"15","t":"Rezilliğim gün boyu karşımda, Utancımdan yerin dibine geçtim"},{"n":"16","t":"Hakaret ve sövgü duya duya, Öç almak isteyen düşman karşısında."},{"n":"17","t":"Bütün bunlar başımıza geldi, Yine de seni unutmadık, Antlaşmana ihanet etmedik,"},{"n":"18","t":"Döneklik etmedik, Adımlarımız senin yolundan sapmadı."},{"n":"19","t":"Oysa sen bizi ezdin, ülkemizi çakalların uğrağı ettin, Üstümüzü koyu karanlıkla örttün."},{"n":"20","t":"Eğer Tanrımız'ın adını unutsaydık, Yabancı bir ilaha ellerimizi açsaydık,"},{"n":"21","t":"Tanrı bunu ortaya çıkarmaz mıydı? Çünkü O yürekteki gizleri bilir."},{"n":"22","t":"Senin uğruna her gün öldürülüyoruz, Kasaplık koyun sayılıyoruz."},{"n":"23","t":"Uyan, ya Rab! Niçin uyuyorsun?Kalk! Sonsuza dek terk etme bizi!"},{"n":"24","t":"Niçin yüzünü gizliyorsun? Neden mazlum halimizi, üzerimizdeki baskıyı unutuyorsun?"},{"n":"25","t":"Çünkü yere serildik, Bedenimiz toprağa yapıştı."},{"n":"26","t":"Kalk, yardım et bize! Kurtar bizi sevgin uğruna!"}]},{"id":45,"name":"45. MezmurMüzik şefi için - \"Zambaklar\" makamındaKorahoğulları'nın Maskili - Aşk ilahisi","verses":[{"n":"1","t":"Yüreğimden güzel sözler taşıyor, Kral için söylüyorum şiirlerimi, Dilim usta bir yazarın kalemi gibi olsun."},{"n":"2","t":"Sen insanların en güzelisin, Lütuf saçılmış dudaklarına. Çünkü Tanrı seni sonsuza dek kutsamış."},{"n":"3","t":"Ey yiğit savaşçı, kuşan kılıcını beline, Görkemine, yüceliğine bürün."},{"n":"4","t":"At sırtında görkeminle, zaferle ilerle, Gerçek ve adalet uğruna*fo* Sağ elin korkunç işler göstersin.D"},{"n":"4","t":"Olası metin \"Gerçek ve adalet uğruna\", Masoretik metin \"Gerçek ve alçakgönüllülük, adalet uğruna\"."},{"n":"5","t":"Okların sivridir, Kral düşmanlarının yüreğine saplanır, Halklar ayaklarının altına serilir."},{"n":"6","t":"Ey Tanrı, tahtın sonsuzluklar boyunca kalıcıdır*fö*, Krallığının asası adalet asasıdır.D"},{"n":"6","t":"\"Ey Tanrı, tahtın sonsuzluklar boyunca kalıcıdır\" ya da \"Tanrı'nın sana armağan ettiği krallık sonsuzluklar boyunca kalıcıdır\"."},{"n":"7","t":"Doğruluğu sever, kötülükten nefret edersin. Bunun için Tanrı, senin Tanrın, Seni sevinç yağıyla Arkadaşlarından daha çok meshetti*."},{"n":"8","t":"Giysilerinin tümü mür*, öd, tarçın kokuyor; Fildişi saraylardan gelen çalgı sesleri seni eğlendiriyor!"},{"n":"9","t":"Kral kızları senin saygın kadınların arasında, Kraliçe, Ofir altınları içinde senin sağında duruyor."},{"n":"10","t":"Dinle, ey kral kızı, bak, kulak ver, Halkını, baba evini unut."},{"n":"11","t":"Kral senin güzelliğine vuruldu, Efendin olduğu için önünde eğil."},{"n":"12","t":"Sur halkı armağan getirecek, Halkın zenginleri lütfunu kazanmak isteyecek."},{"n":"13","t":"Kral kızı odasında ışıl ışıl parıldıyor, Giysisi altınla dokunmuş."},{"n":"14","t":"İşlemeli giysiler içinde kralın önüne çıkarılacak, Arkadaşları, ona eşlik eden kızlar sana getirilecek."},{"n":"15","t":"Sevinç ve coşkuyla götürülecek, Kralın sarayına girecekler."},{"n":"16","t":"Atalarının yerini oğulların alacak, Onları önder yapacaksın bütün ülkeye."},{"n":"17","t":"Adını kuşaklar boyunca yaşatacağım, Böylece halklar sonsuza dek övecek seni. 46. MezmurMüzik şefi için - Tiz sesliler*fp* için -Korahoğulları'nın ezgisi"}]},{"id":46,"name":"BÖLÜM 46","verses":[{"n":"1","t":"Tanrı sığınağımız ve gücümüzdür, Sıkıntıda hep yardıma hazırdır.D Not \"Tiz sesliler\": İbranice \"Alamot\", anlamı tam olarakbilinmeyen bir müzik terimi."},{"n":"2","t":"Bu yüzden korkmayız yeryüzü altüst olsa, Dağlar denizlerin bağrına devrilse,"},{"n":"3","t":"Sular kükreyip köpürse, Kabaran deniz dağları titretse bile. *"},{"n":"4","t":"Bir ırmak var ki, suları sevinç getirir Tanrı kentine, Yüceler Yücesi'nin kutsal konutuna."},{"n":"5","t":"Tanrı onun ortasındadır, Sarsılmaz o kent. Gün doğarken Tanrı ona yardım eder."},{"n":"6","t":"Uluslar kükrüyor, krallıklar sarsılıyor, Tanrı gürleyince yeryüzü eriyip gidiyor."},{"n":"7","t":"Her Şeye Egemen RAB bizimledir, Yakup'un Tanrısı kalemizdir."},{"n":"8","t":"Gelin, görün RAB'bin yaptıklarını, Yeryüzüne getirdiği yıkımları."},{"n":"9","t":"Savaşları durdurur yeryüzünün dört bucağında, Yayları kırar, mızrakları parçalar, Kalkanları*fr* yakar.D"},{"n":"9","t":"\"Kalkanları\" ya da \"Savaş arabalarını\"."},{"n":"10","t":"\"Sakin olun, bilin ki, Tanrı benim! Uluslar arasında yüceleceğim, Yeryüzünde yüceleceğim!\""},{"n":"11","t":"Her Şeye Egemen RAB bizimledir, Yakup'un Tanrısı kalemizdir."}]},{"id":47,"name":"47. MezmurMüzik şefi için - Korahoğulları'nın mezmuru","verses":[{"n":"1","t":"Ey bütün uluslar, el çırpın! Sevinç çığlıkları atın Tanrı'nın onuruna!"},{"n":"2","t":"Ne müthiştir yüce RAB, Bütün dünyanın ulu Kralı."},{"n":"3","t":"Halkları altımıza, Ulusları ayaklarımızın dibine serer."},{"n":"4","t":"Sevdiği Yakup'un gururu olan mirasımızı O seçti bizim için. *"},{"n":"5","t":"RAB Tanrı sevinç çığlıkları, Boru sesleri arasında yükseldi."},{"n":"6","t":"Ezgiler sunun Tanrı'ya, ezgiler; Ezgiler sunun Kralımız'a, ezgiler!"},{"n":"7","t":"Çünkü Tanrı bütün dünyanın kralıdır, Maskil*fs* sunun!D"},{"n":"7","t":"\"Maskil\": Anlamı tam olarak bilinmeyen bir müzik veyaedebiyat terimi. \"Didaktik şiir\" anlamına gelebilir."},{"n":"8","t":"Tanrı kutsal tahtına oturmuş, Krallık eder uluslara."},{"n":"9","t":"Ulusların önderleri İbrahim'in Tanrısı'nın halkıyla bir araya gelmiş; Çünkü Tanrı'ya aittir yeryüzü kralları. O çok yücedir."}]},{"id":48,"name":"48. Mezmurİlahi - Korahoğulları'nın mezmuru","verses":[{"n":"1","t":"RAB büyüktür ve yalnız O övülmeye değer Tanrımız'ın kentinde, kutsal dağında."},{"n":"2","t":"Yükselir zarafetle, Bütün yeryüzünün sevinci Siyon Dağı, Safon'un*fş* doruğu, ulu Kral'ın kenti.D"},{"n":"2","t":"\"Safon\": İlah Baal'ın oturduğu sanılan bir dağ."},{"n":"3","t":"Tanrı onun kalelerinde Sağlam kule olarak gösterdi kendini."},{"n":"4","t":"Krallar toplandı, Birlikte Siyon'un üzerine yürüdüler."},{"n":"5","t":"Ama onu görünce şaşkına döndüler, Dehşete düşüp kaçtılar."},{"n":"6","t":"Doğum sancısı tutan kadın gibi, Bir titreme aldı onları orada."},{"n":"7","t":"Doğu rüzgarının parçaladığı ticaret gemileri gibi Yok ettin onları."},{"n":"8","t":"Her Şeye Egemen RAB'bin kentinde, Tanrımız'ın kentinde, Nasıl duyduksa, öyle gördük. Tanrı onu sonsuza dek güvenlik içinde tutacak. *"},{"n":"9","t":"Ey Tanrı, tapınağında, Ne kadar vefalı olduğunu düşünüyoruz."},{"n":"10","t":"Adın gibi, ey Tanrı, övgün de Dünyanın dört bucağına varıyor. Sağ elin zafer dolu."},{"n":"11","t":"Sevinsin Siyon Dağı, Coşsun Yahuda beldeleri Senin yargılarınla!"},{"n":"12","t":"Siyon'un çevresini gezip dolanın, Kulelerini sayın,"},{"n":"13","t":"Surlarına dikkatle bakın, Kalelerini yoklayın ki, Gelecek kuşağa anlatasınız:"},{"n":"14","t":"Bu Tanrı sonsuza dek bizim Tanrımız olacak, Bize hep yol gösterecektir."}]},{"id":49,"name":"49. MezmurMüzik şefi için - Korahoğulları'nın mezmuru","verses":[{"n":"1","t":"Ey bütün halklar, dinleyin! Kulak verin hepiniz, ey dünyada yaşayanlar,"},{"n":"2","t":"Halk çocukları, bey çocukları, Zenginler, yoksullar!"},{"n":"3","t":"Bilgelik dökülecek ağzımdan, Anlayış sağlayacak içimdeki düşünceler,"},{"n":"4","t":"Kulak vereceğim özdeyişlere, Lirle yorumlayacağım bilmecemi."},{"n":"5","t":"Niçin korkayım kötü günlerde Niyeti bozuk düşmanlarım çevremi sarınca?"},{"n":"6","t":"Onlar varlıklarına güvenir, Büyük servetleriyle böbürlenirler."},{"n":"7","t":"Kimse kimsenin hayatının bedelini ödeyemez, Tanrı'ya fidye veremez."},{"n":"8","t":"Çünkü hayatın fidyesi büyüktür, Kimse ödemeye yeltenmemeli."},{"n":"9","t":"Böyle olmasa, Sonsuza dek yaşar insan, Mezar yüzü görmez."},{"n":"10","t":"Kuşkusuz herkes biliyor bilgelerin öldüğünü, Aptallarla budalaların yok olduğunu. Mallarını başkalarına bırakıyorlar."},{"n":"11","t":"Mezarları, sonsuza dek evleri, Kuşaklar boyu konutları olacak*ft*, Topraklarına kendi adlarını verseler bile.D"},{"n":"11","t":"Septuaginta, Targum, Süryanice \"Mezarları, sonsuza dek evleri, kuşaklar boyu konutları olacak\", Masoretik metin \"'Evlerimiz sonsuza dek kalacak diye düşünüyorlar\"."},{"n":"12","t":"Bütün gösterişine karşın geçicidir insan, Ölüp giden hayvanlar gibi."},{"n":"13","t":"Budalaların yolu, Onların sözünü onaylayanların sonu budur. *"},{"n":"14","t":"Sürü gibi ölüler diyarına sürülecekler, Ölüm güdecek onları. Tan ağarınca doğrular onlara egemen olacak, Cesetleri çürüyecek, Ölüler diyarı onlara konut olacak."},{"n":"15","t":"Ama Tanrı beni Ölüler diyarının pençesinden kurtaracak Ve yanına alacak."},{"n":"16","t":"Korkma biri zenginleşirse, Evinin görkemi artarsa."},{"n":"17","t":"Çünkü ölünce hiçbir şey götüremez, Görkemi onunla mezara gitmez."},{"n":"18","t":"Yaşarken kendini mutlu saysa bile, Başarılı olunca övülse bile."},{"n":"19","t":"Atalarının kuşağına katılacak, Onlar ki asla ışık yüzü görmeyecekler."},{"n":"20","t":"Bütün gösterişine karşın anlayışsızdır insan, Ölüp giden hayvanlar gibi."}]},{"id":50,"name":"50. MezmurAsaf'ın mezmuru","verses":[{"n":"1","t":"Güçlü olan Tanrı, RAB konuşuyor; Güneşin doğduğu yerden battığı yere kadar Yeryüzünün tümüne sesleniyor."},{"n":"2","t":"Güzelliğin doruğu Siyon'dan Parıldıyor Tanrı."},{"n":"3","t":"Tanrımız geliyor, sessiz kalmayacak, Önünde yanan ateş her şeyi kül ediyor, Çevresinde şiddetli bir fırtına esiyor."},{"n":"4","t":"Halkını yargılamak için Yere göğe sesleniyor:"},{"n":"5","t":"\"Toplayın önüme sadık kullarımı, Kurban keserek benimle antlaşma yapanları.\""},{"n":"6","t":"Gökler O'nun doğruluğunu duyuruyor, Çünkü yargıç Tanrı'nın kendisidir. *"},{"n":"7","t":"\"Ey halkım, dinle de konuşayım, Ey İsrail, sana karşı tanıklık edeyim: Ben Tanrı'yım, senin Tanrın'ım!"},{"n":"8","t":"Kurbanlarından ötürü seni azarlamıyorum, Yakmalık sunuların* sürekli önümde."},{"n":"9","t":"Ne evinden bir boğa, Ne de ağıllarından bir teke alacağım."},{"n":"10","t":"Çünkü bütün orman yaratıkları, Dağlardaki bütün hayvanlar benimdir."},{"n":"11","t":"Dağlardaki bütün kuşları korurum, Kırlardaki bütün yabanıl hayvanlar benimdir."},{"n":"12","t":"Acıksam sana söylemezdim, Çünkü bütün dünya ve içindekiler benimdir."},{"n":"13","t":"Ben boğa eti yer miyim? Ya da keçi kanı içer miyim?"},{"n":"14","t":"Tanrı'ya şükran kurbanı sun, Yüceler Yücesi'ne adadığın adakları yerine getir."},{"n":"15","t":"Sıkıntılı gününde seslen bana, Seni kurtarırım, sen de beni yüceltirsin."},{"n":"16","t":"Ama Tanrı kötüye şöyle diyor: \"Kurallarımı ezbere okumaya Ya da antlaşmamı ağzına almaya ne hakkın var?"},{"n":"17","t":"Çünkü yola getirilmekten nefret ediyor, Sözlerimi arkana atıyorsun."},{"n":"18","t":"Hırsız görünce onunla dost oluyor, Zina edenlere ortak oluyorsun."},{"n":"19","t":"Ağzını kötülük için kullanıyor, Dilini yalana koşuyorsun."},{"n":"20","t":"Oturup kardeşine karşı konuşur, Annenin oğluna kara çalarsın."},{"n":"21","t":"Sen bunları yaptın, ben sustum, Beni kendin gibi sandın. Seni azarlıyorum, Suçlarını gözünün önüne seriyorum."},{"n":"22","t":"\"Dikkate alın bunu, ey Tanrı'yı unutan sizler! Yoksa parçalarım sizi, kurtaran olmaz."},{"n":"23","t":"Kim şükran kurbanı sunarsa beni yüceltir; Yolunu düzeltene kurtarışımı göstereceğim.\""}]},{"id":51,"name":"51. Mezmur","verses":[{"n":"1","t":"Ey Tanrı, lütfet bana, Sevgin uğruna; Sil isyanlarımı, Sınırsız merhametin uğruna."},{"n":"2","t":"Tümüyle yıka beni suçumdan, Arıt beni günahımdan."},{"n":"3","t":"Çünkü biliyorum isyanlarımı, Günahım sürekli karşımda."},{"n":"4","t":"Sana karşı, yalnız sana karşı günah işledim, Senin gözünde kötü olanı yaptım. Öyle ki, konuşurken haklı, Yargılarken adil olasın."},{"n":"5","t":"Nitekim suç içinde doğdum ben, Günah içinde annem bana hamile kaldı."},{"n":"6","t":"Madem sen gönülde sadakat istiyorsun, Bilgelik öğret bana yüreğimin derinliklerinde."},{"n":"7","t":"Beni mercanköşkotuyla arıt, paklanayım, Yıka beni, kardan beyaz olayım."},{"n":"8","t":"Neşe, sevinç sesini duyur bana, Bayram etsin ezdiğin kemikler."},{"n":"9","t":"Bakma günahlarıma, Sil bütün suçlarımı."},{"n":"10","t":"Ey Tanrı, temiz bir yürek yarat, Yeniden kararlı bir ruh var et içimde."},{"n":"11","t":"Beni huzurundan atma, Kutsal Ruhun'u benden alma."},{"n":"12","t":"Geri ver bana sağladığın kurtuluş sevincini, Bana destek ol, istekli bir ruh ver."},{"n":"13","t":"Başkaldıranlara senin yollarını öğreteyim, Günahkârlar geri dönsün sana."},{"n":"14","t":"Kurtar beni kan dökme suçundan, Ey Tanrı, beni kurtaran Tanrı, Dilim senin kurtarışını ilahilerle övsün."},{"n":"15","t":"Ya Rab, aç dudaklarımı, Ağzım senin övgülerini duyursun."},{"n":"16","t":"Çünkü sen kurbandan hoşlanmazsın, Yoksa sunardım sana, Yakmalık sunudan* hoşnut kalmazsın."},{"n":"17","t":"Senin kabul ettiğin kurban alçakgönüllü bir ruhtur, Alçakgönüllü ve pişman bir yüreği hor görmezsin, ey Tanrı."},{"n":"18","t":"Lütfet, Siyon'a iyilik yap, Yeruşalim'in surlarını onar."},{"n":"19","t":"O zaman doğru sunulan kurbanlar, Yakmalık sunular, tümüyle yakmalık sunular, Seni hoşnut kılar; O zaman sunağında boğalar sunulur."}]},{"id":52,"name":"52. Mezmur","verses":[{"n":"1-2","t":"Niçin kötülüğünle böbürlenirsin, ey kabadayı, Tanrı'nın sadık kullarına karşı Bütün gün dilin yıkım tasarlar Keskin ustura gibi, ey hilekâr."},{"n":"3","t":"İyilikten çok kötülüğü, Doğru konuşmaktan çok yalanı seversin. *"},{"n":"4","t":"Seni hileli dil seni! Her yıkıcı sözü seversin."},{"n":"5","t":"Ama Tanrı seni sonsuza dek yıkacak, Seni kapıp çadırından fırlatacak, Yaşam diyarından kökünü sökecek."},{"n":"6","t":"Doğrular bunu görünce korkacak, Gülerek şöyle diyecekler:"},{"n":"7","t":"\"İşte bu adam, Tanrı'ya sığınmak istemedi, Servetinin bolluğuna güvendi, Başkalarını yıkarak güçlendi!\""},{"n":"8","t":"Ama ben Tanrı'nın evinde yeşeren zeytin ağacı gibiyim, Sonsuza dek Tanrı'nın sevgisine güvenirim."},{"n":"9","t":"Sürekli sana şükrederim yaptıkların için, Sadık kullarının önünde umut bağlarım, Çünkü adın iyidir."}]},{"id":53,"name":"53. Mezmur(Mez.14)","verses":[{"n":"1","t":"Akılsız içinden, \"Tanrı yok!\" der. İnsanlar bozuldu, iğrençlik aldı yürüdü, İyilik eden yok.D Not \"Mahalat\": Bir müzik terimi, büyük olasılıkla \"Nefesli sazlar\"."},{"n":"2","t":"Tanrı göklerden bakar oldu insanlara, Akıllı, Tanrı'ya yönelen biri var mı diye."},{"n":"3","t":"Hepsi saptı, Tümü yozlaştı, İyilik eden yok, Bir kişi bile!"},{"n":"4","t":"Suç işleyenler görmüyor mu? Halkımı ekmek yer gibi yiyor, Tanrı'ya yakarmıyorlar."},{"n":"5","t":"Ama korkulmayacak yerde korkacaklar, Çünkü Tanrı seni kuşatanların kemiklerini dağıtacak, Onları reddettiği için hepsini utandıracak."},{"n":"6","t":"Keşke İsrail'in kurtuluşu Siyon'dan gelse! Tanrı halkını eski gönencine kavuşturunca, Yakup soyu sevinecek, İsrail halkı coşacak."}]},{"id":54,"name":"54. Mezmur","verses":[{"n":"1","t":"Ey Tanrı, beni adınla kurtar, Gücünle akla beni!"},{"n":"2","t":"Ey Tanrı, duamı dinle, Kulak ver ağzımdan çıkan sözlere."},{"n":"3","t":"Çünkü küstahlar bana saldırıyor, Zorbalar canımı almak istiyor, Tanrı'ya aldırmıyorlar. *"},{"n":"4","t":"İşte Tanrı benim yardımcımdır, Tek desteğim Rab'dir."},{"n":"5","t":"Düşmanlarım yaptıkları kötülüğün cezasını bulsun, Sadakatin uyarınca yok et onları."},{"n":"6","t":"Ya RAB, sana gönülden bir kurban sunacağım, Adına şükredeceğim, çünkü adın iyidir."},{"n":"7","t":"Beni bütün sıkıntılarımdan kurtardın, Gözlerim düşmanlarımın yok oluşunu gördü."}]},{"id":55,"name":"55. MezmurMüzik şefi için - Telli sazlarla Davut'un Maskili","verses":[{"n":"1","t":"Ey Tanrı, kulak ver duama, Sırt çevirme yalvarışıma!"},{"n":"2","t":"Dikkatini çevir, yanıt ver bana. Düşüncelerim beni rahatsız ediyor, şaşkınım"},{"n":"3","t":"Düşman sesinden, kötünün baskısından; Çünkü sıkıntıya sokuyorlar beni, Öfkeyle üstüme üstüme geliyorlar."},{"n":"4","t":"Yüreğim sızlıyor içimde, Ölüm dehşeti çöktü üzerime."},{"n":"5","t":"Korku ve titreme sardı beni, Ürperti kapladı içimi."},{"n":"6","t":"\"Keşke güvercin gibi kanatlarım olsaydı!\" Dedim kendi kendime, \"Uçar, rahatlardım."},{"n":"7","t":"Uzaklara kaçar, Çöllerde konaklardım. *"},{"n":"8","t":"Sert rüzgara, kasırgaya karşı Hemen bir barınak bulurdum.\""},{"n":"9","t":"Şaşkına çevir kötüleri, ya Rab, karıştır dillerini, Çünkü kentte şiddet ve çatışma görüyorum."},{"n":"10","t":"Gece gündüz kent surları üzerinde dolaşırlar, Haksızlık, fesat dolu kentin içi."},{"n":"11","t":"Yıkıcılık kentin göbeğinde, Zorbalık, hile eksilmez meydanından."},{"n":"12","t":"Beni aşağılayan bir düşman olsaydı, Katlanabilirdim; Bana küstahlık eden bir hasım olsaydı, Gizlenebilirdim."},{"n":"13","t":"Ama sensin, bana denk, Yoldaşım, yakın arkadaşım."},{"n":"14","t":"Birlikte tatlı tatlı yarenlik eder, Toplulukla Tanrı'nın evine giderdik."},{"n":"15","t":"Ölüm yakalasın düşmanlarımı ansızın, Diri diri ölüler diyarına insinler; Çünkü içleri ve evleri kötülük dolu."},{"n":"16","t":"Bense Tanrı'ya seslenirim, RAB kurtarır beni."},{"n":"17","t":"Sabah, öğlen, akşam kederimden feryat ederim, O işitir sesimi."},{"n":"18","t":"Bana karşı girişilen savaştan Esenlikle kurtarır canımı, Sayısı çok da olsa karşıtlarımın."},{"n":"19","t":"Öncesizlikten bu yana tahtında oturan Tanrı, Duyacak ve ezecek onları. Çünkü hiç değişmiyor Ve Tanrı'dan korkmuyorlar."},{"n":"20","t":"Yoldaşım dostlarına saldırarak Yaptığı antlaşmayı bozdu."},{"n":"21","t":"Ağzından bal damlar, Ama yüreğinde savaş var. Sözleri yağdan yumuşak, Ama yalın birer kılıçtır."},{"n":"22","t":"Yükünü RAB'be bırak, O sana destek olur. Asla izin vermez Doğru insanın sarsılmasına."},{"n":"23","t":"Ama sen, ey Tanrı, ölüm çukuruna atacaksın kötüleri, Günlerinin yarısını görmeyecek katillerle hainler; Bense sana güveniyorum."}]},{"id":56,"name":"56. MezmurMüzik şefi için\"Uzak Yabanıl Fıstık Ağaçlarındaki Güvercin\" makamında Davut'un Miktamı -Gat Kenti'nde Filistliler kendisini yakaladığı zaman","verses":[{"n":"1","t":"Acı bana, ey Tanrı, Çünkü ayak altında çiğniyor insanlar beni, Gün boyu saldırıp eziyorlar."},{"n":"2","t":"Düşmanlarım ayak altında çiğniyor beni her gün, Küstahça saldırıyor çoğu."},{"n":"3","t":"Sana güvenirim korktuğum zaman."},{"n":"4","t":"Tanrı'ya, sözünü övdüğüm Tanrı'ya Güvenirim ben, korkmam. İnsan bana ne yapabilir?"},{"n":"5","t":"Gün boyu sözlerimi çarpıtıyorlar, Hakkımda hep kötülük tasarlıyorlar."},{"n":"6","t":"Fesatlık için uğraşıyor, pusuya yatıyor, Adımlarımı gözlüyor, canımı almak istiyorlar."},{"n":"7","t":"Kötülüklerinin cezasından kurtulacaklar mı? Ey Tanrı, halkları öfkeyle yere çal!"},{"n":"8","t":"Çektiğim acıları kaydettin, Gözyaşlarımı tulumunda biriktirdin! Bunlar defterinde yazılı değil mi?"},{"n":"9","t":"Seslendiğim zaman, Düşmanlarım geri çekilecek. Biliyorum, Tanrı benden yana."},{"n":"10","t":"Sözünü övdüğüm Tanrı'ya, Sözünü övdüğüm RAB'be,"},{"n":"11","t":"Tanrı'ya güvenirim ben, korkmam; İnsan bana ne yapabilir?"},{"n":"12","t":"Ey Tanrı, sana adaklar adamıştım, Şükran kurbanları sunmalıyım şimdi."},{"n":"13","t":"Çünkü canımı ölümden kurtardın, Ayaklarımı tökezlemekten korudun; İşte yaşam ışığında, Tanrı huzurunda yürüyorum."}]},{"id":57,"name":"57. Mezmur(Mez.108:1-5)","verses":[{"n":"1","t":"Acı bana, ey Tanrı, acı, Çünkü sana sığınıyorum; Felaket geçinceye kadar, Kanatlarının gölgesine sığınacağım."},{"n":"2","t":"Yüce Tanrı'ya, Benim için her şeyi yapan Tanrı'ya sesleniyorum."},{"n":"3","t":"Gökten gönderip beni kurtaracak, Beni ezmek isteyenleri azarlayacak, * Sevgisini, sadakatini gösterecektir."},{"n":"4","t":"Aslanların arasındayım, Alev kusan insanlar arasında yatarım, Mızrak gibi, ok gibi dişleri, Keskin kılıç gibi dilleri."},{"n":"5","t":"Yüceliğini göster göklerin üstünde, ey Tanrı, Görkemin bütün yeryüzünü kaplasın!"},{"n":"6","t":"Ayaklarım için ağ serdiler, Çöktüm; Yoluma çukur kazdılar, İçine kendileri düştüler."},{"n":"7","t":"Kararlıyım, ey Tanrı, kararlıyım, Ezgiler, ilahiler söyleyeceğim."},{"n":"8","t":"Uyan, ey canım, Uyan, ey lir, ey çenk, Seheri ben uyandırayım!"},{"n":"9","t":"Halkların arasında sana şükürler sunayım, ya Rab, Ulusların arasında seni ilahilerle öveyim."},{"n":"10","t":"Çünkü sevgin göklere erişir, Sadakatin gökyüzüne ulaşır."},{"n":"11","t":"Yüceliğini göster göklerin üstünde, ey Tanrı, Görkemin bütün yeryüzünü kaplasın!"}]},{"id":58,"name":"58. MezmurMüzik şefi için - \"Yok Etme\" makamında Davut'un Miktamı","verses":[{"n":"1","t":"Ey yöneticiler*fü*, gerçekten adil mi karar verirsiniz? Doğru mu yargılarsınız insanları?D"},{"n":"1","t":"\"Yöneticiler\" ya da \"Dilsizler\"."},{"n":"2","t":"Hayır! Hep haksızlık tasarlarsınız içinizde, Zorbalık saçar elleriniz yeryüzüne."},{"n":"3","t":"Kötüler daha ana rahmindeyken yoldan çıkar, Doğdu doğalı yalan söyleyerek sapar."},{"n":"4","t":"Zehirleri yılan zehiri gibidir. Kulakları tıkalı bir kobrayı andırırlar,"},{"n":"5","t":"Usta büyücülerin, Afsuncuların sesini duymak istemeyen bir kobrayı."},{"n":"6","t":"Ey Tanrı, kır onların ağzında dişlerini, Sök genç aslanların azı dişlerini, ya RAB!"},{"n":"7","t":"Akıp giden su gibi yok olsunlar. Yaylarını gerince oklarının ucu kırılsın."},{"n":"8","t":"Süründükçe eriyen sümüklüböceğe dönsünler. Düşük çocuk gibi güneş yüzü görmesinler."},{"n":"9","t":"Kazanlarınız diken ateşini daha duymadan, Yaşı da kurusu da kasırgayla savrulacak kötülerin."},{"n":"10","t":"Doğru adam alınan öcü görünce sevinecek Ve ayaklarını kötünün kanında yıkayacak."},{"n":"11","t":"O zaman insanlar, \"Gerçekten doğrulara ödül var\" diyecek, \"Gerçekten dünyayı yargılayan bir Tanrı var.\""}]},{"id":59,"name":"59. Mezmur","verses":[{"n":"1","t":"Kurtar beni düşmanlarımdan, ey Tanrım, Kalem ol hasımlarıma karşı."},{"n":"2","t":"Kurtar beni suç işleyenlerden, Uzak tut kanlı katillerden."},{"n":"3","t":"Bak, canımı almak için pusu kuruyorlar, Güçlüler bana karşı birleşiyorlar, Oysa başkaldırmadım, günahım yok, ya RAB."},{"n":"4","t":"Suç işlemediğim halde, Koşuşup hazırlanıyorlar. Kalk bana yardım etmek için, halime bak!"},{"n":"5","t":"Sen, ya RAB, Her Şeye Egemen Tanrı, İsrail'in Tanrısı, Uyan bütün ulusları cezalandırmak için, Acıma bu suçlu hainlere! *"},{"n":"6","t":"Akşam döner, köpek gibi hırlayıp Sinsi sinsi kenti dolaşırlar."},{"n":"7","t":"Bak, neler dökülür ağızlarından, Kılıç çıkar dudaklarından. \"Kim duyacak?\" derler."},{"n":"8","t":"Ama sen onlara gülersin, ya RAB, Bütün uluslarla eğlenirsin."},{"n":"9","t":"Gücüm sensin, seni gözlüyorum, Çünkü kalemsin, ey Tanrı."},{"n":"10","t":"Tanrım sevgisiyle karşılar beni, Bana düşmanlarımın yıkımını gösterir."},{"n":"11","t":"Onları öldürme, yoksa halkım unutur, Gücünle dağıt ve alçalt onları, Ya Rab, kalkanımız bizim."},{"n":"12","t":"Ağızlarının günahı, dudaklarından çıkan söz yüzünden, Gururlarının tuzağına düşsünler. Okudukları lanet, söyledikleri yalan yüzünden"},{"n":"13","t":"Yok et onları gazabınla, yok et, tükensinler; Bilsinler ki, Tanrı'nın egemenliği Yakup soyundan Yeryüzünün ucuna kadar ulaşır."},{"n":"14","t":"Akşam döner, köpek gibi hırlayıp Sinsi sinsi kenti dolaşırlar."},{"n":"15","t":"Yiyecek bulmak için gezerler,Doymazlarsa ulurlar."},{"n":"16","t":"Bense gücün için sabah ezgiler söyleyecek, Sevgini sevinçle dile getireceğim. Çünkü sen bana kale, Sıkıntılı günümde sığınak oldun."},{"n":"17","t":"Gücüm sensin, seni ilahilerle öveceğim, Çünkü kalem, beni seven Tanrı sensin."}]},{"id":60,"name":"60. Mezmur","verses":[{"n":"1","t":"Bizi reddettin, parladın bize karşı, ey Tanrı, Öfkelendin; eski halimize döndür bizi!"},{"n":"2","t":"Salladın yeri, yarıklar açtın; Onar çatlaklarını, çünkü yer sarsılıyor."},{"n":"3","t":"Halkına sıkıntı çektirdin, Sersemletici bir şarap içirdin bize."},{"n":"4","t":"Sancak verdin senden korkanlara, Okçulara karşı*fv* açsınlar diye. *D"},{"n":"4","t":"\"Okçulara karşı\" ya da \"Doğruluk uğruna\"."},{"n":"5","t":"Kurtar bizi sağ elinle, yardım et, Sevdiklerin özgürlüğe kavuşsun diye!"},{"n":"6","t":"Tanrı şöyle konuştu kutsal yerinde: \"Şekem'i sevinçle bölüştürecek, Sukkot Vadisi'ni ölçeceğim."},{"n":"7","t":"Gilat benimdir, Manaşşe de benim, Efrayim miğferim, Yahuda asam."},{"n":"8","t":"Moav yıkanma leğenim, Edom'un üzerine çarığımı fırlatacağım*fy*, Filist'e zaferle haykıracağım.\"D"},{"n":"8","t":"\"Çarığımı fırlatacağım\": Eski törelere göre çarığınfırlatılması, bir yerin sahiplenilmesi anlamına geliyordu."},{"n":"9","t":"Kim beni surlu kente götürecek? Kim bana Edom'a kadar yol gösterecek?"},{"n":"10","t":"Ey Tanrı, sen bizi reddetmedin mi? Ordularımıza öncülük etmiyor musun artık?"},{"n":"11","t":"Yardım et bize düşmana karşı, Çünkü boştur insan yardımı."},{"n":"12","t":"Tanrı'yla zafer kazanırız, O çiğner düşmanlarımızı."}]},{"id":61,"name":"61. MezmurMüzik şefi için - Telli sazlarla - Davut'un mezmuru","verses":[{"n":"1","t":"Ey Tanrı, yakarışımı işit, Duama kulak ver!"},{"n":"2","t":"Sana seslenirim yeryüzünün öbür ucundan, Yüreğime hüzün çökünce. Erişemeyeceğim yüksek bir kayaya çıkar beni,"},{"n":"3","t":"Çünkü sen benim için sığınak, Düşmana karşı güçlü bir kule oldun."},{"n":"4","t":"Çadırında sonsuza dek oturmak Ve kanatlarının gölgesine sığınmak isterim. *"},{"n":"5","t":"Çünkü sen, ey Tanrı, adaklarımı duydun, Adından korkanların mirasını bana verdin."},{"n":"6","t":"Kralın günlerine gün kat, Yılları yüzyıllar olsun!"},{"n":"7","t":"Tanrı'nın huzurunda sonsuza dek tahtında otursun; Onu sevgin ve sadakatinle koru!"},{"n":"8","t":"O zaman adını hep ilahilerle öveceğim, Her gün adaklarımı yerine getireceğim."}]},{"id":62,"name":"62. MezmurMüzik Şefi Yedutun için - Davut'un mezmuru","verses":[{"n":"1","t":"Canım yalnız Tanrı'da huzur bulur, Kurtuluşum O'ndan gelir."},{"n":"2","t":"Tek kayam, kurtuluşum, Kalem O'dur, asla sarsılmam."},{"n":"3","t":"Birini ezmek için daha ne vakte kadar Hep birlikte üstüne saldıracaksınız, Eğri bir duvara, Yerinden oynamış bir çite saldırır gibi?"},{"n":"4","t":"Tek düşünceleri onu doruktan indirmektir. Yalandan zevk alırlar. Ağızlarıyla hayırdua ederken, İçlerinden lanet okurlar. *"},{"n":"5","t":"Ey canım, yalnız Tanrı'da huzur bul, Çünkü umudum O'ndadır."},{"n":"6","t":"Tek kayam, kurtuluşum, Kalem O'dur, sarsılmam."},{"n":"7","t":"Kurtuluşum ve onurum Tanrı'ya bağlıdır, Güçlü kayam, sığınağım O'dur."},{"n":"8","t":"Ey halkım, her zaman O'na güven, İçini dök O'na, Çünkü Tanrı sığınağımızdır."},{"n":"9","t":"Sıradan insan ancak bir soluk, Soylu insansa bir yalandır. Tartıya konduğunda ikisi birlikte soluktan hafiftir."},{"n":"10","t":"Zorbalığa güvenmeyin, yağma malla övünmeyin; Varlığınız artsa bile, ona gönül bağlamayın."},{"n":"11","t":"Tanrı bir şey söyledi, Ben iki şey duydum: Güç Tanrı'nındır,"},{"n":"12","t":"Sevgi de senin, ya Rab! Çünkü sen herkese, yaptığının karşılığını verirsin."}]},{"id":63,"name":"63. MezmurYahuda kırlarında bulunduğu zaman - Davut'un mezmuru","verses":[{"n":"1","t":"Ey Tanrı, sensin benim Tanrım, Seni çok özlüyorum, Canım sana susamış, Kurak, yorucu, susuz bir diyarda, Bütün varlığımla seni arıyorum."},{"n":"2","t":"Kutsal yerde baktım sana, Gücünü, görkemini görmek için."},{"n":"3","t":"Senin sevgin yaşamdan iyidir, Bu yüzden dudaklarım seni yüceltir."},{"n":"4","t":"Ömrümce sana övgüler sunacağım, Senin adınla ellerimi kaldıracağım."},{"n":"5","t":"Zengin yiyeceklere doyarcasına doyacağım sana, Şakıyan dudaklarla ağzım sana övgüler sunacak."},{"n":"6","t":"Yatağıma uzanınca seni anarım, Gece boyunca derin derin seni düşünürüm."},{"n":"7","t":"Çünkü sen bana yardımcı oldun, Kanatlarının gölgesinde sevincimi dile getiririm."},{"n":"8","t":"Canım sana sımsıkı sarılır, Sağ elin bana destek olur."},{"n":"9","t":"Ama canımı almak isteyenler, Yerin derinliklerine inecek,"},{"n":"10","t":"Kılıcın ağzına atılacak, Çakallara yem olacak."},{"n":"11","t":"Kralsa Tanrı'da sevinç bulacak. Tanrı'nın adıyla ant içenlerin hepsi övünecek, Yalancıların ağzıysa kapanacak."}]},{"id":64,"name":"64. MezmurMüzik şefi için - Davut'un mezmuru","verses":[{"n":"1","t":"Ey Tanrı, kulak ver sesime yakındığım zaman, Hayatımı düşman korkusundan koru."},{"n":"2","t":"Kötülerin gizli tasarılarından, O suçlu güruhun şamatasından esirge beni."},{"n":"3","t":"Onlar dillerini kılıç gibi bilemiş, Acı sözlerini ok gibi hedefe yöneltmişler,"},{"n":"4","t":"Pusularından masum insanın üzerine atmak için. Ansızın vururlar, hiç çekinmeden."},{"n":"5","t":"Birbirlerini kötülük yapmaya iter, Gizli tuzaklar tasarlarken, \"Kim görecek?\" derler."},{"n":"6","t":"Haksızlık yapmayı düşünür, \"Kusursuz bir plan yaptık!\" derler. İnsanın içi ve yüreği derin bir sırdır, bilinmez."},{"n":"7","t":"Ama Tanrı onlara ok atacak, Ansızın yaralanacaklar."},{"n":"8","t":"Dilleri yüzünden yıkıma uğrayacaklar, Hallerini gören herkes alayla baş sallayacak."},{"n":"9","t":"Bütün insanlar korkuya kapılacak, Tanrı'nın işini duyuracak, O'nun yaptıkları üzerinde düşünecekler."},{"n":"10","t":"Doğru insan RAB'de sevinç bulacak, O'na sığınacak, Bütün temiz yürekliler O'nu övecek."}]},{"id":65,"name":"65. MezmurMüzik şefi için - Davut'un mezmuru - İlahi","verses":[{"n":"1","t":"Ey Tanrı, Siyon'da seni övgü bekliyor*fz*, Yerine getirilecek sana adanan adaklar.D"},{"n":"1","t":"Septuaginta, Süryanice \"Seni övgü bekliyor\",Masoretik metin \"Senin için sessizlik övgü\"."},{"n":"2","t":"Ey sen, duaları işiten, Bütün insanlar sana gelecek."},{"n":"3","t":"Suçlarımızın altında ezildik, Ama sen isyanlarımızı bağışlarsın."},{"n":"4","t":"Ne mutlu avlularında otursun diye Seçip kendine yaklaştırdığın kişiye! Evinin, kutsal tapınağının Nimetlerine doyacağız."},{"n":"5","t":"Ey bizi kurtaran Tanrı, Müthiş işler yaparak Zaferle yanıtlarsın bizi. Sen yeryüzünün dört bucağında, Uzak denizlerdekilerin umudusun;"},{"n":"6","t":"Kudret kuşanan, Gücüyle dağları kuran,"},{"n":"7","t":"Denizlerin kükremesini, Dalgaların gümbürtüsünü, Halkların kargaşasını yatıştıran sensin."},{"n":"8","t":"Dünyanın öbür ucunda yaşayanlar Korkuya kapılır senin belirtilerin karşısında. Doğudan batıya kadar insanlara Sevinç çığlıkları attırırsın."},{"n":"9","t":"Toprağa bakar, çok verimli kılarsın, Onu zenginliğe boğarsın. Ey Tanrı, ırmakların suyla doludur, İnsanlara tahıl sağlarsın, Çünkü sen toprağı şöyle hazırlarsın:"},{"n":"10","t":"Sabanın açtığı yarıkları bolca sular, Sırtlarını düzlersin. Yağmurla toprağı yumuşatır, Ürünlerine bereket katarsın."},{"n":"11","t":"İyiliklerinle yılı taçlandırırsın, Arabalarının geçtiği yollardan bolluk akar,"},{"n":"12","t":"Otlaklar yeşillenir, Tepeler sevince bürünür,"},{"n":"13","t":"Çayırlar sürülerle bezenir, Vadiler ekinle örtünür, Sevinçten haykırır, ezgi söylerler. 66. MezmurMüzik şefi için - İlahi - Mezmur"}]},{"id":66,"name":"BÖLÜM 66","verses":[{"n":"1","t":"Ey yeryüzündeki bütün insanlar, Tanrı'ya sevinç çığlıkları atın!"},{"n":"2","t":"Adının yüceliğine ilahiler söyleyin, O'na görkemli övgüler sunun!"},{"n":"3","t":"\"Ne müthiş işlerin var!\" deyin Tanrı'ya, \"Öyle büyük gücün var ki, Düşmanların eğiliyor önünde."},{"n":"4","t":"Bütün yeryüzü sana tapınıyor, İlahiler okuyor, adını ilahilerle övüyor.\" *"},{"n":"5","t":"Gelin, bakın Tanrı'nın neler yaptığına! Ne müthiş işler yaptı insanlar arasında:"},{"n":"6","t":"Denizi karaya çevirdi, Atalarımız yaya geçtiler ırmaktan. Yaptığına sevindik orada."},{"n":"7","t":"Kudretiyle sonsuza dek egemenlik sürer, Gözleri ulusları süzer; Başkaldıranlar gurura kapılmasın!"},{"n":"8","t":"Ey halklar, Tanrımız'a şükredin, Övgülerini duyurun."},{"n":"9","t":"Hayatımızı koruyan, Ayaklarımızın kaymasına izin vermeyen O'dur."},{"n":"10","t":"Sen bizi sınadın, ey Tanrı, Gümüş arıtır gibi arıttın."},{"n":"11","t":"Ağa düşürdün bizi, Sırtımıza ağır yük vurdun."},{"n":"12","t":"İnsanları başımıza çıkardın, Ateşten, sudan geçtik. Ama sonra bizi bolluğa kavuşturdun."},{"n":"13","t":"Yakmalık sunularla* evine gireceğim, Adaklarımı yerine getireceğim,"},{"n":"14","t":"Sıkıntı içindeyken dudaklarımdan dökülen, Ağzımdan çıkan adakları."},{"n":"15","t":"Yakılan koçların dumanıyla semiz hayvanlardan Sana yakmalık sunular sunacağım, Tekeler, sığırlar kurban edeceğim."},{"n":"16","t":"Gelin, dinleyin, ey sizler, Tanrı'dan korkanlar, Benim için neler yaptığını size anlatayım."},{"n":"17","t":"Ağzımla O'na yakardım, Övgüsü dilimden düşmedi."},{"n":"18","t":"Yüreğimde kötülüğe yer verseydim, Rab beni dinlemezdi."},{"n":"19","t":"Oysa Tanrı dinledi beni, Kulak verdi duamın sesine."},{"n":"20","t":"Övgüler olsun Tanrı'ya, Çünkü duamı geri çevirmedi, Sevgisini benden esirgemedi."}]},{"id":67,"name":"67. MezmurMüzik şefi için - Telli sazlarla - Mezmur - İlahi","verses":[{"n":"1","t":"Tanrı bize lütfetsin, bolluk versin, Yüzünün ışığı üzerimize parlasın. *"},{"n":"2","t":"Öyle ki, yeryüzünde yolun, Bütün uluslar arasında kurtarıcı gücün bilinsin."},{"n":"3","t":"Halklar sana şükretsin, ey Tanrı, Bütün halklar sana şükretsin!"},{"n":"4","t":"Uluslar sevinsin, sevinçten çığlık atsın, Çünkü sen halkları adaletle yargılarsın, Yeryüzündeki uluslara yol gösterirsin."},{"n":"5","t":"Halklar sana şükretsin, ey Tanrı, Bütün halklar sana şükretsin!"},{"n":"6","t":"Toprak ürününü verdi, Tanrı, Tanrımız, bizi bolluğa kavuştursun."},{"n":"7","t":"Tanrı bize bolluk versin, Dünyanın dört bucağındakiler O'ndan korksun!"}]},{"id":68,"name":"68. MezmurMüzik şefi için - Davut'un mezmuru - İlahi","verses":[{"n":"1","t":"Kalksın Tanrı, dağılsın düşmanları, Kaçsın önünden O'ndan nefret edenler!"},{"n":"2","t":"Dağıtsın onları dağılan duman gibi; Ateşin karşısında eriyen balmumu gibi Yok olsun kötüler Tanrı'nın önünde!"},{"n":"3","t":"Ancak doğrular sevinsin, Bayram etsinler Tanrı'nın önünde, Neşeyle coşsunlar."},{"n":"4","t":"Tanrı'ya ezgiler söyleyin, adını ilahilerle övün, Çölleri geçecek biniciye yol hazırlayın*fa*; O'nun adı RAB'dir, bayram edin önünde!D"},{"n":"4","t":"\"Çölleri geçecek biniciye yol hazırlayın\" ya da \"Bulutlara binmiş olana ezgiler sunun\"."},{"n":"5","t":"Kutsal konutundaki Tanrı, Öksüzlerin babası, dul kadınların savunucusudur."},{"n":"6","t":"Tanrı kimsesizlere ev verir, Tutsakları özgürlüğe ve gönence kavuşturur, Ama başkaldıranlar kurak yerde oturur."},{"n":"7","t":"Ey Tanrı, sen halkına öncülük ettiğinde, Çölde yürüdüğünde, *"},{"n":"8","t":"Yer sarsıldı, Göklerden yağmur boşandı Tanrı'nın önünde, Sina Dağı sarsıldı Tanrı'nın, İsrail'in Tanrısı'nın önünde."},{"n":"9","t":"Bol yağmurlar yağdırdın, ey Tanrı, Canlandırdın yorgun düşen yurdunu."},{"n":"10","t":"Halkın oraya yerleşti, İyiliğinle mazlumların geçimini sağladın, ey Tanrı."},{"n":"11","t":"Rab buyruk verdi, Büyük bir kadın topluluğu duyurdu müjdeyi:"},{"n":"12","t":"\"Kaçıyor, kaçıyor orduların kralları! Evi bekleyen kadınlar ganimeti paylaşıyor."},{"n":"13","t":"Ağılların arasında uyurken, Kanatları gümüş, tüyleri pırıl pırıl altınla kaplı Bir güvercine benzersiniz.\""},{"n":"14","t":"Her Şeye Gücü Yeten, kralları dağıtırken, Sanki Salmon Dağı'na kar yağıyordu."},{"n":"15","t":"Ey Başan Dağı, Tanrı Dağı! Ey Başan Dağı, dorukları ulu dağ!"},{"n":"16","t":"Ey ulu dağlar, niçin yan gözle bakıyorsunuz Tanrı'nın yerleşmek için seçtiği dağa? Evet, RAB orada sonsuza dek oturacaktır."},{"n":"17","t":"Tanrı'nın savaş arabaları sayısızdır, Rab kutsallık içinde Sina'dan geldi. Mez.6818 Sen yükseğe çıktın, tutsakları peşine taktın, İnsanlardan, başkaldıranlardan bile armağanlar aldın, Oraya yerleşmek için, ya RAB Tanrı."},{"n":"19","t":"Her gün yükümüzü taşıyan Rab'be, Bizi kurtaran Tanrı'ya övgüler olsun."},{"n":"20","t":"Tanrımız kurtarıcı bir Tanrı'dır, Ölümden kurtarış yalnız Egemen RAB'be özgüdür."},{"n":"21","t":"Kuşkusuz Tanrı düşmanlarının başını, Suçlu yaşayanların kıllı kafasını ezer."},{"n":"22","t":"Rab, \"Onları Başan'dan, Denizin derinliklerinden geri getireceğim\" der,"},{"n":"23","t":"\"Öyle ki, ayaklarını düşmanlarının kanına batırasın, Köpeklerinin dili de onlardan payını alsın.\""},{"n":"24","t":"Ey Tanrı, senin zafer alayını, Tanrım'ın, Kralım'ın kutsal yere törenle gelişini gördüler:"},{"n":"25","t":"Başta okuyucular, arkada çalgıcılar, Ortada tef çalan genç kızlar."},{"n":"26","t":"\"Ey sizler, İsrail soyundan gelenler, Toplantılarınızda Tanrı'ya, RAB'be övgüler sunun!\""},{"n":"27","t":"Önde en küçük oymak Benyamin, Kalabalık halinde Yahuda önderleri, Zevulun ve Naftali önderleri oradalar!"},{"n":"28-29","t":"Ey Tanrı, Yeruşalim'deki tapınağından göster gücünü, Bizim için kullandığın gücünü, ey Tanrı. Krallar sana armağanlar sunacak."},{"n":"30","t":"Azarla kamışlar arasında yaşayan hayvanı, Halkların buzağılarıyla boğalar sürüsünü*fb*, Çiğne ayaklarınla gümüşe gönül verenleri, Dağıt savaştan zevk alan halkları!D"},{"n":"30","t":"Bu dizede geçen \"Hayvan\" Mısır'ı, \"Buzağılarlaboğalar\" ise irili ufaklı ulusları simgelemektedir."},{"n":"31","t":"Mısır'dan elçiler gelecek, Kûşlular* ellerini Tanrı'ya doğru kaldırıverecek."},{"n":"32","t":"Ey yeryüzünün krallıkları, Tanrı'ya ezgiler söyleyin, İlahilerle övün Rab'bi,"},{"n":"33","t":"Göklere, kadim göklere binmiş olanı. İşte sesiyle, güçlü sesiyle gürlüyor!"},{"n":"34","t":"Tanrı'nın gücünü tanıyın; O'nun yüceliği İsrail'in üzerinde, Gücü göklerdedir."},{"n":"35","t":"Ne heybetlisin, ey Tanrı, tapınağında! İsrail'in Tanrısı'na, Halkına güç, kudret veren Tanrı'ya övgüler olsun!"}]},{"id":69,"name":"69. MezmurMüzik şefi için - \"Zambaklar\" makamında - Davut'un mezmuru","verses":[{"n":"1","t":"Kurtar beni, ey Tanrı, Sular boyuma ulaştı."},{"n":"2","t":"Dipsiz batağa gömülüyorum, Basacak yer yok. Derin sulara battım, Sellere kapıldım."},{"n":"3","t":"Tükendim feryat etmekten, Boğazım kurudu; Gözlerimin feri sönüyor Tanrım'ı beklemekten."},{"n":"4","t":"Yok yere benden nefret edenler Saçlarımdan daha çok. Kalabalıktır canıma kasteden haksız düşmanlarım. Çalmadığım malı nasıl geri verebilirim?"},{"n":"5","t":"Akılsızlığımı biliyorsun, ey Tanrı, Suçlarım senden gizli değil."},{"n":"6","t":"Ya Rab, Her Şeye Egemen RAB, Utanmasın sana umut bağlayanlar benim yüzümden! Ey İsrail'in Tanrısı, Benim yüzümden sana yönelenler rezil olmasın!"},{"n":"7","t":"Senin uğruna hakarete katlandım, Utanç kapladı yüzümü."},{"n":"8","t":"Kardeşlerime yabancı, Annemin öz oğullarına uzak kaldım."},{"n":"9","t":"Çünkü evin için gösterdiğim gayret beni yiyip bitirdi, Sana edilen hakaretlere ben uğradım."},{"n":"10","t":"Oruç* tutup ağlayınca, Yine hakarete uğradım."},{"n":"11","t":"Çula büründüğüm zaman Alay konusu oldum."},{"n":"12","t":"Kent kapısında oturanlar beni çekiştiriyor, Sarhoşların türküsü oldum."},{"n":"13","t":"Ama benim duam sanadır, ya RAB. Ey Tanrı, sevginin bolluğuyla, Güvenilir kurtarışınla uygun gördüğünde Yanıtla beni."},{"n":"14","t":"Beni çamurdan kurtar, İzin verme batmama; Benden nefret edenlerden, Derin sulardan kurtulayım."},{"n":"15","t":"Seller beni sürüklemesin, Engin beni yutmasın, Ölüm çukuru ağzını üstüme kapamasın."},{"n":"16","t":"Yanıt ver bana, ya RAB, Çünkü sevgin iyidir. Yüzünü çevir bana büyük merhametinle!"},{"n":"17","t":"Kulundan yüzünü gizleme, Çünkü sıkıntıdayım, hemen yanıtla beni!"},{"n":"18","t":"Yaklaş bana, kurtar canımı, Al başımdan düşmanlarımı."},{"n":"19","t":"Bana nasıl hakaret edildiğini, Utandığımı, rezil olduğumu biliyorsun; Düşmanlarımın hepsi senin önünde."},{"n":"20","t":"Hakaret kalbimi kırdı, dertliyim, Acılarımı paylaşacak birini bekledim, çıkmadı, Avutacak birini aradım, bulamadım."},{"n":"21","t":"Yiyeceğime zehir kattılar, Sirke içirdiler susadığımda."},{"n":"22","t":"Önlerindeki sofra tuzak olsun onlara, Yandaşları için kapan olsun!"},{"n":"23","t":"Gözleri kararsın, göremesinler! Bellerini hep bükük tut!"},{"n":"24","t":"Gazabını yağdır üzerlerine, Öfkenin ateşi yapışsın yakalarına!"},{"n":"25","t":"Issız kalsın konakları, Çadırlarında oturan olmasın!"},{"n":"26","t":"Çünkü senin vurduğun insanlara zulmediyor, Yaraladığın insanların acısını konuşuyorlar."},{"n":"27","t":"Ceza yağdır başlarına, Senin tarafından aklanmasınlar!"},{"n":"28","t":"Yaşam kitabından silinsin adları, Doğrularla yan yana yazılmasınlar!"},{"n":"29","t":"Bense ezilmiş ve kederliyim, Senin kurtarışın, ey Tanrı, bana bir kale olsun!"},{"n":"30","t":"Tanrı'nın adını ezgilerle öveceğim, Şükranlarımla O'nu yücelteceğim."},{"n":"31","t":"RAB'bi bir öküzden, Boynuzlu, tırnaklı bir boğadan Daha çok hoşnut eder bu."},{"n":"32","t":"Mazlumlar bunu görünce sevinsin, Ey Tanrı'ya yönelen sizler, yüreğiniz canlansın."},{"n":"33","t":"Çünkü RAB yoksulları işitir, Kendi tutsak halkını hor görmez."},{"n":"34","t":"O'na övgüler sunun, ey yer, gök, Denizler ve onlardaki bütün canlılar! Mez.6935 Çünkü Tanrı Siyon'u kurtaracak, Yahuda kentlerini onaracak; Halk oraya yerleşip sahibi olacak."},{"n":"36","t":"Kullarının çocukları orayı miras alacak, O'nun adını sevenler orada oturacak."}]},{"id":70,"name":"70. Mezmur(Mez.40: 13-17)Müzik şefi için - Anma sunusu için - Davut'un mezmuru","verses":[{"n":"1","t":"Ey Tanrı, kurtar beni! Yardımıma koş, ya RAB!"},{"n":"2","t":"Utansın canımı almaya çalışanlar, Yüzleri kızarsın! Geri dönsün zararımı isteyenler, Rezil olsunlar!"},{"n":"3","t":"Bana, \"Oh! Oh!\" çekenler Geri çekilsin utançlarından!"},{"n":"4","t":"Sende neşe ve sevinç bulsun Bütün sana yönelenler! \"Tanrı yücedir!\" desin hep Senin kurtarışını özleyenler!"},{"n":"5","t":"Bense, mazlum ve yoksulum, Ey Tanrı, yardımıma koş! Yardımcım ve kurtarıcım sensin, Geç kalma, ya RAB!"}]},{"id":71,"name":"71. Mezmur(Mez.31: 1-4)","verses":[{"n":"1","t":"Ya RAB, sana sığınıyorum, Utandırma beni hiçbir zaman!"},{"n":"2","t":"Adaletinle kurtar beni, tehlikeden uzaklaştır, Kulak ver bana, kurtar beni! Mez.71: Sığınacak kayam ol, Her zaman başvurabileceğim; Buyruk ver, kurtulayım, Çünkü kayam ve kalem sensin."},{"n":"4","t":"Ey Tanrım, kurtar beni Kötünün elinden, haksızın, gaddarın pençesinden! Mez.71: Çünkü umudum sensin, ey Egemen RAB, Gençliğimden beri dayanağım sensin."},{"n":"6","t":"Doğduğum günden beri sana güveniyorum, Beni ana rahminden çıkaran sensin. Övgülerim hep sanadır."},{"n":"7","t":"Birçokları için iyi bir örnek oldum, Çünkü sen güçlü sığınağımsın."},{"n":"8","t":"Ağzımdan sana övgü eksilmez, Gün boyu yüceliğini anarım."},{"n":"9","t":"Yaşlandığımda beni reddetme, Gücüm tükendiğinde beni terk etme!"},{"n":"10","t":"Çünkü düşmanlarım benden söz ediyor, Beni öldürmek isteyenler birbirine danışıyor,"},{"n":"11","t":"\"Tanrı onu terk etti\" diyorlar, \"Kovalayıp yakalayın, Kurtaracak kimsesi yok!\""},{"n":"12","t":"Ey Tanrı, benden uzak durma, Tanrım, yardımıma koş!"},{"n":"13","t":"Utansın, yok olsun beni suçlayanlar, Utanca, rezalete bürünsün kötülüğümü isteyenler."},{"n":"14","t":"Ama ben her zaman umutluyum, Sana övgü üstüne övgü dizeceğim."},{"n":"15","t":"Gün boyu senin zaferini, Kurtarışını anlatacağım, Ölçüsünü bilmesem de."},{"n":"16","t":"Ey Egemen RAB, gelip yiğitliklerini, Senin, yalnız senin zaferini duyuracağım."},{"n":"17","t":"Ey Tanrı, çocukluğumdan beri beni sen yetiştirdin, Senin harikalarını hâlâ anlatıyorum."},{"n":"18","t":"Yaşlanıp saçlarıma ak düşse bile Terk etme beni, ey Tanrı, Gücünü gelecek kuşağa, Kudretini sonrakilere anlatana dek."},{"n":"19","t":"Ey Tanrı, doğruluğun göklere erişiyor, Büyük işler yaptın, Senin gibisi var mı, ey Tanrı?"},{"n":"20","t":"Sen ki, bana birçok kötü sıkıntı gösterdin, Bana yeniden yaşam verecek, Beni toprağın derinliklerinden çıkaracaksın."},{"n":"21","t":"Saygınlığımı artıracak, Yine beni avutacaksın."},{"n":"22","t":"Ben de seni, Senin sadakatini çenkle öveceğim, ey Tanrım, Lir çalarak seni ilahilerle öveceğim, Ey İsrail'in Kutsalı!"},{"n":"23","t":"Seni ilahilerle överken, Dudaklarımla, varlığımla sevincimi dile getireceğim, Çünkü sen beni kurtardın."},{"n":"24","t":"Dilim gün boyu senin zaferinden söz edecek, Çünkü kötülüğümü isteyenler Utanıp rezil oldu."}]},{"id":72,"name":"72. MezmurSüleyman'ın mezmuru","verses":[{"n":"1","t":"Ey Tanrı, adaletini krala, Doğruluğunu kral oğluna armağan et."},{"n":"2","t":"Senin halkını doğrulukla, Mazlum kullarını adilce yargılasın!"},{"n":"3","t":"Dağlar, tepeler, Halka adilce gönenç getirsin!"},{"n":"4","t":"Mazlumlara hakkını versin, Yoksulların çocuklarını kurtarsın, Zalimleriyse ezsin!"},{"n":"5","t":"Güneş ve ay durdukça, Kral kuşaklar boyunca yaşasın*fc*;D"},{"n":"5","t":"Septuaginta \"Kral kuşaklar boyunca yaşasın\", Masoretikmetin \"Kuşaklar boyunca senden korksunlar.\""},{"n":"6","t":"Yeni biçilmiş çayıra düşen yağmur gibi, Toprağı sulayan bereketli yağmurlar gibi olsun!"},{"n":"7","t":"Onun günlerinde doğruluk serpilip gelişsin, Ay ışıdığı sürece esenlik artsın!"},{"n":"8","t":"Egemenlik sürsün denizden denize, Fırat'tan yeryüzünün ucuna dek!"},{"n":"9","t":"Çöl kabileleri diz çöksün önünde, Düşmanları toz yalasın."},{"n":"10","t":"Tarşiş'in ve kıyı ülkelerinin kralları Ona haraç getirsin, Saba ve Seva kralları armağanlar sunsun!"},{"n":"11","t":"Bütün krallar önünde yere kapansın, Bütün uluslar ona kulluk etsin!"},{"n":"12","t":"Çünkü yardım isteyen yoksulu, Dayanağı olmayan düşkünü o kurtarır."},{"n":"13","t":"Yoksula, düşküne acır, Düşkünlerin canını kurtarır."},{"n":"14","t":"Baskıdan, zorbalıktan özgür kılar onları, Çünkü onun gözünde onların kanı değerlidir."},{"n":"15","t":"Yaşasın kral! Ona Saba altını versinler; Durmadan dua etsinler onun için, Gün boyu onu övsünler!"},{"n":"16","t":"Ülkede bol buğday olsun, Dağ başlarında dalgalansın! Başakları Lübnan gibi verimli olsun, Kent halkı ot gibi serpilip çoğalsın!"},{"n":"17","t":"Kralın adı sonsuza dek yaşasın, Güneş durdukça adı var olsun, Onun aracılığıyla insanlar kutsansın, Bütün uluslar \"Ne mutlu ona\" desin!"},{"n":"18","t":"RAB Tanrı'ya, İsrail'in Tanrısı'na övgüler olsun, Harikalar yaratan yalnız O'dur."},{"n":"19","t":"Yüce adına sonsuza dek övgüler olsun, Bütün yeryüzü O'nun yüceliğiyle dolsun! Amin! Amin!"},{"n":"20","t":"İşay oğlu Davut'un duaları burada bitiyor."}]},{"id":73,"name":"73. MezmurAsaf'ın mezmuru","verses":[{"n":"1","t":"Tanrı gerçekten İsrail'e, Yüreği temiz olanlara karşı iyidir."},{"n":"2","t":"Ama benim ayaklarım neredeyse tökezlemiş, Adımlarım az kalsın kaymıştı."},{"n":"3","t":"Çünkü kötülerin gönencini gördükçe, Küstahları kıskanıyordum."},{"n":"4","t":"Onlar acı nedir bilmezler, Bedenleri sağlıklı ve semizdir*fç*.D"},{"n":"4","t":"\"Onlar acı nedir bilmezler, bedenleri sağlıklı vesemizdir\" ya da \"Ölürken acı çekmezler, bedenleri semizdir\"."},{"n":"5","t":"Başkalarının derdini bilmez, Onlar gibi çile çekmezler."},{"n":"6","t":"Bu yüzden gurur onların gerdanlığı, Zorbalık onları örten bir giysi gibidir."},{"n":"7","t":"Şişmanlıktan gözleri dışarı fırlar, İçleri kötülük kazanı gibi kaynar."},{"n":"8","t":"İnsanlarla eğlenir, kötü niyetle konuşur, Tepeden bakar, baskıyla tehdit ederler."},{"n":"9","t":"Göklere karşı ağızlarını açarlar, Boş sözleri yeryüzünü dolaşır."},{"n":"10","t":"Bu yüzden halk onlardan yana döner, Sözlerini ağzı açık dinler."},{"n":"11","t":"Derler ki, \"Tanrı nasıl bilir? Bilgisi var mı Yüceler Yücesi'nin?\""},{"n":"12","t":"İşte böyledir kötüler, Hep tasasız, sürekli varlıklarını artırırlar."},{"n":"13","t":"Anlaşılan boş yere yüreğimi temiz tutmuşum, Ellerimi yıkamışım suçsuzum diye."},{"n":"14","t":"Gün boyu içim içimi yiyor, Her sabah azap çekiyorum."},{"n":"15","t":"\"Ben de onlar gibi konuşayım\" deseydim, Senin çocuklarına ihanet etmiş olurdum."},{"n":"16","t":"Bunu anlamak için düşündüğümde, Zor geldi bana,"},{"n":"17","t":"Tanrı'nın Tapınağı'na girene dek; O zaman anladım sonlarının ne olacağını."},{"n":"18","t":"Gerçekten onları kaygan yere koyuyor, Yıkıma sürüklüyorsun."},{"n":"19","t":"Nasıl da bir anda yok oluyor, Siliniveriyorlar dehşet içinde!"},{"n":"20","t":"Uyanan birisi için rüya nasılsa, Sen de uyanınca, ya Rab, Hor göreceksin onların görüntüsünü."},{"n":"21","t":"Kalbim kırıldığında, İçim acı dolduğunda,"},{"n":"22","t":"Akılsız ve bilgisizdim, Karşında bir hayvan gibi."},{"n":"23","t":"Yine de sürekli seninleyim, Sağ elimden tutarsın beni."},{"n":"24","t":"Öğütlerinle yol gösterir, Beni sonunda yüceliğe eriştirirsin."},{"n":"25","t":"Senden başka kimim var göklerde? İstemem senden başkasını yeryüzünde."},{"n":"26","t":"Bedenim ve yüreğim tükenebilir, Ama Tanrı yüreğimde güç, Bana düşen paydır sonsuza dek."},{"n":"27","t":"Kuşkusuz yok olacak senden uzak duranlar, Ortadan kaldıracaksın sana vefasızlık edenleri."},{"n":"28","t":"Ama benim için en iyisi Tanrı'ya yakın olmaktır; Bütün işlerini duyurayım diye Sığınak yaptım Egemen RAB'bi kendime."}]},{"id":74,"name":"74. MezmurAsaf'ın Maskili","verses":[{"n":"1","t":"Ey Tanrı, neden bizi sonsuza dek reddettin? Niçin otlağının koyunlarına karşı öfken tütmekte?"},{"n":"2","t":"Anımsa geçmişte sahiplendiğin topluluğu, Kendi halkın olsun diye kurtardığın oymağı Ve üzerine konut kurduğun Siyon Dağı'nı."},{"n":"3","t":"Yönelt adımlarını şu onarılmaz yıkıntılara doğru, Düşman kutsal yerdeki her şeyi yıktı."},{"n":"4","t":"Düşmanların bizimle buluştuğun yerde kükredi, Zafer simgesi olarak kendi bayraklarını dikti."},{"n":"5","t":"Gür bir ormana Baltayla dalar gibiydiler."},{"n":"6","t":"Baltayla, balyozla kırdılar, Bütün oymaları."},{"n":"7","t":"Ateşe verdiler tapınağını, Yerle bir edip kutsallığını bozdular Adının yaşadığı konutun."},{"n":"8","t":"İçlerinden, \"Hepsini ezelim!\" dediler. Ülkede Tanrı'yla buluşma yerlerinin tümünü yaktılar."},{"n":"9","t":"Artık kutsal simgelerimizi görmüyoruz, Peygamberler de yok oldu, İçimizden kimse bilmiyor ne zamana dek..."},{"n":"10","t":"Ey Tanrı, ne zamana dek düşman sana sövecek, Hasmın senin adını hor görecek?"},{"n":"11","t":"Niçin geri çekiyorsun elini? Çıkar sağ elini bağrından, yok et onları!"},{"n":"12","t":"Ama geçmişten bu yana kralım sensin, ey Tanrı, Yeryüzünde kurtuluş sağladın."},{"n":"13","t":"Gücünle denizi yardın, Canavarların kafasını sularda parçaladın."},{"n":"14","t":"Livyatan'ın* başlarını ezdin, Çölde yaşayanlara onu yem ettin."},{"n":"15","t":"Kaynaklar, dereler fışkırttın, Sürekli akan ırmakları kuruttun."},{"n":"16","t":"Gün senindir, gece de senin, Ay*fd* ve güneşi sen yerleştirdin,D"},{"n":"16","t":"\"Ay\": İbranice \"Işık\". Ayı ya da yıldızları kastediyor."},{"n":"17","t":"Yeryüzünün bütün sınırlarını sen saptadın, Yazı da kışı da yaratan sensin."},{"n":"18","t":"Anımsa, ya RAB, düşmanın sana nasıl sövdüğünü, Akılsız bir halkın, adını nasıl hor gördüğünü."},{"n":"19","t":"Canavara teslim etme kumrunun canını, Asla unutma düşkün kullarının yaşamını."},{"n":"20","t":"Yaptığın antlaşmayı gözönüne al, Çünkü ülkenin her karanlık köşesi Zorbaların inleriyle dolmuş."},{"n":"21","t":"Düşkünler boynu bükük geri çevrilmesin, Mazlumlar, yoksullar adına övgüler dizsin."},{"n":"22","t":"Kalk, ey Tanrı, davanı savun! Anımsa akılsızların gün boyu sana nasıl sövdüğünü!"},{"n":"23","t":"Unutma hasımlarının yaygarasını, Sana başkaldıranların durmadan yükselen patırtısını!"}]},{"id":75,"name":"75. MezmurMüzik şefi için - \"Yok Etme\" makamında -Asaf'ın mezmuru - İlahi","verses":[{"n":"1","t":"Sana şükrederiz, ey Tanrı, Şükrederiz, çünkü sen yakınsın*fe*, Harikaların bunu gösterir.D"},{"n":"1","t":"\"Sen yakınsın\": İbranice \"Adın yakındır\"."},{"n":"2","t":"\"Belirlediğim zaman gelince, Doğrulukla yargılayacağım\" diyor Tanrı,"},{"n":"3","t":"\"Yeryüzü altüst olunca üzerindekilerle, Ben pekiştireceğim onun direklerini. *"},{"n":"4","t":"Övünenlere, 'Övünmeyin artık! dedim; Kötülere, 'Kaldırmayın başınızı*ff*!"},{"n":"5","t":"Kaldırmayın başınızı*ff*! Tepeden konuşmayın!\"D Not 75:4,5 \"Başınızı\": İbranice \"Boynuzunuzu\" (Boynuz güç simgesidir)."},{"n":"6","t":"Çünkü ne doğudan, ne batıdan, Ne de çöldeki dağlardan doğar yargı."},{"n":"7","t":"Yargıç ancak Tanrı'dır, Birini alçaltır, birini yükseltir."},{"n":"8","t":"RAB elinde dolu bir kâse* tutuyor, Köpüklü, baharat karıştırılmış şarap döküyor; Yeryüzünün bütün kötüleri Tortusuna dek yalayıp onu içiyor."},{"n":"9","t":"Bense sürekli duyuracağım bunu, Yakup'un Tanrısı'nı ilahilerle öveceğim:"},{"n":"10","t":"\"Kıracağım kötülerin bütün gücünü, Doğruların gücüyse yükseltilecek.\""}]},{"id":76,"name":"76. MezmurMüzik şefi için - Telli sazlarla - Asaf'ın mezmuru - İlahi","verses":[{"n":"1","t":"Yahuda'da Tanrı bilinir, İsrail'de adı uludur;"},{"n":"2","t":"Konutu Şalem'dedir*fg*, Yaşadığı yer Siyon'da.D"},{"n":"2","t":"\"Şalem\", yani \"Yeruşalim\"."},{"n":"3","t":"Orada kırdı alevli okları, Kalkanı, kılıcı, savaş silahlarını. *"},{"n":"4","t":"Işıl ışıl parıldıyorsun, Avı bol dağlardan daha görkemli."},{"n":"5","t":"Yağmaya uğradı yiğitler, Uykularına daldılar, En güçlüleri bile elini kıpırdatamaz oldu."},{"n":"6","t":"Ey Yakup'un Tanrısı, sen kükreyince, Atlarla atlılar son uykularına daldılar."},{"n":"7","t":"Yalnız sensin korkulması gereken, Öfkelenince kim durabilir karşında?"},{"n":"8","t":"Yargını göklerden açıkladın, Yeryüzü korkup sessizliğe büründü,"},{"n":"9","t":"Ey Tanrı, sen yargılamaya, Ülkedeki mazlumları kurtarmaya kalkınca."},{"n":"10","t":"İnsanların gazabı bile sana övgüler doğuruyor, Gazabından kurtulanları çevrene topluyorsun."},{"n":"11","t":"Adaklar adayın Tanrı'nız RAB'be, Yerine getirin adaklarınızı, Armağanlar sunun korkulması gereken Tanrı'ya, Bütün çevresindekiler."},{"n":"12","t":"RAB önderlerin soluğunu keser, Korku salar yeryüzü krallarına."}]},{"id":77,"name":"77. MezmurMüzik Şefi Yedutun için - Asaf'ın mezmuru","verses":[{"n":"1","t":"Yüksek sesle Tanrı'ya yakarıyorum, Haykırıyorum beni duysun diye."},{"n":"2","t":"Sıkıntılı günümde Rab'be yönelir, Gece hiç durmadan ellerimi açarım, Gönlüm avunmaz bir türlü."},{"n":"3","t":"Tanrı'yı anımsayınca inlerim, Düşündükçe içim daralır. *"},{"n":"4","t":"Açık tutuyorsun göz kapaklarımı, Sıkıntıdan konuşamıyorum."},{"n":"5","t":"Geçmiş günleri, Yıllar öncesini düşünüyorum."},{"n":"6","t":"Gece ilahilerimi anacağım, Kendi kendimle konuşacağım, İnceden inceye soracağım:"},{"n":"7","t":"\"Rab sonsuza dek mi bizi reddedecek? Lütfunu bir daha göstermeyecek mi?"},{"n":"8","t":"Sevgisi sonsuza dek mi yok oldu? Sözü geçerli değil mi artık?"},{"n":"9","t":"Tanrı unuttu mu acımayı? Sevecenliğinin yerini öfke mi aldı?\""},{"n":"10","t":"Sonra kendi kendime, \"İşte benim derdim bu!\" dedim, \"Yüceler Yücesi gücünü göstermiyor artık.\""},{"n":"11","t":"RAB'bin işlerini anacağım, Evet, geçmişteki harikalarını anacağım."},{"n":"12","t":"Yaptıkları üzerinde derin derin düşüneceğim, Bütün işlerinin üzerinde dikkatle duracağım."},{"n":"13","t":"Ey Tanrı, yolun kutsaldır! Hangi ilah Tanrı kadar uludur?"},{"n":"14","t":"Harikalar yaratan Tanrı sensin, Halklar arasında gücünü gösterdin."},{"n":"15","t":"Güçlü bileğinle kendi halkını, Yakup ve Yusuf oğullarını kurtardın."},{"n":"16","t":"Sular seni görünce, ey Tanrı, Sular seni görünce çalkalandı, Enginler titredi."},{"n":"17","t":"Bulutlar suyunu boşalttı, Gökler gürledi, Her yanda okların uçuştu."},{"n":"18","t":"Kasırgada gürleyişin duyuldu, Şimşekler dünyayı aydınlattı, Yer titreyip sarsıldı."},{"n":"19","t":"Kendine denizde, Derin sularda yollar açtın, Ama ayak izlerin belli değildi."},{"n":"20","t":"Musa ve Harun'un eliyle Halkını bir sürü gibi güttün."}]},{"id":78,"name":"78. MezmurAsaf'ın Maskili","verses":[{"n":"1","t":"Dinle, ey halkım, öğrettiklerimi, Kulak ver ağzımdan çıkan sözlere."},{"n":"2","t":"Özdeyişlerle söze başlayacağım, Eski sırları anlatacağım,"},{"n":"3","t":"Duyduğumuzu, bildiğimizi, Atalarımızın bize anlattığını."},{"n":"4","t":"Torunlarından bunları gizlemeyeceğiz; RAB'bin övgüye değer işlerini, Gücünü, yaptığı harikaları Gelecek kuşağa duyuracağız."},{"n":"5","t":"RAB Yakup soyuna koşullar bildirdi, İsrail'e yasa koydu. Bunları çocuklarına öğretsinler diye Atalarımıza buyruk verdi."},{"n":"6","t":"Öyle ki, gelecek kuşak, yeni doğacak çocuklar bilsinler, Onlar da kendi çocuklarına anlatsınlar,"},{"n":"7","t":"Tanrı'ya güven duysunlar, Tanrı'nın yaptıklarını unutmasınlar, O'nun buyruklarını yerine getirsinler;"},{"n":"8","t":"Ataları gibi inatçı, başkaldırıcı, Yüreği kararsız, Tanrı'ya sadakatsiz bir kuşak olmasınlar."},{"n":"9","t":"Oklarla, yaylarla kuşanmış Efrayimoğulları Savaş günü sırtlarını döndüler."},{"n":"10","t":"Tanrı'nın antlaşmasına uymadılar, O'nun yasasına göre yaşamayı reddettiler."},{"n":"11","t":"Unuttular O'nun işlerini, Kendilerine gösterdiği harikaları."},{"n":"12","t":"Mısır'da, Soan*fh* bölgesinde Tanrı harikalar yapmıştı atalarının önünde.D"},{"n":"12","t":"\"Soan\": Tanis olduğu sanılıyor."},{"n":"13","t":"Denizi yarıp geçirmişti onları, Bir duvar gibi ayakta tutmuştu suları."},{"n":"14","t":"Gündüz bulutla, Gece ateş ışığıyla onlara yol göstermişti."},{"n":"15","t":"Çölde kayaları yarmış, Sanki dipsiz kaynaklardan Onlara kana kana su içirmişti."},{"n":"16","t":"Kayadan akarsular fışkırtmış, Suları ırmak gibi akıtmıştı."},{"n":"17","t":"Ama onlar çölde Yüceler Yücesi'ne başkaldırarak Günah işlemeye devam ettiler."},{"n":"18","t":"Canlarının çektiği yiyeceği isteyerek İçlerinde Tanrı'yı denediler."},{"n":"19","t":"\"Tanrı çölde sofra kurabilir mi?\" diyerek, Tanrı'ya karşı konuştular."},{"n":"20","t":"\"Bak, kayaya vurunca sular fışkırdı, Dereler taştı. Peki, ekmek de verebilir mi, Et sağlayabilir mi halkına?\""},{"n":"21","t":"RAB bunu duyunca çok öfkelendi, Yakup'a ateş püskürdü, Öfkesi tırmandı İsrail'e karşı;"},{"n":"22","t":"Çünkü Tanrı'ya inanmıyorlardı, O'nun kurtarıcılığına güvenmiyorlardı."},{"n":"23","t":"Yine de RAB buyruk verdi bulutlara, Kapaklarını açtı göklerin;"},{"n":"24","t":"Man* yağdırdı onları beslemek için, Göksel tahıl verdi onlara."},{"n":"25","t":"Meleklerin*fı* ekmeğini yedi her biri, Doyasıya yiyecek gönderdi onlara.D"},{"n":"25","t":"\"Meleklerin\" ya da \"Güçlülerin\"."},{"n":"26","t":"Doğu rüzgarını estirdi göklerde, Gücüyle güney rüzgarına yol gösterdi."},{"n":"27","t":"Toz gibi et yağdırdı başlarına, Deniz kumu kadar kuş;"},{"n":"28","t":"Ordugahlarının ortasına, Konakladıkları yerin çevresine düşürdü."},{"n":"29","t":"Yediler, tıka basa doydular, İsteklerini yerine getirdi Tanrı."},{"n":"30","t":"Ancak onlar isteklerine doymadan, Daha ağızları doluyken,"},{"n":"31","t":"Tanrı'nın öfkesi parladı üzerlerine. En güçlülerini öldürdü, Yere serdi İsrail yiğitlerini."},{"n":"32","t":"Yine de günah işlemeye devam ettiler, O'nun harikalarına inanmadılar."},{"n":"33","t":"Bu yüzden Tanrı onların günlerini boşluk, Yıllarını dehşet içinde bitirdi."},{"n":"34","t":"Tanrı onları öldürdükçe O'na yönelmeye, İstekle O'nu yeniden aramaya başlıyorlardı."},{"n":"35","t":"Tanrı'nın kayaları olduğunu, Yüce Tanrı'nın kurtarıcıları olduğunu anımsıyorlardı."},{"n":"36","t":"Oysa ağızlarıyla O'na yaltaklanıyor, Dilleriyle yalan söylüyorlardı."},{"n":"37","t":"O'na yürekten bağlı değillerdi, Antlaşmasına sadık kalmadılar."},{"n":"38","t":"Yine de Tanrı sevecendi, Suçlarını bağışlıyor, onları yok etmiyordu; Çok kez öfkesini tuttu, Bütün gazabını göstermedi."},{"n":"39","t":"Onların yalnızca insan olduğunu anımsadı, Geçip giden, dönmeyen bir rüzgar gibi."},{"n":"40","t":"Çölde kaç kez O'na başkaldırdılar, Issız yerlerde O'nu gücendirdiler!"},{"n":"41","t":"Defalarca denediler Tanrı'yı, İncittiler İsrail'in Kutsalı'nı."},{"n":"42","t":"Anımsamadılar O'nun güçlü elini, Kendilerini düşmandan kurtardığı günü,"},{"n":"43","t":"Mısır'da gösterdiği belirtileri, Soan bölgesinde yaptığı şaşılası işleri."},{"n":"44","t":"Mısır'ın kanallarını kana çevirdi, Sularını içemediler."},{"n":"45","t":"Gönderdiği at sinekleri yedi halkı, Gönderdiği kurbağalar yok etti ülkeyi."},{"n":"46","t":"Ekinlerini tırtıllara, Emeklerinin ürününü çekirgelere verdi."},{"n":"47","t":"Asmalarını doluyla, Yabanıl incir ağaçlarını iri dolu taneleriyle yok etti."},{"n":"48","t":"Büyükbaş hayvanlarını kırgına, Küçükbaş hayvanlarını yıldırıma teslim etti."},{"n":"49","t":"Üzerlerine kızgın öfkesini, Gazap, hışım, bela Ve bir alay kötülük meleği gönderdi."},{"n":"50","t":"Yol verdi öfkesine, Canlarını ölümden esirgemedi, Onları salgın hastalığın pençesine düşürdü."},{"n":"51","t":"Mısır'da bütün ilk doğanları, Ham'ın çadırlarında bütün ilk çocukları vurdu."},{"n":"52","t":"Kendi halkını davar gibi götürdü, Çölde onları bir sürü gibi güttü."},{"n":"53","t":"Onlara güvenlik içinde yol gösterdi, korkmadılar; Düşmanlarınıysa deniz yuttu."},{"n":"54","t":"Böylece onları kendi kutsal topraklarının sınırına, Sağ elinin kazandığı dağlık bölgeye getirdi."},{"n":"55","t":"Önlerinden ulusları kovdu, Mülk olarak topraklarını İsrail oymakları arasında bölüştürdü. Halkını konutlarına yerleştirdi."},{"n":"56","t":"Ama onlar yüce Tanrı'yı denediler, O'na başkaldırdılar, Koşullarına uymadılar."},{"n":"57","t":"Döneklik edip ataları gibi ihanet ettiler, Güvenilmez bir yay gibi bozuk çıktılar."},{"n":"58","t":"Puta taptıkları yerlerle O'nu kızdırdılar, Putlarıyla O'nu kıskandırdılar."},{"n":"59","t":"Tanrı bunları duyunca çok öfkelendi, İsrail'i büsbütün reddetti."},{"n":"60","t":"İnsanlar arasında kurduğu çadırı, Şilo'daki konutunu terk etti."},{"n":"61","t":"Kudretini*fi* tutsaklığa, Görkemini*fi* düşman eline teslim etti.D"},{"n":"61","t":"Bu ayette geçen \"Kudret\" ve \"Görkem\" sözcükleriAntlaşma Sandığı'nı kastetmektedir."},{"n":"62","t":"Halkını kılıç önüne sürdü, Öfkesini kendi halkından çıkardı."},{"n":"63","t":"Gençlerini ateş yuttu, Kızlarına düğün türküsü söylenmez oldu."},{"n":"64","t":"Kâhinleri* kılıç altında öldü, Dul kadınları ağlayamadı."},{"n":"65","t":"O zaman Rab uykudan uyanır gibi, Şarabın rehavetinden ayılan bir yiğit gibi oldu."},{"n":"66","t":"Düşmanlarını püskürttü, Onları sonsuz utanca boğdu."},{"n":"67","t":"Tanrı Yusuf soyunu reddetti, Efrayim oymağını seçmedi;"},{"n":"68","t":"Ancak Yahuda oymağını, Sevdiği Siyon Dağı'nı seçti."},{"n":"69","t":"Tapınağını doruklar gibi, Sonsuzluk için kurduğu yeryüzü gibi yaptı."},{"n":"70","t":"Kulu Davut'u seçti, Onu koyun ağılından aldı."},{"n":"71","t":"Halkı Yakup'u, kendi halkı İsrail'i gütmek için, Onu yavru kuzuların ardından getirdi."},{"n":"72","t":"Böylece Davut onlara dürüstçe çobanlık etti, Becerikli elleriyle onlara yol gösterdi."}]},{"id":79,"name":"79. MezmurAsaf'ın mezmuru","verses":[{"n":"1","t":"Ey Tanrı, uluslar senin yurduna saldırdı, Kutsal tapınağını kirletti, Yeruşalim'i taş yığınına çevirdi."},{"n":"2","t":"Kullarının ölülerini yem olarak yırtıcı kuşlara, Sadık kullarının etini yabanıl hayvanlara verdiler."},{"n":"3","t":"Kanlarını su gibi akıttılar Yeruşalim'in çevresine, Onları gömecek kimse yok."},{"n":"4","t":"Komşularımıza yüzkarası, Çevremizdekilere eğlence ve oyuncak olduk."},{"n":"5","t":"Ne zamana dek, ya RAB? Sonsuza dek mi sürecek öfken, Alev gibi yanan kıskançlığın?"},{"n":"6","t":"Öfkeni seni tanımayan ulusların, Adını anmayan ülkelerin üzerine dök."},{"n":"7","t":"Çünkü onlar Yakup soyunu yiyip bitirdiler, Yurdunu viraneye çevirdiler."},{"n":"8","t":"Atalarımızın suçlarını artık önümüze sürme, Sevecenliğini hemen göster bize, Çünkü tükendikçe tükendik."},{"n":"9","t":"Yardım et bize yüce adın uğruna, ey bizi kurtaran Tanrı, Kurtar bizi adın uğruna, bağışla günahlarımızı!"},{"n":"10","t":"Niçin uluslar, \"Nerede onların Tanrısı?\" diye konuşsun, Kullarının dökülen kanının öcünü alacağını bilsinler, Gözlerimizle bunu görelim!"},{"n":"11","t":"Tutsakların iniltisi senin katına erişsin, Koru büyük gücünle ölüme mahkûm olanları."},{"n":"12","t":"Komşularımızın sana ettikleri hakareti Yedi kat iade et bağırlarına, ya Rab!"},{"n":"13","t":"Bizler, kendi halkın, otlağının koyunları Sonsuza dek şükredeceğiz sana, Kuşaklar boyunca övgülerini dilimizden düşürmeyeceğiz."}]},{"id":80,"name":"80. MezmurMüzik şefi için - \"Zambaklar Antlaşması\" makamında - Asaf'ın mezmuru","verses":[{"n":"1","t":"Kulak ver, ey İsrail'in çobanı, Ey Yusuf'u bir sürü gibi güden, Keruvlar* arasında taht kuran, Saç ışığını,"},{"n":"2","t":"Efrayim, Benyamin, Manaşşe önünde Uyandır gücünü, Gel, kurtar bizi!"},{"n":"3","t":"Bizi eski halimize kavuştur, ey Tanrı, Yüzünün ışığıyla aydınlat, kurtulalım!"},{"n":"4","t":"Ya RAB, Her Şeye Egemen Tanrı, Ne zamana dek halkının dualarına ateş püsküreceksin?"},{"n":"5","t":"Onlara ekmek yerine gözyaşı verdin, Ölçekler dolusu gözyaşı içirdin."},{"n":"6","t":"Kavga nedeni ettin bizi komşularımıza, Düşmanlarımız alay ediyor bizimle."},{"n":"7","t":"Bizi eski halimize kavuştur, Ey Her Şeye Egemen Tanrı, Yüzünün ışığıyla aydınlat, kurtulalım!"},{"n":"8","t":"Mısır'dan bir asma çubuğu getirdin, Ulusları kovup onu diktin."},{"n":"9","t":"Onun için toprağı hazırladın, Kök saldı, bütün ülkeye yayıldı."},{"n":"10","t":"Gölgesi dağları, Dalları koca sedir ağaçlarını kapladı."},{"n":"11","t":"Sürgünleri Akdeniz'e, Filizleri Fırat'a dek uzandı."},{"n":"12","t":"Niçin yıktın bağın duvarlarını? Yoldan geçen herkes üzümünü koparıyor,"},{"n":"13","t":"Orman domuzları onu yoluyor, Yabanıl hayvanlar onunla besleniyor."},{"n":"14","t":"Ey Her Şeye Egemen Tanrı, ne olur, dön bize! Göklerden bak ve gör, İlgilen bu asmayla."},{"n":"15","t":"İlgilen sağ elinin diktiği filizle, Kendine seçtiğin oğulla!"},{"n":"16","t":"Asman kesilmiş, yakılmış, Öfkeli bakışların yok etsin düşmanlarını!"},{"n":"17","t":"Elin, sağ kolun olan adamın üzerinde, Kendine seçtiğin insanın üzerinde olsun!"},{"n":"18","t":"O zaman senden asla ayrılmayacağız; Yaşam ver bize, adını analım!"},{"n":"19","t":"Ya RAB, ey Her Şeye Egemen Tanrı, Bizi eski halimize kavuştur, Yüzünün ışığıyla aydınlat, kurtulalım!"}]},{"id":81,"name":"81. MezmurMüzik şefi için - Gittit üzerine - Asaf'ın mezmuru","verses":[{"n":"1","t":"Sevincinizi dile getirin gücümüz olan Tanrı'ya, Sevinç çığlıkları atın Yakup'un Tanrısı'na!"},{"n":"2","t":"Çalgıya başlayın, tef çalın, Tatlı sesli lir ve çenk çınlatın."},{"n":"3","t":"Yeni Ay'da, dolunayda, Boru çalın bayram günümüzde."},{"n":"4","t":"Çünkü bu İsrail için bir kuraldır, Yakup'un Tanrısı'nın ilkesidir."},{"n":"5","t":"Tanrı Mısır'a karşı yürüdüğünde, Yusuf soyuna koydu bu koşulu. Orada tanımadığım bir ses işittim:"},{"n":"6","t":"\"Sırtındaki yükü kaldırdım, Ellerin küfeden kurtuldu\" diyordu,"},{"n":"7","t":"\"Sıkıntıya düşünce seslendin, seni kurtardım, Gök gürlemesinin ardından sana yanıt verdim, Meriva*fj* sularında seni sınadım. *D"},{"n":"7","t":"\"Meriva\": \"Çıkışma\" anlamına gelir (bkz. Çık.17:7)."},{"n":"8","t":"\"Dinle, ey halkım, seni uyarıyorum; Ey İsrail, keşke beni dinlesen!"},{"n":"9","t":"Aranızda yabancı ilah olmasın, Başka bir ilaha tapmayın!"},{"n":"10","t":"Seni Mısır'dan çıkaran Tanrın RAB benim. Ağzını iyice aç, doldurayım!"},{"n":"11","t":"\"Ama halkım sesimi dinlemedi, İsrail bana boyun eğmek istemedi."},{"n":"12","t":"Ben de onları inatçı yürekleriyle baş başa bıraktım, Bildikleri gibi yaşasınlar diye."},{"n":"13","t":"Keşke halkım beni dinleseydi, İsrail yollarımda yürüseydi!"},{"n":"14","t":"Düşmanlarını hemen yere serer, Hasımlarına el kaldırırdım!"},{"n":"15","t":"Benden nefret edenler bana boyun eğerdi, Bu böyle sonsuza dek sürerdi."},{"n":"16","t":"Oysa sizleri en iyi buğdayla besler, Kayadan akan balla doyururdum.\""}]},{"id":82,"name":"82. MezmurAsaf'ın mezmuru","verses":[{"n":"1","t":"Tanrı yerini aldı tanrısal kurulda*fk*, Yargısını açıklıyor ilahların ortasında:D"},{"n":"1","t":"\"Tanrısal kurulda\" ya da \"Yargıçlar topluluğunda\"."},{"n":"2","t":"\"Ne zamana dek haksız karar verecek, Kötüleri kayıracaksınız? *"},{"n":"3","t":"Zayıfın, öksüzün davasını savunun, Mazlumun, yoksulun hakkını arayın."},{"n":"4","t":"Zayıfı, düşkünü kurtarın, Onları kötülerin elinden özgür kılın.\""},{"n":"5","t":"Bilmiyor, anlamıyorlar, Karanlıkta dolaşıyorlar. Yeryüzünün temelleri sarsılıyor."},{"n":"6","t":"\"'Siz ilahlarsınız diyorum, 'Yüceler Yücesi'nin oğullarısınız hepiniz!"},{"n":"7","t":"Yine de insanlar gibi öleceksiniz, Sıradan bir önder gibi düşeceksiniz!\""},{"n":"8","t":"Kalk, ey Tanrı, yargıla yeryüzünü! Çünkü bütün uluslar senindir."}]},{"id":83,"name":"83. Mezmurİlahi - Asaf'ın mezmuru","verses":[{"n":"1","t":"Ey Tanrı, susma, Sessiz, hareketsiz kalma!"},{"n":"2","t":"Bak, düşmanların kargaşa çıkarıyor, Senden nefret edenler boy gösteriyor."},{"n":"3","t":"Halkına karşı kurnazlık peşindeler, Koruduğun insanlara dolap çeviriyorlar."},{"n":"4","t":"\"Gelin, bu ulusun kökünü kazıyalım\" diyorlar, \"İsrail'in adı bir daha anılmasın!\""},{"n":"5","t":"Hepsi sözbirliği etmiş, düzen kuruyor, Sana karşı anlaşmaya vardı:"},{"n":"6","t":"Edomlular, İsmaililer, Moavlılar, Hacerliler,"},{"n":"7","t":"Geval, Ammon, Amalek, Filist ve Sur halkı."},{"n":"8","t":"Asur da onlara katıldı, Lutoğulları'na güç verdiler. *"},{"n":"9","t":"Onlara Midyan'a, Kişon Vadisi'nde Sisera'ya ve Yavin'e yaptığını yap:"},{"n":"10","t":"Onlar Eyn-Dor'da yok oldular, Toprak için gübreye döndüler."},{"n":"11","t":"Onların soylularına Orev ve Zeev'e yaptığını, Beylerine Zevah ve Salmunna'ya yaptığını yap."},{"n":"12","t":"Onlar: \"Gelin, sahiplenelim Tanrı'nın otlaklarını\" demişlerdi."},{"n":"13","t":"Ey Tanrım, savrulan toza, Rüzgarın sürüklediği saman çöpüne çevir onları!"},{"n":"14","t":"Orman yangını gibi, Dağları tutuşturan alev gibi,"},{"n":"15","t":"Fırtınanla kovala, Kasırganla dehşete düşür onları!"},{"n":"16","t":"Utançla kapla yüzlerini, Sana yönelsinler, ya RAB."},{"n":"17","t":"Sonsuza dek utanç ve dehşet içinde kalsınlar, Rezil olup yok olsunlar."},{"n":"18","t":"Senin adın RAB'dir, Anlasınlar yalnız senin yeryüzüne egemen en yüce Tanrıolduğunu."}]},{"id":84,"name":"84. MezmurMüzik şefi için - Gittit üzerine - Korahoğulları'nın mezmuru","verses":[{"n":"1","t":"Ey Her Şeye Egemen RAB, Ne kadar severim konutunu!"},{"n":"2","t":"Canım senin avlularını özlüyor, İçim çekiyor, Yüreğim, bütün varlığım Sana, yaşayan Tanrı'ya sevinçle haykırıyor."},{"n":"3","t":"Kuşlar bile bir yuva, Kırlangıç, yavrularını koyacak bir yer buldu Senin sunaklarının yanında, Ey Her Şeye Egemen RAB, Kralım ve Tanrım!"},{"n":"4","t":"Ne mutlu senin evinde oturanlara, Seni sürekli överler! *"},{"n":"5","t":"Ne mutlu gücünü senden alan insana! Aklı hep Siyon'u ziyaret etmekte."},{"n":"6","t":"Baka Vadisi'nden geçerken, Pınar başına çevirirler orayı, İlk yağmurlar orayı berekete boğar."},{"n":"7","t":"Gittikçe güçlenir, Siyon'da Tanrı'nın huzuruna çıkarlar."},{"n":"8","t":"Ya RAB, Her Şeye Egemen Tanrı, duamı dinle, Kulak ver, ey Yakup'un Tanrısı!"},{"n":"9","t":"Ey Tanrı, kalkanımıza bak, Meshettiğin* krala lütfet!"},{"n":"10","t":"Senin avlularında bir gün, Başka yerdeki bin günden iyidir; Kötülerin çadırında yaşamaktansa, Tanrım'ın evinin eşiğinde durmayı yeğlerim."},{"n":"11","t":"Çünkü RAB Tanrı bir güneş, bir kalkandır. Lütuf ve yücelik sağlar; Dürüstçe yaşayanlardan hiçbir iyiliği esirgemez."},{"n":"12","t":"Ey Her Şeye Egemen RAB, Ne mutlu sana güvenen insana!"}]},{"id":85,"name":"85. MezmurMüzik şefi için - Korahoğulları'nın mezmuru","verses":[{"n":"1","t":"Ya RAB, ülkenden hoşnut kaldın, Yakup soyunu eski gönencine kavuşturdun."},{"n":"2","t":"Halkının suçlarını bağışladın, Bütün günahlarını yok saydın. *"},{"n":"3","t":"Bütün gazabını bir yana koydun, Kızgın öfkenden vazgeçtin."},{"n":"4","t":"Ey bizi kurtaran Tanrı, bizi eski halimize getir, Bize karşı öfkeni dindir!"},{"n":"5","t":"Sonsuza dek mi öfkeleneceksin bize? Kuşaktan kuşağa mı sürdüreceksin öfkeni?"},{"n":"6","t":"Halkın sende sevinç bulsun diye Bize yeniden yaşam vermeyecek misin?"},{"n":"7","t":"Ya RAB, sevgini göster bize, Kurtarışını bağışla!"},{"n":"8","t":"Kulak vereceğim RAB Tanrı'nın ne diyeceğine; Halkına, sadık kullarına esenlik sözü verecek, Yeter ki, bir daha akılsızlık etmesinler."},{"n":"9","t":"Evet, O kendisinden korkanları kurtarmak üzeredir, Görkemi ülkemizde yaşasın diye."},{"n":"10","t":"Sevgiyle sadakat buluşacak, Doğrulukla esenlik öpüşecek."},{"n":"11","t":"Sadakat yerden bitecek, Doğruluk gökten bakacak."},{"n":"12","t":"Ve RAB iyi olan neyse, onu verecek, Toprağımızdan ürün fışkıracak."},{"n":"13","t":"Doğruluk önüsıra yürüyecek, Adımları için yol yapacak."}]},{"id":86,"name":"86. MezmurDavut'un duası","verses":[{"n":"1","t":"Kulak ver, ya RAB, yanıtla beni, Çünkü mazlum ve yoksulum."},{"n":"2","t":"Koru canımı, çünkü senin sadık kulunum. Ey Tanrım, kurtar sana güvenen kulunu!"},{"n":"3","t":"Acı bana, ya Rab, Çünkü gün boyu sana yakarıyorum."},{"n":"4","t":"Sevindir kulunu, ya Rab, Çünkü dualarımı sana yükseltiyorum."},{"n":"5","t":"Sen iyi ve bağışlayıcısın, ya Rab, Sana yakaran herkese bol sevgi gösterirsin."},{"n":"6","t":"Kulak ver duama, ya RAB, Yalvarışlarımı dikkate al!"},{"n":"7","t":"Sıkıntılı günümde sana yakarırım, Çünkü yanıtlarsın beni."},{"n":"8","t":"İlahlar arasında senin gibisi yok, ya Rab, Eşsizdir işlerin."},{"n":"9","t":"Yarattığın bütün uluslar gelip Sana tapınacaklar, ya Rab, Adını yüceltecekler."},{"n":"10","t":"Çünkü sen ulusun, harikalar yaratırsın, Tek Tanrı sensin."},{"n":"11","t":"Ya RAB, yolunu bana öğret, Senin gerçeğine göre yürüyeyim, Kararlı kıl beni, yalnız senin adından korkayım."},{"n":"12","t":"Ya Rab Tanrım, bütün yüreğimle sana şükredeceğim, Adını sonsuza dek yücelteceğim."},{"n":"13","t":"Çünkü bana sevgin büyüktür, Canımı ölüler diyarının derinliklerinden sen kurtardın."},{"n":"14","t":"Ey Tanrı, küstahlar bana saldırıyor, Zorbalar sürüsü, sana aldırmayanlar Canımı almak istiyor,"},{"n":"15","t":"Oysa sen, ya Rab, Sevecen, lütfeden, tez öfkelenmeyen, Sevgisi ve sadakati bol bir Tanrı'sın."},{"n":"16","t":"Yönel bana, acı halime, Kuluna kendi gücünü ver, Kurtar hizmetçinin oğlunu."},{"n":"17","t":"İyiliğinin bir belirtisini göster bana; Benden nefret edenler görüp utansın; Çünkü sen, ya RAB, bana yardım ettin, Beni avuttun."}]},{"id":87,"name":"87. MezmurKorahoğulları'nın mezmuru - İlahi","verses":[{"n":"1","t":"RAB Siyon'u kutsal dağlar üzerine kurdu."},{"n":"2","t":"Siyon'un kapılarını Yakup soyunun bütün konutlarından daha çok sever."},{"n":"3","t":"Ey Tanrı kenti, senin için ne yüce sözler söylenir: *"},{"n":"4","t":"\"Beni tanıyanlar arasında Rahav*fl* ve Babil'i anacağım, Filist'i, Sur'u, Kûş'u* da; 'Bu da Siyon'da doğdu diyeceğim.\" 87:4 \"Rahav\": Mısır'ı simgeliyor."},{"n":"5","t":"Evet, Siyon için şöyle denecek: \"Şu da orada doğmuş, bu da, Yüceler Yücesi onu sarsılmaz kılacak.\""},{"n":"6","t":"RAB halkları kaydederken, \"Bu da Siyon'da doğmuş\" diye yazacak."},{"n":"7","t":"Okuyucular, kavalcılar, \"Bütün kaynaklarım sendedir!\" diyecek."}]},{"id":88,"name":"88. MezmurKorahoğulları'nın mezmuru - İlahi - Müzik şefi için - \"Mahalat Leannot\" makamında Ezrahlı Heman'ın Maskili","verses":[{"n":"1","t":"Ya RAB, beni kurtaran Tanrı, Gece gündüz sana yakarıyorum."},{"n":"2","t":"Duam sana erişsin, Kulak ver yakarışıma."},{"n":"3","t":"Çünkü sıkıntıya doydum, Canım ölüler diyarına yaklaştı."},{"n":"4","t":"Ölüm çukuruna inenler arasında sayılıyorum, Tükenmiş gibiyim;"},{"n":"5","t":"Ölüler arasına atılmış, Artık anımsamadığın, İlginden yoksun, Mezarda yatan cesetler gibiyim."},{"n":"6","t":"Beni çukurun dibine, Karanlıklara, derinliklere attın."},{"n":"7","t":"Öfken üzerime çöktü, Dalga dalga kızgınlığınla beni ezdin. *"},{"n":"8","t":"Yakınlarımı benden uzaklaştırdın, İğrenç kıldın beni gözlerinde. Kapalı kaldım, çıkamıyorum."},{"n":"9","t":"Üzüntüden gözlerimin feri sönüyor, Her gün sana yakarıyorum, ya RAB, Ellerimi sana açıyorum."},{"n":"10","t":"Harikalarını ölülere mi göstereceksin? Ölüler mi kalkıp seni övecek?"},{"n":"11","t":"Sevgin mezarda, Sadakatin yıkım diyarında duyurulur mu?"},{"n":"12","t":"Karanlıklarda harikaların, Unutulmuşluk diyarında doğruluğun bilinir mi?"},{"n":"13","t":"Ama ben, ya RAB, yardıma çağırıyorum seni, Sabah duam sana varıyor."},{"n":"14","t":"Niçin beni reddediyorsun, ya RAB, Neden yüzünü benden gizliyorsun?"},{"n":"15","t":"Düşkünüm, gençliğimden beri ölümle burun burunayım, Dehşetlerinin altında tükendim."},{"n":"16","t":"Şiddetli gazabın üzerimden geçti, Saçtığın dehşet beni yedi bitirdi."},{"n":"17","t":"Bütün gün su gibi kuşattılar beni, Çevremi tümüyle sardılar."},{"n":"18","t":"Eşi dostu benden uzaklaştırdın, Tek dostum karanlık kaldı."}]},{"id":89,"name":"89. MezmurEzrahlı Eytan'ın Maskili","verses":[{"n":"1","t":"RAB'bin sevgisini sonsuza dek ezgilerle öveceğim, Sadakatini bütün kuşaklara bildireceğim."},{"n":"2","t":"Sevgin sonsuza dek ayakta kalır diyeceğim, Sadakatini gökler kadar kalıcı kıldın."},{"n":"3","t":"Dedin ki, \"Seçtiğim adamla antlaşma yaptım, Kulum Davut'a şöyle ant içtim:"},{"n":"4","t":"'Soyunu sonsuza dek sürdüreceğim, Tahtını kuşaklar boyunca sürekli kılacağım.\" *"},{"n":"5","t":"Ya RAB, gökler över harikalarını, Kutsallar topluluğunda övülür sadakatin."},{"n":"6","t":"Çünkü göklerde RAB'be kim eş koşulur? Kim benzer RAB'be ilahi varlıklar arasında?"},{"n":"7","t":"Kutsallar topluluğunda Tanrı korku uyandırır, Çevresindekilerin hepsinden ulu ve müthiştir."},{"n":"8","t":"Ya RAB, Her Şeye Egemen Tanrı, Senin gibi güçlü RAB var mı? Sadakatin çevreni sarar."},{"n":"9","t":"Sen kudurmuş denizler üzerinde egemenlik sürer, Dalgalar kabardıkça onları dindirirsin."},{"n":"10","t":"Sen Rahav'ı*fm* leş ezer gibi ezdin, Güçlü kolunla düşmanlarını dağıttın.D"},{"n":"10","t":"\"Rahav\": Deniz, deniz canavarı ya da Mısır gibi güçlüdüşmanları kastediyor."},{"n":"11","t":"Gökler senindir, yeryüzü de senin; Dünyanın ve içindeki her şeyin temelini sen attın."},{"n":"12","t":"Kuzeyi, güneyi sen yarattın, Tavor ve Hermon dağları Sana sevincini dile getiriyor."},{"n":"13","t":"Kolun güçlüdür, Elin kudretli, sağ elin yüce."},{"n":"14","t":"Tahtın adalet ve doğruluk üzerine kurulu, Sevgi ve sadakat önünsıra gider."},{"n":"15","t":"Ne mutlu sevinç çığlıkları atmasını bilen halka, ya RAB! Yüzünün ışığında yürürler."},{"n":"16","t":"Gün boyu senin adınla sevinir, Doğruluğunla yücelirler."},{"n":"17","t":"Çünkü sen onların gücü ve yüceliğisin, Lütfun sayesinde gücümüz artar."},{"n":"18","t":"Kalkanımız RAB'be, Kralımız İsrail'in Kutsalı'na aittir."},{"n":"19","t":"Geçmişte bir görüm aracılığıyla, Sadık kullarına şöyle dedin: \"Bir yiğide yardım ettim, Halkın içinden bir genci yükselttim."},{"n":"20","t":"Kulum Davut'u buldum, Kutsal yağımla onu meshettim*."},{"n":"21","t":"Elim ona destek olacak, Kolum güç verecek."},{"n":"22","t":"Düşman onu haraca bağlayamayacak*fn*, Kötüler onu ezmeyecek.D"},{"n":"22","t":"\"Haraca bağlayamayacak\" ya da \"Aldatamayacak\"."},{"n":"23","t":"Düşmanlarını onun önünde kıracağım, Ondan nefret edenleri vuracağım."},{"n":"24","t":"Sadakatim, sevgim ona destek olacak, Benim adımla gücü yükselecek."},{"n":"25","t":"Sağ elini denizin, Irmakların üzerine egemen kılacağım."},{"n":"26","t":"'Babam sensin diye seslenecek bana, 'Tanrım, kurtuluşumun kayası."},{"n":"27","t":"Ben de onu ilk oğlum, Dünyadaki kralların en yücesi kılacağım."},{"n":"28","t":"Sonsuza dek ona sevgi göstereceğim, Onunla yaptığım antlaşma hiç bozulmayacak."},{"n":"29","t":"Soyunu sonsuza dek, Tahtını gökler durduğu sürece sürdüreceğim."},{"n":"30","t":"\"Çocukları yasamdan ayrılır, İlkelerime göre yaşamazsa;"},{"n":"31","t":"Kurallarımı bozar, Buyruklarıma uymazsa,"},{"n":"32","t":"İsyanlarını sopayla, Suçlarını dayakla cezalandıracağım."},{"n":"33","t":"Ama onu sevmekten vazgeçmeyecek, Sadakatime sırt çevirmeyeceğim."},{"n":"34","t":"Antlaşmamı bozmayacak, Ağzımdan çıkan sözü değiştirmeyeceğim."},{"n":"35","t":"Bir kez kutsallığım üstüne ant içtim, Davut'a yalan söylemeyeceğim."},{"n":"36","t":"Onun soyu sonsuza dek sürecek, Tahtı karşımda güneş gibi duracak,"},{"n":"37","t":"Göklerde güvenilir bir tanık olan ay gibi Sonsuza dek kalacak.\""},{"n":"38","t":"Ama sen reddettin, sırt çevirdin, Çok öfkelendin meshettiğin* krala."},{"n":"39","t":"Kulunla yaptığın antlaşmadan vazgeçtin, Onun tacını yere atıp kirlettin."},{"n":"40","t":"Yıktın bütün surlarını, Viran ettin kalelerini."},{"n":"41","t":"Yoldan geçen herkes onu yağmaladı, Yüzkarası oldu komşularına."},{"n":"42","t":"Hasımlarının sağ elini onun üstüne kaldırdın, Bütün düşmanlarını sevindirdin."},{"n":"43","t":"Kılıcının ağzını başka yöne çevirdin, Savaşta ona yan çıkmadın."},{"n":"44","t":"Görkemine son verdin, Tahtını yere çaldın."},{"n":"45","t":"Gençlik günlerini kısalttın, Onu utanca boğdun."},{"n":"46","t":"Ne zamana dek, ya RAB? Sonsuza dek mi gizleneceksin? Ne zamana dek öfken alev alev yanacak?"},{"n":"47","t":"Anımsa ömrümün ne çabuk geçtiğini, Ne boş yaratmışsın insanoğlunu!"},{"n":"48","t":"Var mı yaşayıp da ölümü görmeyen, Ölüler diyarının pençesinden canını kurtaran?"},{"n":"49","t":"Ya Rab, nerede o eski sevgin? Davut'a göstereceğine ant içtiğin o sadık sevgin!"},{"n":"50-51","t":"Anımsa, ya Rab, kullarının nasıl rezil olduğunu, Bütün halkların hakaretini bağrımda nasıl taşıdığımı, Düşmanlarının hakaretini, ya RAB, Meshettiğin kralın attığı adıma edilen hakaretleri."},{"n":"52","t":"Sonsuza dek övgüler olsun RAB'be! Amin! Amin!"}]},{"id":90,"name":"90. MezmurTanrı adamı Musa'nın duası","verses":[{"n":"1","t":"Ya Rab, barınak oldun bize Kuşaklar boyunca."},{"n":"2","t":"Dağlar var olmadan, Daha evreni ve dünyayı yaratmadan, Öncesizlikten sonsuzluğa dek Tanrı sensin."},{"n":"3","t":"İnsanı toprağa döndürürsün, \"Ey insanoğulları, toprağa dönün!\" diyerek."},{"n":"4","t":"Çünkü senin gözünde bin yıl Geçmiş bir gün, dün gibi, Bir gece nöbeti gibidir."},{"n":"5","t":"İnsanları bir düş gibi siler, süpürürsün, Sabah biten ot misali:"},{"n":"6","t":"Sabah filizlenir, büyür, Akşam solar, kurur."},{"n":"7","t":"Eriyip bitiyoruz senin öfkenden, Kızgınlığından dehşete düşüyoruz."},{"n":"8","t":"Suçlarımızı önüne, Gizli günahlarımızı yüzünün ışığına çıkardın."},{"n":"9","t":"Gazabından kısalıyor günlerimiz, Bir soluk gibi tükeniyor yıllarımız."},{"n":"10","t":"Ömrümüz yetmiş yıl sürüyor, Bilemedin seksen, o da sağlıklıysak; En güzel yıllar da zahmetle, kederle geçiyor, Çabucak bitiyor, uçup gidiyoruz."},{"n":"11","t":"Kim bilir gazabının gücünü? Çünkü öfken sana duyulan korku kadar güçlüdür."},{"n":"12","t":"Bu yüzden günlerimizi saymayı bize öğret ki, Bilgelik kazanalım."},{"n":"13","t":"Vazgeç, ya RAB! Öfken ne zamana dek sürecek? Acı kullarına!"},{"n":"14","t":"Sabah bizi sevginle doyur, Ömrümüz boyunca sevinçle haykıralım."},{"n":"15","t":"Kaç gün bizi sıkıntıya soktunsa, Kaç yıl çile çektirdinse, O kadar sevindir bizi."},{"n":"16","t":"Yaptıkların kullarına, Görkemin onların çocuklarına görünsün."},{"n":"17","t":"Tanrımız Rab bizden hoşnut kalsın. Ellerimizin emeğini boşa çıkarma. Evet, ellerimizin emeğini boşa çıkarma."}]},{"id":91,"name":"91. Mezmur","verses":[{"n":"1","t":"Yüceler Yücesi'nin barınağında oturan, Her Şeye Gücü Yeten'in gölgesinde barınır."},{"n":"2","t":"\"O benim sığınağım, kalemdir\" derim RAB için, \"Tanrım'dır, O'na güvenirim.\""},{"n":"3","t":"Çünkü O seni avcı tuzağından, Ölümcül hastalıktan kurtarır."},{"n":"4","t":"Seni kanatlarının altına alır, Onların altına sığınırsın. O'nun sadakati senin kalkanın, siperin olur."},{"n":"5-6","t":"Ne gecenin dehşetinden korkarsın, Ne gündüz uçan oktan, Ne karanlıkta dolaşan hastalıktan, Ne de öğleyin yok eden kırgından."},{"n":"7","t":"Yanında bin kişi, Sağında on bin kişi kırılsa bile, Sana dokunmaz."},{"n":"8","t":"Sen yalnız kendi gözlerinle seyredecek, Kötülerin cezasını göreceksin."},{"n":"9","t":"Sen RAB'bi kendine sığınak, Yüceler Yücesi'ni konut edindiğin için,"},{"n":"10","t":"Başına kötülük gelmeyecek, Çadırına felaket yaklaşmayacak."},{"n":"11","t":"Çünkü Tanrı meleklerine buyruk verecek, Gideceğin her yerde seni korusunlar diye."},{"n":"12","t":"Elleri üzerinde taşıyacaklar seni, Ayağın bir taşa çarpmasın diye."},{"n":"13","t":"Aslanın, kobranın üzerine basıp geçeceksin, Genç aslanı, yılanı çiğneyeceksin."},{"n":"14","t":"\"Beni sevdiği için Onu kurtaracağım\" diyor RAB, \"Beni iyi tanıdığı için Ona kale olacağım."},{"n":"15","t":"Bana seslenince onu yanıtlayacağım, Sıkıntıda onun yanında olacağım, Kurtarıp yücelteceğim onu."},{"n":"16","t":"Onu uzun ömürle doyuracak, Ona kurtarışımı göstereceğim.\""}]},{"id":92,"name":"92. Mezmur - Şabat Günü* için ilahi","verses":[{"n":"1-3","t":"Ya RAB, sana şükretmek, Ey Yüceler Yücesi, adını ilahilerle övmek, Sabah sevgini, Gece sadakatini, On telli sazla, çenk ve lirle duyurmak ne güzel!"},{"n":"4","t":"Çünkü yaptıklarınla beni sevindirdin, ya RAB, Ellerinin işi karşısında sevinç ilahileri okuyorum."},{"n":"5","t":"Yaptıkların ne büyüktür, ya RAB, Düşüncelerin ne derin!"},{"n":"6","t":"Aptal insan bilemez, Budala akıl erdiremez:"},{"n":"7","t":"Kötüler mantar gibi bitse, Suçlular pıtrak gibi açsa bile, Bu onların sonsuza dek yok oluşu demektir."},{"n":"8","t":"Ama sen sonsuza dek yücesin, ya RAB."},{"n":"9","t":"Ya RAB, düşmanların kesinlikle, Evet, kesinlikle yok olacak, Suç işleyen herkes dağılacak."},{"n":"10","t":"Beni yaban öküzü kadar güçlü kıldın, Taze zeytinyağını başıma döktün."},{"n":"11","t":"Gözlerim düşmanlarımın bozgununu gördü, Kulaklarım bana saldıran kötülerin sonunu duydu."},{"n":"12","t":"Doğru insan hurma ağacı gibi serpilecek, Lübnan sediri gibi yükselecek."},{"n":"13","t":"RAB'bin evinde dikilmiş, Tanrımız'ın avlularında serpilecek."},{"n":"14","t":"Böyleleri yaşlanınca da meyve verecek, Taptaze ve yeşil kalacaklar."},{"n":"15","t":"\"RAB doğrudur! Kayamdır benim! O'nda haksızlık bulunmaz!\" diye duyuracaklar."}]},{"id":93,"name":"93. Mezmur","verses":[{"n":"1","t":"RAB egemenlik sürüyor, görkeme bürünmüş, Kudret giyinip kuşanmış. Dünya sağlam kurulmuş, sarsılmaz."},{"n":"2","t":"Ya RAB, tahtın öteden beri kurulmuş, Varlığın öncesizliğe uzanır."},{"n":"3","t":"Denizler gürlüyor, ya RAB, Denizler gümbür gümbür gürlüyor, Denizler dalgalarını çınlatıyor."},{"n":"4","t":"Yücelerdeki RAB engin suların gürleyişinden, Denizlerin azgın dalgalarından Daha güçlüdür."},{"n":"5","t":"Koşulların hep geçerlidir; Tapınağına kutsallık yaraşır Sonsuza dek, ya RAB."}]},{"id":94,"name":"94. Mezmur","verses":[{"n":"1","t":"Ya RAB, öç alıcı Tanrı, Saç ışığını, ey öç alıcı Tanrı!"},{"n":"2","t":"Kalk, ey yeryüzünün yargıcı, Küstahlara hak ettikleri cezayı ver!"},{"n":"3","t":"Kötüler ne zamana dek, ya RAB, Ne zamana dek sevinip coşacak?"},{"n":"4","t":"Ağızlarından küstahlık dökülüyor, Suç işleyen herkes övünüyor."},{"n":"5","t":"Halkını eziyorlar, ya RAB, Kendi halkına eziyet ediyorlar."},{"n":"6","t":"Dulu, garibi boğazlıyor, Öksüzleri öldürüyorlar."},{"n":"7","t":"\"RAB görmez\" diyorlar, \"Yakup'un Tanrısı dikkat etmez.\""},{"n":"8","t":"Ey halkın içindeki budalalar, dikkat edin; Ey aptallar, ne zaman akıllanacaksınız?"},{"n":"9","t":"Kulağı yaratan işitmez mi? Göze biçim veren görmez mi?"},{"n":"10","t":"Ulusları yola getiren yargılamaz mı? İnsanı eğiten bilmez mi?"},{"n":"11","t":"RAB insanın düşüncelerinin Boş olduğunu bilir."},{"n":"12","t":"Ne mutlu, ya RAB, yola getirdiğin, Yasanı öğrettiğin insana!"},{"n":"13","t":"Kötüler için çukur kazılıncaya dek, Onu sıkıntılı günlerden kurtarıp rahatlatırsın."},{"n":"14","t":"Çünkü RAB halkını reddetmez, Kendi halkını terk etmez."},{"n":"15","t":"Adalet yine doğruluk üzerine kurulacak, Yüreği temiz olan herkes ona uyacak."},{"n":"16","t":"Kötülere karşı beni kim savunacak? Kim benim için suçlulara karşı duracak?"},{"n":"17","t":"RAB yardımcım olmasaydı, Şimdiye dek sessizlik diyarına göçmüştüm bile."},{"n":"18","t":"\"Ayağım kayıyor\" dediğimde, Sevgin ayakta tutar beni, ya RAB."},{"n":"19","t":"Kaygılar içimi sarınca, Senin avutmaların gönlümü sevindirir."},{"n":"20","t":"Yasaya dayanarak haksızlık yapan koltuk sahibi Seninle bağdaşır mı?"},{"n":"21","t":"Onlar doğruya karşı birleşiyor, Suçsuzu ölüme mahkûm ediyorlar."},{"n":"22","t":"Ama RAB bana kale oldu, Tanrım sığındığım kaya oldu."},{"n":"23","t":"Tanrımız RAB yaptıkları kötülüğü Kendi başlarına getirecek, Kötülükleri yüzünden köklerini kurutacak, Evet, köklerini kurutacak."}]},{"id":95,"name":"95. Mezmur","verses":[{"n":"1","t":"Gelin, RAB'be sevinçle haykıralım, Bizi kurtaran kayaya sevinç çığlıkları atalım,"},{"n":"2","t":"Şükranla huzuruna çıkalım, O'na sevinç ilahileri yükseltelim!"},{"n":"3","t":"Çünkü RAB ulu Tanrı'dır, Bütün ilahların üstünde ulu kraldır."},{"n":"4","t":"Yerin derinlikleri O'nun elindedir, Dağların dorukları da O'nun."},{"n":"5","t":"Deniz O'nundur, çünkü O yarattı, Karaya da O'nun elleri biçim verdi."},{"n":"6","t":"Gelin, tapınalım, eğilelim, Bizi yaratan RAB'bin önünde diz çökelim."},{"n":"7","t":"Çünkü O Tanrımız'dır, Bizse O'nun otlağının halkı, Elinin altındaki koyunlarız. Bugün sesini duyarsanız,"},{"n":"8","t":"Meriva'da*fo*, o gün çölde, Massa'da*fö* olduğu gibi, Yüreklerinizi nasırlaştırmayın.D"},{"n":"8","t":"\"Meriva\": \"Çıkışma\" anlamına gelir (bkz. Çık.17:7). 95:8 \"Massa\": \"Deneme\" anlamına gelir (bkz. Çık.17:7)."},{"n":"9","t":"Yaptıklarımı görmelerine karşın, Atalarınız orada beni sınayıp denediler."},{"n":"10","t":"Kırk yıl o kuşaktan hep iğrendim, \"Yüreği kötü yola sapan bir halktır\" dedim, \"Yollarımı bilmiyorlar.\""},{"n":"11","t":"Bu yüzden öfkeyle ant içtim: \"Huzur diyarıma*fp* asla girmeyecekler!\"D"},{"n":"11","t":"\"Huzur diyarıma\", yani \"Vaat edilen toprağa\" (bkz. Say.14:26-35; İbr.4:1-7)."}]},{"id":96,"name":"96. Mezmur(1Ta.16:23-33)","verses":[{"n":"1","t":"Yeni bir ezgi söyleyin RAB'be! Ey bütün dünya, RAB'be ezgiler söyleyin!"},{"n":"2","t":"Ezgi söyleyin, RAB'bin adını övün, Her gün duyurun kurtarışını!"},{"n":"3","t":"Görkemini uluslara, Harikalarını bütün halklara anlatın!"},{"n":"4","t":"Çünkü RAB uludur, yalnız O övgüye değer, İlahlardan çok O'ndan korkulur."},{"n":"5","t":"Halkların bütün ilahları bir hiçtir, Oysa gökleri yaratan RAB'dir."},{"n":"6","t":"Yücelik, ululuk O'nun huzurundadır, Güç ve güzellik O'nun tapınağındadır."},{"n":"7","t":"Ey bütün halklar, RAB'bi övün, RAB'bin gücünü, yüceliğini övün,"},{"n":"8","t":"RAB'bin görkemini adına yaraşır biçimde övün, Sunular getirip avlularına girin!"},{"n":"9","t":"Kutsal giysiler içinde RAB'be tapının! Titreyin O'nun önünde, ey bütün yeryüzündekiler!"},{"n":"10","t":"Uluslara, \"RAB egemenlik sürüyor\" deyin. Dünya sağlam kurulmuş, sarsılmaz. O halkları adaletle yargılar."},{"n":"11","t":"Sevinsin gökler, coşsun yeryüzü! Gürlesin deniz içindekilerle birlikte!"},{"n":"12-13","t":"Bayram etsin kırlar ve üzerindekiler! O zaman RAB'bin önünde bütün orman ağaçları Sevinçle haykıracak. Çünkü O geliyor! Yeryüzünü yargılamaya geliyor. Dünyayı adaletle, Halkları kendi gerçeğiyle yönetecek."}]},{"id":97,"name":"97. Mezmur","verses":[{"n":"1","t":"RAB egemenlik sürüyor, coşsun yeryüzü, Bütün kıyı halkları sevinsin!"},{"n":"2","t":"Bulut ve zifiri karanlık sarmış çevresini, Doğruluk ve adalettir tahtının temeli."},{"n":"3","t":"Ateş yürüyor O'nun önünde, Düşmanlarını yakıyor çevrede."},{"n":"4","t":"Şimşekleri dünyayı aydınlatır, Yeryüzü görüp titrer."},{"n":"5","t":"Dağlar balmumu gibi erir, RAB'bin, bütün yeryüzünün Rab'bi önünde."},{"n":"6","t":"Gökler O'nun doğruluğunu duyurur, Bütün halklar görkemini görür."},{"n":"7","t":"Utansın puta tapanlar, Değersiz putlarla övünenler! RAB'be tapın, ey bütün ilahlar!"},{"n":"8","t":"Siyon seviniyor yargılarını duyunca, ya RAB, Yahuda kentleri coşuyor."},{"n":"9","t":"Çünkü sensin, ya RAB, bütün yeryüzünün en yücesi, Bütün ilahların üstündesin, çok ulusun."},{"n":"10","t":"Ey sizler, RAB'bi sevenler, kötülükten tiksinin. O sadık kullarının canını korur, Onları kötülerin elinden kurtarır."},{"n":"11","t":"Doğrulara ışık, Temiz yüreklilere sevinç saçar."},{"n":"12","t":"Ey doğrular, RAB'de sevinç bulun, Kutsallığını anarak O'na şükredin!"}]},{"id":98,"name":"98. Mezmur","verses":[{"n":"1","t":"Yeni bir ezgi söyleyin RAB'be. Çünkü harikalar yaptı, Zaferler kazandı sağ eli ve kutsal koluyla."},{"n":"2","t":"RAB ulusların gözü önüne serdi kurtarışını, Zaferini bildirdi."},{"n":"3","t":"İsrail halkına sevgisini, Sadakatini anımsadı; Tanrımız'ın zaferini gördü dünyanın dört bucağı."},{"n":"4","t":"Sevinç çığlıkları yükseltin RAB'be, ey yeryüzündekiler! Sevinç ilahileriyle yeri göğü çınlatın!"},{"n":"5","t":"Lirle ezgiler sunun RAB'be, Lir ve müzik eşliğinde!"},{"n":"6","t":"Boru ve borazan eşliğinde Sevinç çığlıkları atın Kral olan RAB'bin önünde."},{"n":"7","t":"Gürlesin deniz ve içindekiler, Gürlesin yeryüzü ve üzerindekiler."},{"n":"8-9","t":"El çırpsın ırmaklar, Sevinçle haykırsın dağlar RAB'bin önünde! Çünkü O geliyor Yeryüzünü yönetmeye. Dünyayı adaletle, Halkları doğrulukla yönetecek."}]},{"id":99,"name":"99. Mezmur","verses":[{"n":"1","t":"RAB egemenlik sürüyor, titresin halklar! Keruvlar* arasında tahtına oturmuş, Sarsılsın yeryüzü!"},{"n":"2","t":"RAB Siyon'da uludur, Yücedir O, bütün halklara egemendir."},{"n":"3","t":"Övsünler büyük, müthiş adını! O kutsaldır."},{"n":"4","t":"Ey adaleti seven güçlü kral, Eşitliği sen sağladın, Yakup soyunda doğru ve adil olanı sen yaptın."},{"n":"5","t":"Yüceltin Tanrımız RAB'bi, Ayaklarının taburesi önünde tapının! O kutsaldır."},{"n":"6","t":"Musa'yla Harun O'nun kâhinlerindendi, Samuel de O'na yakaranlar arasında. RAB'be seslenirlerdi, O da yanıtlardı."},{"n":"7","t":"Bulut sütunu içinden onlarla konuştu, Uydular O'nun buyruklarına, Kendilerine verdiği kurallara."},{"n":"8","t":"Ya RAB Tanrımız, yanıt verdin onlara; Bağışlayıcı bir Tanrı oldun, Ama yaptıkları kötülüğü cezasız bırakmadın."},{"n":"9","t":"Tanrımız RAB'bi yüceltin, Tapının O'na kutsal dağında! Çünkü Tanrımız RAB kutsaldır."}]},{"id":100,"name":"100. Mezmur - Şükretmek için","verses":[{"n":"1","t":"Ey bütün dünya, RAB'be sevinç çığlıkları yükseltin!"},{"n":"2","t":"O'na neşeyle kulluk edin, Sevinç ezgileriyle çıkın huzuruna!"},{"n":"3","t":"Bilin ki RAB Tanrı'dır. Bizi yaratan O'dur, biz de O'nunuz*fr*, O'nun halkı, otlağının koyunlarıyız.D"},{"n":"3","t":"\"Biz de O'nunuz\" ya da \"Kendimiz değil\"."},{"n":"4","t":"Kapılarına şükranla, Avlularına övgüyle girin! Şükredin O'na, adına övgüler sunun!"},{"n":"5","t":"Çünkü RAB iyidir, Sevgisi sonsuzdur. Sadakati kuşaklar boyunca sürer."}]},{"id":101,"name":"101. MezmurDavut'un mezmuru","verses":[{"n":"1","t":"Sevgini ve adaletini ezgilerle anacağım, Seni ilahilerle öveceğim, ya RAB."},{"n":"2","t":"Dürüst davranmaya özen göstereceğim, Ne zaman geleceksin bana? Temiz bir yaşam süreceğim evimde,"},{"n":"3","t":"Önümde alçaklığa izin vermeyeceğim. Tiksinirim döneklerin işinden, Etkilemez beni."},{"n":"4","t":"Uzak olsun benden sapıklık, Tanımak istemem kötülüğü."},{"n":"5","t":"Yok ederim dostunu gizlice çekiştireni, Katlanamam tepeden bakan, gururlu insana."},{"n":"6","t":"Gözüm ülkenin sadık insanları üzerinde olacak, Yanımda oturmalarını isterim; Bana dürüst yaşayan kişi hizmet edecek."},{"n":"7","t":"Dolap çeviren evimde oturmayacak, Yalan söyleyen gözümün önünde durmayacak."},{"n":"8","t":"Her sabah ülkedeki kötüleri yok ederek Bütün haksızları RAB'bin kentinden söküp atacağım."}]},{"id":102,"name":"102. MezmurZayıf düşünce derdini RAB'be döken mazlumun duası","verses":[{"n":"1","t":"Ya RAB, duamı işit, Yakarışım sana erişsin."},{"n":"2","t":"Sıkıntılı günümde yüzünü benden gizleme, Kulak ver sesime, Seslenince yanıt ver bana hemen."},{"n":"3","t":"Çünkü günlerim duman gibi yok oluyor, Kemiklerim ateş gibi yanıyor."},{"n":"4","t":"Yüreğim kırgın yemiş ot gibi kurudu, Ekmek yemeyi bile unuttum."},{"n":"5","t":"Bir deri bir kemiğe döndüm Acı acı inlemekten."},{"n":"6","t":"Issız yerlerdeki ishakkuşunu andırıyorum, Viranelerdeki kukumav gibiyim."},{"n":"7","t":"Gözüme uyku girmiyor, Damda yalnız kalmış bir kuş gibiyim."},{"n":"8","t":"Düşmanlarım bütün gün bana hakaret ediyor, Bana dil uzatanlar adımı lanet için kullanıyor."},{"n":"9-10","t":"Kızıp öfkelendiğin için Külü ekmek gibi yiyor, İçeceğime gözyaşı katıyorum. Beni kaldırıp bir yana attın."},{"n":"11","t":"Günlerim akşam uzayan gölge gibi yitmekte, Ot gibi sararmaktayım."},{"n":"12","t":"Ama sen, sonsuza dek tahtında oturursun, ya RAB, Ünün kuşaklar boyu sürer."},{"n":"13","t":"Kalkıp Siyon'a sevecenlik göstereceksin, Çünkü onu kayırmanın zamanıdır, beklenen zaman geldi."},{"n":"14","t":"Kulların onun taşlarından hoşlanır, Tozunu bile severler."},{"n":"15","t":"Uluslar RAB'bin adından, Yeryüzü kralları görkeminden korkacak."},{"n":"16","t":"Çünkü RAB Siyon'u yeniden kuracak, Görkem içinde görünecek."},{"n":"17","t":"Yoksulların duasına kulak verecek, Yalvarışlarını asla hor görmeyecek."},{"n":"18","t":"Bunlar gelecek kuşak için yazılsın, Öyle ki, henüz doğmamış insanlar RAB'be övgüler sunsun."},{"n":"19","t":"RAB yücelerdeki kutsal katından aşağı baktı, Göklerden yeryüzünü gözetledi,"},{"n":"20","t":"Tutsakların iniltisini duymak, Ölüm mahkûmlarını kurtarmak için."},{"n":"21-22","t":"Böylece halklar ve krallıklar RAB'be tapınmak için toplanınca, O'nun adı Siyon'da, Övgüsü Yeruşalim'de duyurulacak."},{"n":"23","t":"RAB gücümü kırdı yaşam yolunda, Ömrümü kısalttı."},{"n":"24","t":"\"Ey Tanrım, ömrümün ortasında canımı alma!\" dedim. \"Senin yılların kuşaklar boyu sürer!"},{"n":"25","t":"\"Çok önceden attın dünyanın temellerini, Gökler de senin ellerinin yapıtıdır."},{"n":"26","t":"Onlar yok olacak, ama sen kalıcısın. Hepsi bir giysi gibi eskiyecek. Onları bir kaftan gibi değiştireceksin, Geçip gidecekler."},{"n":"27","t":"Ama sen hep aynısın, Yılların tükenmeyecek."},{"n":"28","t":"Gözetiminde yaşayacak kullarının çocukları, Senin önünde duracak soyları.\""}]},{"id":103,"name":"103. MezmurDavut'un mezmuru","verses":[{"n":"1","t":"RAB'be övgüler sun, ey gönlüm! O'nun kutsal adına övgüler sun, ey bütün varlığım!"},{"n":"2","t":"RAB'be övgüler sun, ey canım! İyiliklerinin hiçbirini unutma!"},{"n":"3","t":"Bütün suçlarını bağışlayan, Bütün hastalıklarını iyileştiren,"},{"n":"4","t":"Canını ölüm çukurundan kurtaran, Sana sevgi ve sevecenlik tacı giydiren,"},{"n":"5","t":"Yaşam boyu seni iyiliklerle doyuran O'dur, Bu nedenle gençliğin kartalınki gibi tazelenir."},{"n":"6","t":"RAB bütün düşkünlere Hak ve adalet sağlar."},{"n":"7","t":"Kendi yöntemlerini Musa'ya, İşlerini İsrailliler'e açıkladı."},{"n":"8","t":"RAB sevecen ve lütfedendir, Tez öfkelenmez, sevgisi engindir."},{"n":"9","t":"Sürekli suçlamaz, Öfkesini sonsuza dek sürdürmez."},{"n":"10","t":"Bize günahlarımıza göre davranmaz, Suçlarımızın karşılığını vermez."},{"n":"11","t":"Çünkü gökler yeryüzünden ne kadar yüksekse, Kendisinden korkanlara karşı sevgisi de o kadar büyüktür."},{"n":"12","t":"Doğu batıdan ne kadar uzaksa, O kadar uzaklaştırdı bizden isyanlarımızı."},{"n":"13","t":"Bir baba çocuklarına nasıl sevecen davranırsa, RAB de kendisinden korkanlara öyle sevecen davranır."},{"n":"14","t":"Çünkü mayamızı bilir, Toprak olduğumuzu anımsar."},{"n":"15","t":"İnsana gelince, ota benzer ömrü, Kır çiçeği gibi serpilir;"},{"n":"16","t":"Rüzgar üzerine esince yok olur gider, Bulunduğu yer onu tanımaz."},{"n":"17-18","t":"Ama RAB kendisinden korkanları sonsuza dek sever, Antlaşmasına uyan Ve buyruklarına uymayı anımsayan soylarına adil davranır."},{"n":"19","t":"RAB tahtını göklere kurmuştur, O'nun egemenliği her yeri kapsar."},{"n":"20","t":"RAB'be övgüler sunun, ey sizler, O'nun melekleri, O'nun sözünü dinleyen, Söylediklerini yerine getiren güç sahipleri!"},{"n":"21","t":"RAB'be övgüler sunun, ey sizler, O'nun bütün göksel orduları, İsteğini yerine getiren kulları!"},{"n":"22","t":"RAB'be övgüler sunun, Ey O'nun egemen olduğu yerlerdeki bütün yaratıklar! RAB'be övgüler sun, ey gönlüm!"}]},{"id":104,"name":"104. Mezmur","verses":[{"n":"1","t":"RAB'be övgüler sun, ey gönlüm! Ya RAB Tanrım, ne ulusun! Görkem ve yücelik kuşanmışsın,"},{"n":"2","t":"Bir kaftana bürünür gibi ışığa bürünmüşsün. Gökleri bir çadır gibi geren,"},{"n":"3","t":"Evini yukarıdaki sular üzerine kuran, Bulutları kendine savaş arabası yapan, Rüzgarın kanatları üzerinde gezen,"},{"n":"4","t":"Rüzgarları kendine haberci, Yıldırımları hizmetkâr eden sensin*fs*.D"},{"n":"4","t":"\"Rüzgarları kendine haberci, yıldırımları hizmetkâr eden sensin\" ya da \"Meleklerini rüzgarlar, hizmetkârlarını ateş alevleri yapan sensin\"."},{"n":"5","t":"Yeryüzünü temeller üzerine kurdun, Asla sarsılmasın diye."},{"n":"6","t":"Engini ona bir giysi gibi giydirdin, Sular dağların üzerinde durdu."},{"n":"7","t":"Sen kükreyince sular kaçtı, Göğü gürletince hemen çekildi."},{"n":"8","t":"Dağları aşıp derelere aktı, Onlar için belirlediğin yerlere doğru."},{"n":"9","t":"Bir sınır koydun önlerine, Geçmesinler, gelip yeryüzünü bir daha kaplamasınlar diye."},{"n":"10","t":"Vadilerde fışkırttığın pınarlar, Dağların arasından akar."},{"n":"11","t":"Bütün kır hayvanlarını suvarır, Yaban eşeklerinin susuzluğunu giderirler."},{"n":"12","t":"Kuşlar yanlarında yuva kurar, Dalların arasında ötüşürler."},{"n":"13","t":"Gökteki evinden dağları sularsın, Yeryüzü işlerinin meyvesine doyar."},{"n":"14","t":"Hayvanlar için ot, İnsanların yararı için bitkiler yetiştirirsin; İnsanlar ekmeğini topraktan çıkarsın diye,"},{"n":"15","t":"Yüreklerini sevindiren şarabı, Yüzlerini güldüren zeytinyağını, Güçlerini arttıran ekmeği hep sen verirsin."},{"n":"16","t":"RAB'bin ağaçları, Kendi diktiği Lübnan sedirleri suya doyar."},{"n":"17","t":"Kuşlar orada yuva yapar, Leyleğin evi ise çamlardadır."},{"n":"18","t":"Yüksek dağlar dağ keçilerinin uğrağı, Kayalar kaya tavşanlarının* sığınağıdır."},{"n":"19","t":"Mevsimleri göstersin diye ayı, Batacağı zamanı bilen güneşi yarattın."},{"n":"20","t":"Karartırsın ortalığı, gece olur, Başlar kıpırdamaya orman hayvanları."},{"n":"21","t":"Genç aslan av peşinde kükrer, Tanrı'dan yiyecek ister."},{"n":"22","t":"Güneş doğunca İnlerine çekilir, yatarlar."},{"n":"23","t":"İnsan işine gider, Akşama dek çalışmak için."},{"n":"24","t":"Ya RAB, ne çok eserin var! Hepsini bilgece yaptın; Yeryüzü yarattıklarınla dolu."},{"n":"25","t":"İşte uçsuz bucaksız denizler, İçinde kaynaşan sayısız canlılar, Büyük küçük yaratıklar."},{"n":"26","t":"Orada gemiler dolaşır, İçinde oynaşsın diye yarattığın Livyatan* da orada."},{"n":"27","t":"Hepsi seni bekliyor, Yiyeceklerini zamanında veresin diye."},{"n":"28","t":"Sen verince onlar toplar, Sen elini açınca onlar iyiliğe doyar."},{"n":"29","t":"Yüzünü gizleyince dehşete kapılırlar, Soluklarını kesince ölüp toprak olurlar."},{"n":"30","t":"Ruhun'u gönderince var olurlar, Yeryüzüne yeni yaşam verirsin."},{"n":"31","t":"RAB'bin görkemi sonsuza dek sürsün! Sevinsin RAB yaptıklarıyla!"},{"n":"32","t":"O bakınca yeryüzü titrer, O dokununca dağlar tüter."},{"n":"33","t":"Ömrümce RAB'be ezgiler söyleyecek, Var oldukça Tanrım'ı ilahilerle öveceğim."},{"n":"34","t":"Düşüncem ona hoş görünsün, Sevincim RAB olsun!"},{"n":"35","t":"Tükensin dünyadaki günahlılar, Yok olsun artık kötüler! RAB'be övgüler sun, ey gönlüm! RAB'be övgüler sunun!"}]},{"id":105,"name":"105. Mezmur(1Ta.16:8-22)","verses":[{"n":"1","t":"RAB'be şükredin, O'na yakarın, Halklara duyurun yaptıklarını!"},{"n":"2","t":"O'nu ezgilerle, ilahilerle övün, Bütün harikalarını anlatın!"},{"n":"3","t":"Kutsal adıyla övünün, Sevinsin RAB'be yönelenler!"},{"n":"4","t":"RAB'be ve O'nun gücüne bakın, Durmadan O'nun yüzünü arayın!"},{"n":"5-6","t":"Ey sizler, kulu İbrahim'in soyu, Seçtiği Yakupoğulları, O'nun yaptığı harikaları, Olağanüstü işlerini Ve ağzından çıkan yargıları anımsayın!"},{"n":"7","t":"Tanrımız RAB O'dur, Yargıları bütün yeryüzünü kapsar."},{"n":"8-9","t":"O antlaşmasını, Bin kuşak için verdiği sözü, İbrahim'le yaptığı antlaşmayı, İshak için içtiği andı sonsuza dek anımsar."},{"n":"10-11","t":"\"Hakkınıza düşen mülk olarak Kenan ülkesini size vereceğim\" diyerek, Bunu Yakup için bir kural, İsrail'le sonsuza dek geçerli bir antlaşma yaptı."},{"n":"12","t":"O zaman bir avuç insandılar, Sayıca az ve ülkeye yabancıydılar."},{"n":"13","t":"Bir ulustan öbürüne, Bir ülkeden ötekine dolaşıp durdular."},{"n":"14","t":"RAB kimsenin onları ezmesine izin vermedi, Onlar için kralları bile payladı:"},{"n":"15","t":"\"Meshettiklerime* dokunmayın, Peygamberlerime kötülük etmeyin!\" dedi."},{"n":"16","t":"Ülkeye kıtlık gönderdi, Bütün yiyeceklerini yok etti."},{"n":"17","t":"Önlerinden bir adam göndermişti, Köle olarak satılan Yusuf'tu bu."},{"n":"18","t":"Zincir vurup incittiler ayaklarını, Demir halka geçirdiler boynuna,"},{"n":"19","t":"Söyledikleri gerçekleşinceye dek, RAB'bin sözü onu sınadı."},{"n":"20","t":"Kral adam gönderip Yusuf'u salıverdi, Halklara egemen olan onu özgür kıldı."},{"n":"21","t":"Onu kendi sarayının efendisi, Bütün varlığının sorumlusu yaptı;"},{"n":"22","t":"Önderlerini istediği gibi eğitsin, İleri gelenlerine akıl versin diye."},{"n":"23","t":"O zaman İsrail Mısır'a gitti, Yakup Ham ülkesine yerleşti."},{"n":"24","t":"RAB halkını alabildiğine çoğalttı, Düşmanlarından sayıca arttırdı onları."},{"n":"25","t":"Sonunda tutumunu değiştirdi düşmanlarının: Halkından tiksindiler, Kullarına kurnazca davrandılar."},{"n":"26","t":"Kulu Musa'yı, Seçtiği Harun'u gönderdi aralarına."},{"n":"27","t":"Onlar gösterdiler RAB'bin belirtilerini, Ham ülkesinde şaşılası işlerini."},{"n":"28","t":"Karanlık gönderip ülkeyi karanlığa bürüdü RAB, Çünkü Mısırlılar O'nun sözlerine karşı gelmişti."},{"n":"29","t":"Kana çevirdi sularını, Öldürdü balıklarını."},{"n":"30","t":"Ülkede kurbağalar kaynaştı Krallarının odalarına kadar."},{"n":"31","t":"RAB buyurunca sinek sürüleri, Sivrisinekler üşüştü ülkenin her yanına."},{"n":"32","t":"Dolu yağdırdı yağmur yerine, Şimşekler çaktırdı ülkelerinde."},{"n":"33","t":"Bağlarını, incir ağaçlarını vurdu, Parçaladı ülkenin ağaçlarını."},{"n":"34","t":"O buyurunca çekirgeler, Sayısız yavrular kaynadı."},{"n":"35","t":"Ülkenin bütün bitkilerini yediler, Toprağın ürününü yiyip bitirdiler."},{"n":"36","t":"RAB ülkede ilk doğanların hepsini, İlk çocuklarını öldürdü."},{"n":"37","t":"İsrailliler'i ülkeden altın ve gümüşle çıkardı, Oymaklarından tek kişi bile tökezlemedi."},{"n":"38","t":"Onlar gidince Mısır sevindi, Çünkü İsrail korkusu çökmüştü Mısır'ın üzerine."},{"n":"39","t":"RAB bulutu bir örtü gibi yaydı üzerlerine, Gece ateş verdi yollarını aydınlatsın diye."},{"n":"40","t":"İstediler, bıldırcın gönderdi, Göksel ekmekle doyurdu karınlarını."},{"n":"41","t":"Kayayı yardı, sular fışkırdı, Çorak topraklarda bir ırmak gibi aktı."},{"n":"42","t":"Çünkü kutsal sözünü, Kulu İbrahim'e verdiği sözü anımsadı."},{"n":"43","t":"Halkını sevinç içinde, Seçtiklerini sevinç çığlıklarıyla ülkeden çıkardı."},{"n":"44","t":"Ulusların topraklarını verdi onlara. Halkların emeğini miras aldılar;"},{"n":"45","t":"Kurallarını yerine getirsinler, Yasalarına uysunlar diye. RAB'be övgüler sunun!"}]},{"id":106,"name":"106. Mezmur(1Ta.16:34-36)","verses":[{"n":"1","t":"Övgüler sunun, RAB'be! RAB'be şükredin, çünkü O iyidir, Sevgisi sonsuzdur."},{"n":"2","t":"RAB'bin büyük işlerini kim anlatabilir, Kim O'na yeterince övgü sunabilir?"},{"n":"3","t":"Ne mutlu adalete uyanlara, Sürekli doğru olanı yapanlara!"},{"n":"4","t":"Ya RAB, halkına lütfettiğinde anımsa beni, Onları kurtardığında ilgilen benimle."},{"n":"5","t":"Öyle ki, seçtiklerinin gönencini göreyim, Ulusunun sevincini, Kendi halkının kıvancını paylaşayım."},{"n":"6","t":"Atalarımız gibi biz de günah işledik, Suç işledik, kötülük ettik."},{"n":"7","t":"Atalarımız Mısır'dayken Yaptığın harikaları anlamadı, Çok kez gösterdiğin sevgiyi anımsamadı, Denizde, Kızıldeniz'de* başkaldırdılar."},{"n":"8","t":"Buna karşın RAB gücünü göstermek için, Adı uğruna kurtardı onları."},{"n":"9","t":"Kızıldeniz'i azarladı, kurudu deniz, Yürüdüler enginde O'nun öncülüğünde, Çölde yürür gibi."},{"n":"10","t":"Kendilerinden nefret edenlerin elinden aldı onları, Düşmanlarının pençesinden kurtardı."},{"n":"11","t":"Sular yuttu hasımlarını, Hiçbiri kurtulmadı."},{"n":"12","t":"O zaman atalarımız O'nun sözlerine inandılar, Ezgiler söyleyerek O'nu övdüler."},{"n":"13","t":"Ne var ki, RAB'bin yaptıklarını çabucak unuttular, Öğüt vermesini beklemediler."},{"n":"14","t":"Özlemle kıvrandılar çölde, Tanrı'yı denediler ıssız yerlerde."},{"n":"15","t":"Tanrı onlara istediklerini verdi, Ama üzerlerine yıpratıcı bir hastalık gönderdi."},{"n":"16","t":"Onlar ordugahlarında Musa'yı, RAB'bin kutsal kulu Harun'u kıskanınca,"},{"n":"17","t":"Yer yarıldı ve Datan'ı yuttu, Aviram'la yandaşlarının üzerine kapandı."},{"n":"18","t":"Ateş kavurdu onları izleyenleri, Alev yaktı kötüleri."},{"n":"19","t":"Bir buzağı heykeli yaptılar Horev'de, Dökme bir puta tapındılar."},{"n":"20","t":"Tanrı'nın yüceliğini, Ot yiyen öküz putuna değiştirdiler."},{"n":"21","t":"Unuttular kendilerini kurtaran Tanrı'yı, Mısır'da yaptığı büyük işleri,"},{"n":"22","t":"Ham ülkesinde yarattığı harikaları, Kızıldeniz kıyısında yaptığı müthiş işleri."},{"n":"23","t":"Bu yüzden onları yok edeceğini söyledi Tanrı, Ama seçkin kulu Musa O'nun önündeki gedikte durarak, Yok edici öfkesinden vazgeçirdi O'nu."},{"n":"24","t":"Ardından hor gördüler güzelim ülkeyi, Tanrı'nın verdiği söze inanmadılar."},{"n":"25","t":"Çadırlarında söylendiler, Dinlemediler RAB'bin sesini."},{"n":"26-27","t":"Bu yüzden RAB elini kaldırdıVe çölde onları yere sereceğine, Soylarını ulusların arasına saçacağına, Onları öteki ülkelere dağıtacağına ant içti."},{"n":"28","t":"Sonra Baal-Peor'a bel bağladılar, Ölülere sunulan kurbanları yediler."},{"n":"29","t":"Öfkelendirdiler RAB'bi yaptıklarıyla, Salgın hastalık çıktı aralarında."},{"n":"30","t":"Ama Pinehas kalkıp araya girdi, Felaketi önledi."},{"n":"31","t":"Bu doğruluk sayıldı ona, Kuşaklar boyu, sonsuza dek sürecek bu."},{"n":"32","t":"Yine RAB'bi öfkelendirdiler Meriva suları yanında, Musa'nın başına dert açıldı onlar yüzünden;"},{"n":"33","t":"Çünkü onu sinirlendirdiler, O da düşünmeden konuştu."},{"n":"34","t":"RAB'bin onlara buyurduğu gibi Yok etmediler halkları,"},{"n":"35","t":"Tersine öteki uluslara karıştılar, Onların törelerini öğrendiler."},{"n":"36","t":"Putlarına taptılar, Bu da onlara tuzak oldu."},{"n":"37","t":"Oğullarını, kızlarınıCinlere kurban ettiler."},{"n":"38","t":"Kenan putlarına kurban olsun diye Oğullarının, kızlarının kanını, Suçsuzların kanını döktüler; Ülke onların kanıyla kirlendi."},{"n":"39","t":"Böylece yaptıklarıyla kirli sayıldılar, Vefasız duruma düştüler töreleriyle."},{"n":"40","t":"RAB'bin öfkesi parladı halkına karşı, Tiksindi kendi halkından."},{"n":"41","t":"Onları ulusların eline teslim etti. Onlardan nefret edenler onlara egemen oldu."},{"n":"42","t":"Düşmanları onları ezdi, Boyun eğdirdi hepsine."},{"n":"43","t":"RAB onları birçok kez kurtardı, Ama akılları fikirleri başkaldırmaktaydı Ve alçaltıldılar suçları yüzünden."},{"n":"44","t":"RAB yine de ilgilendi sıkıntılarıyla Yakarışlarını duyunca."},{"n":"45","t":"Antlaşmasını anımsadı onlar uğruna, Eşsiz sevgisinden ötürü vazgeçti yapacaklarından."},{"n":"46","t":"Merhamet koydu onları tutsak alanların yüreğine."},{"n":"47","t":"Kurtar bizi, ey Tanrımız RAB, Topla bizi ulusların arasından. Kutsal adına şükredelim, Yüceliğinle övünelim."},{"n":"48","t":"Öncesizlikten sonsuza dek, İsrail'in Tanrısı RAB'be övgüler olsun! Bütün halk, \"Amin!\" desin. RAB'be övgüler olsun!"}]},{"id":107,"name":"107. Mezmur","verses":[{"n":"1","t":"RAB'be şükredin, çünkü O iyidir, Sevgisi sonsuzdur."},{"n":"2","t":"Böyle desin RAB'bin kurtardıkları, Düşman pençesinden özgür kıldıkları,"},{"n":"3","t":"Doğudan, batıdan, kuzeyden, güneyden*fş*, Bütün ülkelerden topladıkları.D"},{"n":"3","t":"\"Güneyden\": İbranice \"Denizden\"."},{"n":"4","t":"Issız çöllerde dolaştılar, Yerleşecekleri kente giden bir yol bulamadılar."},{"n":"5","t":"Aç, susuz, Sefil oldular."},{"n":"6","t":"O zaman sıkıntı içinde RAB'be yakardılar, RAB kurtardı onları dertlerinden."},{"n":"7","t":"Yerleşecekleri bir kente varıncaya dek, Onlara doğru yolda öncülük etti."},{"n":"8","t":"Şükretsinler RAB'be sevgisi için, İnsanlar yararına yaptığı harikalar için."},{"n":"9","t":"Çünkü O susamış canın susuzluğunu giderir, Aç canı iyiliklerle doyurur."},{"n":"10","t":"Zincire vurulmuş, acıyla kıvranan tutsaklar, Karanlıkta, zifiri karanlıkta oturmuştu."},{"n":"11","t":"Çünkü Tanrı'nın buyruklarına karşı çıkmışlardı, Küçümsemişlerdi Yüceler Yücesi'nin öğüdünü."},{"n":"12","t":"Ağır işlerle hayatı onlara zehir etti, Çöktüler, yardım eden olmadı."},{"n":"13","t":"O zaman sıkıntı içinde RAB'be yakardılar, RAB kurtardı onları dertlerinden;"},{"n":"14","t":"Çıkardı karanlıktan, zifiri karanlıktan, Kopardı zincirlerini."},{"n":"15","t":"Şükretsinler RAB'be sevgisi için, İnsanlar yararına yaptığı harikalar için!"},{"n":"16","t":"Çünkü tunç* kapıları kırdı, Demir kapı kollarını parçaladı O."},{"n":"17","t":"Cezalarını buldu aptallar, Suçları, isyanları yüzünden."},{"n":"18","t":"İğrenir olmuşlardı bütün yemeklerden, Ölümün kapılarına yaklaşmışlardı."},{"n":"19","t":"O zaman sıkıntı içinde RAB'be yakardılar, RAB kurtardı onları dertlerinden."},{"n":"20","t":"Sözünü gönderip iyileştirdi onları, Kurtardı ölüm çukurundan."},{"n":"21","t":"Şükretsinler RAB'be sevgisi için, İnsanlar yararına yaptığı harikalar için!"},{"n":"22","t":"Şükran kurbanları sunsunlar Ve sevinç çığlıklarıyla duyursunlar O'nun yaptıklarını!"},{"n":"23","t":"Gemilerle denize açılanlar, Okyanuslarda iş yapanlar,"},{"n":"24","t":"RAB'bin işlerini, Derinliklerde yaptığı harikaları gördüler."},{"n":"25","t":"Çünkü O buyurunca şiddetli bir fırtına koptu, Dalgalar şaha kalktı."},{"n":"26","t":"Göklere yükselip diplere indi gemiler, Sıkıntıdan canları burunlarına geldi gemicilerin,"},{"n":"27","t":"Sarhoş gibi sallanıp sendelediler, Ustalıkları işe yaramadı."},{"n":"28","t":"O zaman sıkıntı içinde RAB'be yakardılar, RAB kurtardı onları dertlerinden."},{"n":"29","t":"Fırtınayı limanlığa çevirdi, Yatıştı dalgalar;"},{"n":"30","t":"Rahatlayınca sevindiler, Diledikleri limana götürdü RAB onları."},{"n":"31","t":"Şükretsinler RAB'be sevgisi için, İnsanlar yararına yaptığı harikalar için!"},{"n":"32","t":"Yüceltsinler O'nu halk topluluğunda, Övgüler sunsunlar ileri gelenlerin toplantısında."},{"n":"33","t":"Irmakları çöle çevirir, Pınarları kurak toprağa,"},{"n":"34","t":"Verimli toprağı çorak alana, Orada yaşayanların kötülüğü yüzünden."},{"n":"35","t":"Çölü su birikintisine çevirir, Kuru toprağı pınara."},{"n":"36","t":"Açları yerleştirir oraya; Oturacak bir kent kursunlar,"},{"n":"37","t":"Tarlalar ekip bağlar diksinler, Bol ürün alsınlar diye."},{"n":"38","t":"RAB'bin kutsamasıyla, Çoğaldılar alabildiğine, Eksiltmedi hayvanlarını."},{"n":"39","t":"Sonra azaldılar, alçaldılar, Baskı, sıkıntı ve acı yüzünden."},{"n":"40","t":"RAB rezalet saçtı soylular üzerine, Yolu izi belirsiz bir çölde dolaştırdı onları."},{"n":"41","t":"Ama yoksulu sefaletten kurtardı, Davar sürüsü gibi çoğalttı ailelerini."},{"n":"42","t":"Doğru insanlar görüp sevinecek, Kötülerse ağzını kapayacak."},{"n":"43","t":"Aklı olan bunları göz önünde tutsun, RAB'bin sevgisini dikkate alsın."}]},{"id":108,"name":"108. Mezmur(Mez.57: 7-11; 60:5-12)Ezgi - Davut'un mezmuru","verses":[{"n":"1","t":"Kararlıyım, ey Tanrı, Bütün varlığımla sana ezgiler, ilahiler söyleyeceğim!"},{"n":"2","t":"Uyan, ey lir, ey çenk, Seheri ben uyandırayım!"},{"n":"3","t":"Halkların arasında sana şükürler sunayım, ya RAB, Ulusların arasında seni ilahilerle öveyim."},{"n":"4","t":"Çünkü sevgin göklere erişir, Sadakatin gökyüzüne ulaşır."},{"n":"5","t":"Yüceliğini göster göklerin üstünde, ey Tanrı, Görkemin bütün yeryüzünü kaplasın!"},{"n":"6","t":"Kurtar bizi sağ elinle, yardım et, Sevdiklerin özgürlüğe kavuşsun diye!"},{"n":"7","t":"Tanrı şöyle konuştu kutsal yerinde: \"Şekem'i sevinçle bölüştürecek, Sukkot Vadisi'ni ölçeceğim."},{"n":"8","t":"Gilat benimdir, Manaşşe de benim, Efrayim miğferim, Yahuda asam."},{"n":"9","t":"Moav yıkanma leğenim, Edom'un üzerine çarığımı fırlatacağım*ft*, Filist'e zaferle haykıracağım.\"D"},{"n":"9","t":"\"Çarığımı fırlatacağım\": Eski törelere göre çarığınfırlatılması, bir yerin sahiplenilmesi anlamına geliyordu."},{"n":"10","t":"Kim beni surlu kente götürecek? Kim bana Edom'a kadar yol gösterecek?"},{"n":"11","t":"Ey Tanrı, sen bizi reddetmedin mi? Ordularımıza öncülük etmiyor musun artık?"},{"n":"12","t":"Yardım et bize düşmana karşı, Çünkü boştur insan yardımı."},{"n":"13","t":"Tanrı'yla zafer kazanırız, O çiğner düşmanlarımızı."}]},{"id":109,"name":"109. MezmurMüzik şefi için - Davut'un mezmuru","verses":[{"n":"1","t":"Ey övgüler sunduğum Tanrı, Sessiz kalma!"},{"n":"2","t":"Çünkü kötüler, yalancılar Bana karşı ağzını açtı, Karalıyorlar beni."},{"n":"3","t":"Nefret dolu sözlerle beni kuşatıp Yok yere bana savaş açtılar."},{"n":"4","t":"Sevgime karşılık bana düşman oldular, Bense dua etmekteyim."},{"n":"5","t":"İyiliğime kötülük, Sevgime nefretle karşılık verdiler."},{"n":"6","t":"Kötü bir adam koy düşmanın başına, Sağında onu suçlayan biri dursun!D"},{"n":"6-19","t":"Bazı uzmanlara göre bu ayetler Davut'un düşmanlarının konuşmasıdır."},{"n":"7","t":"Yargılanınca suçlu çıksın, Duası bile günah sayılsın!"},{"n":"8","t":"Ömrü kısa olsun, Görevini bir başkası üstlensin!"},{"n":"9","t":"Çocukları öksüz, Karısı dul kalsın!"},{"n":"10","t":"Çocukları avare gezip dilensin, Yıkık evlerinden uzakta yiyecek arasın!"},{"n":"11","t":"Bütün malları tefecinin ağına düşsün, Emeğini yabancılar yağmalasın!"},{"n":"12","t":"Kimse ona sevgi göstermesin, Öksüzlerine acıyan olmasın!"},{"n":"13","t":"Soyu kurusun, Bir kuşak sonra adı silinsin!"},{"n":"14","t":"Atalarının suçları RAB'bin önünde anılsın, Annesinin günahı silinmesin!"},{"n":"15","t":"Günahları hep RAB'bin önünde dursun, RAB anılarını yok etsin yeryüzünden!"},{"n":"16","t":"Çünkü düşmanım sevgi göstermeyi düşünmedi, Ölesiye baskı yaptı mazluma, yoksula, Yüreği kırık insana."},{"n":"17","t":"Sevdiği lanet başına gelsin! Madem kutsamaktan hoşlanmıyor, Uzak olsun ondan kutsamak!"},{"n":"18","t":"Laneti bir giysi gibi giydi, Su gibi içine, yağ gibi kemiklerine işlesin lanet!"},{"n":"19","t":"Bir giysi gibi onu örtünsün, Bir kuşak gibi hep onu sarsın!*fu*"},{"n":"20","t":"Düşmanlarıma, beni kötüleyenlere, RAB böyle karşılık versin!"},{"n":"21","t":"Ama sen, ey Egemen RAB, Adın uğruna bana ilgi göster; Kurtar beni, iyiliğin, sevgin uğruna!"},{"n":"22","t":"Çünkü düşkün ve yoksulum, Yüreğim yaralı içimde."},{"n":"23","t":"Batan güneş gibi geçip gidiyorum, Çekirge gibi silkilip atılıyorum."},{"n":"24","t":"Dizlerim titriyor oruç* tutmaktan; Bir deri bir kemiğe döndüm."},{"n":"25","t":"Düşmanlarıma yüzkarası oldum; Beni görünce kafalarını sallıyorlar!"},{"n":"26","t":"Yardım et bana, ya RAB Tanrım; Kurtar beni sevgin uğruna!"},{"n":"27","t":"Bilsinler bu işte senin elin olduğunu, Bunu senin yaptığını, ya RAB!"},{"n":"28","t":"Varsın lanet etsin onlar, sen kutsa beni, Bana saldıranlar utanacak, Ben kulunsa sevineceğim."},{"n":"29","t":"Rezilliğe bürünsün beni suçlayanlar, Kaftan giyer gibi utançlarıyla örtünsünler!"},{"n":"30","t":"RAB'be çok şükredeceğim, Kalabalığın arasında O'na övgüler dizeceğim;"},{"n":"31","t":"Çünkü O yoksulun sağında durur, Onu yargılayanlardan kurtarmak için."}]},{"id":110,"name":"110. MezmurDavut'un mezmuru","verses":[{"n":"1","t":"RAB efendime: \"Ben düşmanlarını ayaklarının altına serinceye dek*fü* Sağımda otur\" diyor.D"},{"n":"1","t":"\"Ayaklarının altına serinceye dek\": İbranice \"Ayaklarına tabure yapıncaya dek\"."},{"n":"2","t":"RAB Siyon'dan uzatacak kudret asanı, Düşmanlarının ortasında egemenlik sür!"},{"n":"3","t":"Savaşacağın gün Gönüllü gidecek askerlerin. Seherin bağrından doğan çiy gibi Kutsal giysiler içinde Sana gelecek gençlerin."},{"n":"4","t":"RAB ant içti, kararından dönmez: \"Melkisedek düzeni uyarınca Sonsuza dek kâhinsin sen!\" dedi."},{"n":"5","t":"Rab senin sağındadır, Kralları ezecek öfkelendiği gün."},{"n":"6","t":"Ulusları yargılayacak, ortalığı cesetler dolduracak, Dünyanın dört bucağında başları ezecek."},{"n":"7","t":"Yol kenarındaki dereden su içecek; Bu yüzden başını dik tutacak."}]},{"id":111,"name":"111. Mezmur","verses":[{"n":"1","t":"Övgüler sunun RAB'be! Doğru insanların toplantısında, Topluluk içinde, Bütün yüreğimle RAB'be şükredeceğim."},{"n":"2","t":"RAB'bin işleri büyüktür, Onlardan zevk alanlar hep onları düşünür."},{"n":"3","t":"O'nun yaptıkları yüce ve görkemlidir, Doğruluğu sonsuza dek sürer."},{"n":"4","t":"RAB unutulmayacak harikalar yaptı, O sevecen ve lütfedendir."},{"n":"5","t":"Kendisinden korkanları besler, Antlaşmasını sonsuza dek anımsar."},{"n":"6","t":"Ulusların topraklarını kendi halkına vermekle Gösterdi onlara işlerinin gücünü."},{"n":"7","t":"Yaptığı her işte sadık ve adildir, Bütün koşulları güvenilirdir;"},{"n":"8","t":"Sonsuza dek sürer, Sadakat ve doğrulukla yapılır."},{"n":"9","t":"O halkının kurtuluşunu sağladı, Antlaşmasını sonsuza dek geçerli kıldı. Adı kutsal ve müthiştir."},{"n":"10","t":"Bilgeliğin temeli RAB korkusudur, O'nun kurallarını yerine getiren herkes Sağduyu sahibi olur. O'na sonsuza dek övgü sunulur!"}]},{"id":112,"name":"112. Mezmur","verses":[{"n":"1","t":"Övgüler sunun RAB'be! Ne mutlu RAB'den korkan insana, O'nun buyruklarından büyük zevk alana!"},{"n":"2","t":"Soyu yeryüzünde güç kazanacak, Doğruların kuşağı kutsanacak."},{"n":"3","t":"Bolluk ve zenginlik eksilmez evinden, Sonsuza dek sürer doğruluğu."},{"n":"4","t":"Karanlıkta ışık doğar dürüstler için, Lütfeden, sevecen, doğru insanlar için."},{"n":"5","t":"Ne mutlu eli açık olan, ödünç veren, İşlerini adaletle yürüten insana!"},{"n":"6","t":"Asla sarsılmaz, Sonsuza dek anılır doğru insan."},{"n":"7","t":"Kötü haberden korkmaz, Yüreği sarsılmaz, RAB'be güvenir."},{"n":"8","t":"Gözü pektir, korku nedir bilmez, Sonunda düşmanlarının yenilgisini görür."},{"n":"9","t":"Armağanlar dağıttı, yoksullara verdi; Doğruluğu sonsuza dek kalıcıdır, Gücü ve saygınlığı artar."},{"n":"10","t":"Kötü kişi bunu görünce kudurur, Dişlerini gıcırdatır, kendi kendini yer, bitirir. Kötülerin dileği boşa çıkar."}]},{"id":113,"name":"113. Mezmur","verses":[{"n":"1","t":"Övgüler sunun RAB'be! Övgüler sunun, ey RAB'bin kulları, RAB'bin adına övgüler sunun!"},{"n":"2","t":"Şimdiden sonsuza dek RAB'bin adına şükürler olsun!"},{"n":"3","t":"Güneşin doğduğu yerden battığı yere kadar RAB'bin adına övgüler sunulmalı!"},{"n":"4","t":"RAB bütün uluslara egemendir, Görkemi gökleri aşar."},{"n":"5","t":"Var mı Tanrımız RAB gibi, Yücelerde oturan,"},{"n":"6","t":"Göklerde ve yeryüzünde olanlara Bakmak için eğilen?"},{"n":"7","t":"Düşkünü yerden kaldırır, Yoksulu çöplükten çıkarır;"},{"n":"8","t":"Soylularla, Halkının soylularıyla birlikte oturtsun diye."},{"n":"9","t":"Kısır kadını evde oturtur, Çocuk sahibi mutlu bir anne kılar. RAB'be övgüler sunun!"}]},{"id":114,"name":"114. Mezmur","verses":[{"n":"1","t":"İsrail Mısır'dan çıktığında, Yakup'un soyu yabancı dil konuşan bir halktan ayrıldığında,"},{"n":"2","t":"Yahuda Rab'bin kutsal yeri oldu, İsrail de O'nun krallığı."},{"n":"3","t":"Deniz olanı görüp geri çekildi, Şeria Irmağı tersine aktı."},{"n":"4","t":"Dağlar koç gibi, Tepeler kuzu gibi sıçradı."},{"n":"5","t":"Ey deniz, sana ne oldu da kaçtın? Ey Şeria, neden tersine aktın?"},{"n":"6","t":"Ey dağlar, niçin koç gibi, Ey tepeler, niçin kuzu gibi sıçradınız?"},{"n":"7-8","t":"Titre, ey yeryüzü, Kayayı havuza, Çakmaktaşını pınara çeviren Rab'bin önünde, Yakup'un Tanrısı'nın huzurunda."}]},{"id":115,"name":"115. Mezmur(Mez.135:13-20)","verses":[{"n":"1","t":"Bizi değil, ya RAB, bizi değil, Sevgin ve sadakatin uğruna, Kendi adını yücelt!"},{"n":"2","t":"Niçin uluslar: \"Hani, nerede onların Tanrısı?\" desin."},{"n":"3","t":"Bizim Tanrımız göklerdedir, Ne isterse yapar."},{"n":"4","t":"Oysa onların putları altın ve gümüşten yapılmış, İnsan elinin eseridir."},{"n":"5","t":"Ağızları var, konuşmazlar, Gözleri var, görmezler,"},{"n":"6","t":"Kulakları var, duymazlar, Burunları var, koku almazlar,"},{"n":"7","t":"Elleri var, hissetmezler, Ayakları var, yürümezler, Boğazlarından ses çıkmaz."},{"n":"8","t":"Onları yapan, onlara güvenen herkes Onlar gibi olacak!"},{"n":"9","t":"Ey İsrail halkı, RAB'be güven, O'dur yardımcınız ve kalkanınız!"},{"n":"10","t":"Ey Harun soyu, RAB'be güven, O'dur yardımcınız ve kalkanınız!"},{"n":"11","t":"Ey RAB'den korkanlar, RAB'be güvenin, O'dur yardımcınız ve kalkanınız!"},{"n":"12","t":"RAB bizi anımsayıp kutsayacak, İsrail halkını, Harun soyunu kutsayacak."},{"n":"13","t":"Küçük, büyük, Kendisinden korkan herkesi kutsayacak."},{"n":"14","t":"RAB sizi, Sizi ve çocuklarınızı çoğaltsın!"},{"n":"15","t":"Yeri göğü yaratan RAB Sizleri kutsasın."},{"n":"16","t":"Göklerin öteleri RAB'bindir, Ama yeryüzünü insanlara vermiştir."},{"n":"17","t":"Ölüler, sessizlik diyarına inenler, RAB'be övgüler sunmaz;"},{"n":"18","t":"Biziz RAB'bi öven, Şimdiden sonsuza dek. RAB'be övgüler sunun!"}]},{"id":116,"name":"116. Mezmur","verses":[{"n":"1","t":"RAB'bi seviyorum, Çünkü O feryadımı duyar."},{"n":"2","t":"Bana kulak verdiği için, Yaşadığım sürece O'na sesleneceğim."},{"n":"3","t":"Ölüm iplerine dolaşmıştım, Ölüler diyarının kâbusu yakama yapışmıştı, Sıkıntıya, acıya gömülmüştüm."},{"n":"4","t":"O zaman RAB'be yakardım, \"Aman, ya RAB, kurtar canımı!\" dedim."},{"n":"5","t":"RAB lütufkâr ve adildir, Sevecendir Tanrımız."},{"n":"6","t":"RAB saf insanları korur, Tükendiğim zaman beni kurtardı."},{"n":"7","t":"Ey canım, yine huzura kavuş, Çünkü RAB sana iyilik etti."},{"n":"8","t":"Sen, ya RAB, canımı ölümden, Gözlerimi yaştan, Ayaklarımı sürçmekten kurtardın."},{"n":"9","t":"Yaşayanların diyarında, RAB'bin huzurunda yürüyeceğim."},{"n":"10","t":"İman ettim, \"Büyük acı çekiyorum\" dediğim zaman bile*fv*.D"},{"n":"10","t":"\"İman ettim, 'Büyük acı çekiyorum dediğim zaman bile\" ya da \"İman ettim, bu nedenle konuştum. Büyük acı çekiyorum\" (bkz. 2Ko.4:13)."},{"n":"11","t":"Şaşkınlık içinde, \"Bütün insanlar yalancı\" dedim."},{"n":"12","t":"Ne karşılık verebilirim RAB'be, Bana yaptığı onca iyilik için?"},{"n":"13","t":"Kurtuluş sunusu olarak kadeh kaldırıp RAB'be sesleneceğim."},{"n":"14","t":"Bütün halkının önünde, RAB'be adadıklarımı yerine getireceğim."},{"n":"15","t":"RAB'bin gözünde değerlidir*fy* Sadık kullarının ölümü.D"},{"n":"15","t":"\"Değerlidir\" ya da \"Acıdır\"."},{"n":"16","t":"Ya RAB, ben gerçekten senin kulunum; Kulun, hizmetçinin oğluyum, Sen çözdün bağlarımı."},{"n":"17","t":"Ya RAB, sana seslenecek, Şükran kurbanı sunacağım."},{"n":"18","t":"RAB'be adadıklarımı yerine getireceğim Bütün halkının önünde,"},{"n":"19","t":"RAB'bin Tapınağı'nın avlularında, Senin orta yerinde, ey Yeruşalim! RAB'be övgüler sunun!"}]},{"id":117,"name":"117. Mezmur","verses":[{"n":"1","t":"Ey bütün uluslar, RAB'be övgüler sunun! Ey bütün halklar, O'nu yüceltin!"},{"n":"2","t":"Çünkü bize beslediği sevgi büyüktür, RAB'bin sadakati sonsuza dek sürer. RAB'be övgüler sunun!"}]},{"id":118,"name":"118. Mezmur","verses":[{"n":"1","t":"RAB'be şükredin, çünkü O iyidir, Sevgisi sonsuzdur."},{"n":"2","t":"\"Sonsuzdur sevgisi!\" desin İsrail halkı."},{"n":"3","t":"\"Sonsuzdur sevgisi!\" desin Harun'un soyu."},{"n":"4","t":"\"Sonsuzdur sevgisi!\" desin RAB'den korkanlar."},{"n":"5","t":"Sıkıntı içinde RAB'be seslendim; Yanıtladı, rahata kavuşturdu beni."},{"n":"6","t":"RAB benden yana, korkmam; İnsan bana ne yapabilir?"},{"n":"7","t":"RAB benden yana, benim yardımcım, Benden nefret edenlerin sonuna zaferle bakacağım."},{"n":"8","t":"RAB'be sığınmak İnsana güvenmekten iyidir."},{"n":"9","t":"RAB'be sığınmak Soylulara güvenmekten iyidir."},{"n":"10","t":"Bütün uluslar beni kuşattı, RAB'bin adıyla püskürttüm onları."},{"n":"11","t":"Kuşattılar, sardılar beni, RAB'bin adıyla püskürttüm onları."},{"n":"12","t":"Arılar gibi sardılar beni, Ama diken ateşi gibi sönüverdiler; RAB'bin adıyla püskürttüm onları."},{"n":"13","t":"İtilip kakıldım*fz*, düşmek üzereydim, Ama RAB yardım etti bana.D"},{"n":"13","t":"Septuaginta, Süryanice \"İtilip kakıldım\", Masoretik metin \"Beni itip kaktın\"."},{"n":"14","t":"RAB gücüm ve ezgimdir, O kurtardı beni."},{"n":"15","t":"Sevinç ve zafer çığlıkları Çınlıyor doğruların çadırlarında: \"RAB'bin sağ eli güçlü işler yapar!"},{"n":"16","t":"RAB'bin sağ eli üstündür, RAB'bin sağ eli güçlü işler yapar!\""},{"n":"17","t":"Ölmeyecek, yaşayacağım, RAB'bin yaptıklarını duyuracağım."},{"n":"18","t":"RAB beni şiddetle yola getirdi, Ama ölüme terk etmedi."},{"n":"19","t":"Açın bana adalet kapılarını, Girip RAB'be şükredeyim."},{"n":"20","t":"İşte budur RAB'bin kapısı! Doğrular girebilir oradan."},{"n":"21","t":"Sana şükrederim, çünkü bana yanıt verdin, Kurtarıcım oldun."},{"n":"22","t":"Yapıcıların reddettiği taş, Köşenin baş taşı oldu."},{"n":"23","t":"RAB'bin işidir bu, Gözümüzde harika bir iş!"},{"n":"24","t":"Bugün RAB'bin yarattığı gündür, Onun için sevinip coşalım!"},{"n":"25","t":"Ne olur, ya RAB, kurtar bizi, Ne olur, başarılı kıl bizi!"},{"n":"26","t":"Kutsansın RAB'bin adıyla gelen! Kutsuyoruz sizi RAB'bin evinden."},{"n":"27","t":"RAB Tanrı'dır, aydınlattı bizi. İplerle bağlayın bayram kurbanını*fa*, İlerleyin sunağın boynuzlarına kadar.D"},{"n":"27","t":"\"İplerle bağlayın bayram kurbanını\" ya da \"Elinizdedallarla bayramı kutlayın\"."},{"n":"28","t":"Tanrım sensin, şükrederim sana, Tanrım sensin, yüceltirim seni."},{"n":"29","t":"RAB'be şükredin, çünkü O iyidir, Sevgisi sonsuzdur."}]},{"id":119,"name":"119. Mezmur (ALEF)*fb*","verses":[{"n":"1","t":"Ne mutlu yolları temiz olanlara, RAB'bin yasasına göre yaşayanlara!D Not Alef, beyt, vb. sözcükleri İbrani alfabesinin harfleridir.119. Mezmur akrostiş biçimde yazılmış bir şiirdir."},{"n":"2","t":"Ne mutlu O'nun öğütlerine uyanlara, Bütün yüreğiyle O'na yönelenlere!"},{"n":"3","t":"Hiç haksızlık etmezler, O'nun yolunda yürürler."},{"n":"4","t":"Koyduğun koşullara Dikkatle uyulmasını buyurdun."},{"n":"5","t":"Keşke kararlı olsam Senin kurallarına uymakta!"},{"n":"6","t":"Hiç utanmayacağım, Bütün buyruklarını izledikçe."},{"n":"7","t":"Şükredeceğim sana temiz yürekle, Adil hükümlerini öğrendikçe."},{"n":"8","t":"Kurallarını yerine getireceğim, Bırakma beni hiçbir zaman! (BEYT)"},{"n":"9","t":"Genç insan yolunu nasıl temiz tutar? Senin sözünü tutmakla."},{"n":"10","t":"Bütün yüreğimle sana yöneliyorum, İzin verme buyruklarından sapmama!"},{"n":"11","t":"Aklımdan çıkarmam sözünü, Sana karşı günah işlememek için."},{"n":"12","t":"Övgüler olsun sana, ya RAB, Bana kurallarını öğret."},{"n":"13","t":"Ağzından çıkan bütün hükümleri Dudaklarımla yineliyorum."},{"n":"14","t":"Sevinç duyuyorum öğütlerini izlerken, Sanki benim oluyor bütün hazineler."},{"n":"15","t":"Koşullarını derin derin düşünüyorum, Yollarını izlerken."},{"n":"16","t":"Zevk alıyorum kurallarından, Sözünü unutmayacağım. (GİMEL)"},{"n":"17","t":"Ben kuluna iyilik et ki yaşayayım, Sözüne uyayım."},{"n":"18","t":"Gözlerimi aç, Yasandaki harikaları göreyim."},{"n":"19","t":"Garibim bu dünyada, Buyruklarını benden gizleme!"},{"n":"20","t":"İçim tükeniyor, Her an hükümlerini özlemekten."},{"n":"21","t":"Buyruklarından sapan Lanetli küstahları azarlarsın."},{"n":"22","t":"Uzaklaştır benden küçümsemeleri, hakaretleri, Çünkü öğütlerini tutuyorum."},{"n":"23","t":"Önderler toplanıp beni kötüleseler bile, Ben kulun senin kurallarını derin derin düşüneceğim."},{"n":"24","t":"Öğütlerin benim zevkimdir, Bana akıl verirler. (DALET)"},{"n":"25","t":"Toza toprağa serildim, Sözün uyarınca yaşam ver bana."},{"n":"26","t":"Yaptıklarımı açıkladım, beni yanıtladın; Kurallarını öğret bana!"},{"n":"27","t":"Koşullarını anlamamı sağla ki, Harikalarının üzerinde düşüneyim."},{"n":"28","t":"İçim eriyor kederden, Sözün uyarınca güçlendir beni!"},{"n":"29","t":"Yalan yoldan uzaklaştır, Yasan uyarınca lütfet bana."},{"n":"30","t":"Ben sadakat yolunu seçtim, Hükümlerini uygun gördüm."},{"n":"31","t":"Öğütlerine dört elle sarıldım, ya RAB, Utandırma beni!"},{"n":"32","t":"İçime huzur verdiğin için Buyrukların doğrultusunda koşacağım. (HE)"},{"n":"33","t":"Kurallarını nasıl izleyeceğimi öğret bana, ya RAB, Öyle ki, onları sonuna kadar izleyeyim."},{"n":"34","t":"Anlamamı sağla, yasana uyayım, Bütün yüreğimle onu yerine getireyim."},{"n":"35","t":"Buyrukların doğrultusunda yol göster bana, Çünkü yolundan zevk alırım."},{"n":"36","t":"Yüreğimi haksız kazanca değil, Kendi öğütlerine yönelt."},{"n":"37","t":"Gözlerimi boş şeylerden*fc* çevir, Beni kendi yolunda yaşat.D"},{"n":"37","t":"\"Boş şeylerden\" ya da \"Değersiz putlardan\"."},{"n":"38","t":"Senden korkulması için Ben kuluna verdiğin sözü yerine getir."},{"n":"39","t":"Korktuğum hakaretten uzak tut beni, Çünkü senin ilkelerin iyidir."},{"n":"40","t":"Çok özlüyorum senin koşullarını! Beni doğruluğunun içinde yaşat! (VAV)"},{"n":"41","t":"Bana sevgini göster, ya RAB, Sözün uyarınca kurtar beni!"},{"n":"42","t":"O zaman beni aşağılayanlara Gereken yanıtı verebilirim, Çünkü senin sözüne güvenirim."},{"n":"43","t":"Gerçeğini ağzımdan düşürme, Çünkü senin hükümlerine umut bağladım."},{"n":"44","t":"Yasana sürekli, Sonsuza dek uyacağım."},{"n":"45","t":"Özgürce yürüyeceğim, Çünkü senin koşullarına yöneldim ben."},{"n":"46","t":"Kralların önünde senin öğütlerinden söz edecek, Utanç duymayacağım."},{"n":"47","t":"Senin buyruklarından zevk alıyor, Onları seviyorum."},{"n":"48","t":"Saygı ve sevgi duyuyorum buyruklarına, Derin derin düşünüyorum kurallarını. (ZAYİN)"},{"n":"49","t":"Kuluna verdiğin sözü anımsa, Bununla umut verdin bana."},{"n":"50","t":"Acı çektiğimde beni avutan budur, Sözün bana yaşam verir."},{"n":"51","t":"Çok eğlendiler küstahlar benimle, Yine de yasandan şaşmadım."},{"n":"52","t":"Geçmişte verdiğin hükümleri anımsayınca, Avundum, ya RAB."},{"n":"53","t":"Çileden çıkıyorum, Yasanı terk eden kötüler yüzünden."},{"n":"54","t":"Senin kurallarındır ezgilerimin konusu, Konuk olduğum bu dünyada."},{"n":"55","t":"Gece adını anarım, ya RAB, Yasana uyarım."},{"n":"56","t":"Tek yaptığım, Senin koşullarına uymak. (HET)"},{"n":"57","t":"Benim payıma düşen sensin, ya RAB, Sözlerini yerine getireceğim, dedim."},{"n":"58","t":"Bütün yüreğimle sana yakardım. Lütfet bana, sözün uyarınca."},{"n":"59","t":"Tuttuğum yolları düşündüm, Senin öğütlerine göre adım attım."},{"n":"60","t":"Buyruklarına uymak için Elimi çabuk tuttum, oyalanmadım."},{"n":"61","t":"Kötülerin ipleri beni sardı, Yasanı unutmadım."},{"n":"62","t":"Doğru hükümlerin için Gece yarısı kalkıp sana şükrederim."},{"n":"63","t":"Dostuyum bütün senden korkanların, Koşullarına uyanların."},{"n":"64","t":"Yeryüzü sevginle dolu, ya RAB, Kurallarını öğret bana! (TET)"},{"n":"65","t":"Ya RAB, iyilik ettin kuluna, Sözünü tuttun."},{"n":"66","t":"Bana sağduyu ve bilgi ver, Çünkü inanıyorum buyruklarına."},{"n":"67","t":"Acı çekmeden önce yoldan sapardım, Ama şimdi sözüne uyuyorum."},{"n":"68","t":"Sen iyisin, iyilik edersin; Bana kurallarını öğret."},{"n":"69","t":"Küstahlar yalanlarla beni lekeledi, Ama ben bütün yüreğimle senin koşullarına uyarım."},{"n":"70","t":"Onların yüreği yağ bağladı, Bense zevk alırım yasandan."},{"n":"71","t":"İyi oldu acı çekmem; Çünkü kurallarını öğreniyorum."},{"n":"72","t":"Ağzından çıkan yasa benim için Binlerce altın ve gümüşten daha değerlidir. (YOD)"},{"n":"73","t":"Senin ellerin beni yarattı, biçimlendirdi. Anlamamı sağla ki buyruklarını öğreneyim."},{"n":"74","t":"Senden korkanlar beni görünce sevinsin, Çünkü senin sözüne umut bağladım."},{"n":"75","t":"Biliyorum, ya RAB, hükümlerin adildir; Bana acı çektirirken bile sadıksın."},{"n":"76","t":"Ben kuluna verdiğin söz uyarınca, Sevgin beni avutsun."},{"n":"77","t":"Sevecenlik göster bana, yaşayayım, Çünkü yasandan zevk alıyorum."},{"n":"78","t":"Utansın küstahlar beni yalan yere suçladıkları için. Bense senin koşullarını düşünüyorum."},{"n":"79","t":"Bana dönsün senden korkanlar, Öğütlerini bilenler."},{"n":"80","t":"Yüreğim kusursuz uysun kurallarına, Öyle ki, utanç duymayayım. (KAF)"},{"n":"81","t":"İçim tükeniyor senin kurtarışını özlerken, Senin sözüne umut bağladım ben."},{"n":"82","t":"Gözümün feri sönüyor söz verdiklerini beklemekten, \"Ne zaman avutacaksın beni?\" diye soruyorum."},{"n":"83","t":"Dumandan kararmış tuluma döndüm, Yine de unutmuyorum kurallarını."},{"n":"84","t":"Daha ne kadar bekleyecek kulun? Ne zaman yargılayacaksın bana zulmedenleri?"},{"n":"85","t":"Çukur kazdılar benim için Yasana uymayan küstahlar."},{"n":"86","t":"Bütün buyrukların güvenilirdir; Haksız yere zulmediyorlar, yardım et bana!"},{"n":"87","t":"Nerdeyse sileceklerdi beni yeryüzünden, Ama ben senin koşullarından ayrılmadım."},{"n":"88","t":"Koru canımı sevgin uyarınca, Tutayım ağzından çıkan öğütleri. (LAMET)"},{"n":"89","t":"Ya RAB, sözün Göklerde sonsuza dek duruyor."},{"n":"90","t":"Sadakatin kuşaklar boyu sürüyor, Kurduğun yeryüzü sapasağlam duruyor."},{"n":"91","t":"Bugün hükümlerin uyarınca ayakta duran her şey Sana kulluk ediyor."},{"n":"92","t":"Eğer yasan zevk kaynağım olmasaydı, Çektiğim acılardan yok olurdum."},{"n":"93","t":"Koşullarını asla unutmayacağım, Çünkü onlarla bana yaşam verdin."},{"n":"94","t":"Kurtar beni, çünkü seninim, Senin koşullarına yöneldim."},{"n":"95","t":"Kötüler beni yok etmeyi beklerken, Ben senin öğütlerini inceliyorum."},{"n":"96","t":"Kusursuz olan her şeyin bir sonu olduğunu gördüm, Ama senin buyruğun sınır tanımaz. (MEM)"},{"n":"97","t":"Ne kadar severim yasanı! Bütün gün düşünürüm onun üzerinde."},{"n":"98","t":"Buyrukların beni düşmanlarımdan bilge kılar, Çünkü her zaman aklımdadır onlar."},{"n":"99","t":"Bütün öğretmenlerimden daha akıllıyım, Çünkü öğütlerin üzerinde düşünüyorum."},{"n":"100","t":"Yaşlılardan daha bilgeyim, Çünkü senin koşullarına uyuyorum."},{"n":"101","t":"Sakınırım her kötü yoldan, Senin sözünü tutmak için."},{"n":"102","t":"Ayrılmam hükümlerinden, Çünkü bana sen öğrettin."},{"n":"103","t":"Ne tatlı geliyor verdiğin sözler damağıma, Baldan tatlı geliyor ağzıma!"},{"n":"104","t":"Senin koşullarına uymakla bilgelik kazanıyorum, Bu yüzden nefret ediyorum her yanlış yoldan. (NUN)"},{"n":"105","t":"Sözün adımlarım için çıra, Yolum için ışıktır."},{"n":"106","t":"Adil hükümlerini izleyeceğime ant içtim, Andımı tutacağım."},{"n":"107","t":"Çok sıkıntı çektim, ya RAB; Koru hayatımı sözün uyarınca."},{"n":"108","t":"Ağzımdan çıkan içten övgüleri Kabul et, ya RAB, Bana hükümlerini öğret."},{"n":"109","t":"Hayatım her an tehlikede, Yine de unutmam yasanı."},{"n":"110","t":"Kötüler tuzak kurdu bana, Yine de sapmadım senin koşullarından."},{"n":"111","t":"Öğütlerin sonsuza dek mirasımdır, Yüreğimin sevincidir onlar."},{"n":"112","t":"Kararlıyım Sonuna kadar senin kurallarına uymaya. (SAMEK)"},{"n":"113","t":"Döneklerden tiksinir, Senin yasanı severim."},{"n":"114","t":"Sığınağım ve kalkanım sensin, Senin sözüne umut bağlarım."},{"n":"115","t":"Ey kötüler, benden uzak durun, Tanrım'ın buyruklarını yerine getireyim."},{"n":"116","t":"Sözün uyarınca destek ol bana, yaşam bulayım; Umudumu boşa çıkarma!"},{"n":"117","t":"Sıkı tut beni, kurtulayım, Her zaman kurallarını dikkate alayım."},{"n":"118","t":"Kurallarından sapan herkesi reddedersin, Çünkü onların hileleri boştur."},{"n":"119","t":"Dünyadaki kötüleri cüruf gibi atarsın, Bu yüzden severim senin öğütlerini."},{"n":"120","t":"Bedenim ürperiyor dehşetinden, Korkuyorum hükümlerinden. (AYİN)"},{"n":"121","t":"Adil ve doğru olanı yaptım, Gaddarların eline bırakma beni!"},{"n":"122","t":"Güven altına al kulunun mutluluğunu, Baskı yapmasın bana küstahlar."},{"n":"123","t":"Gözümün feri sönüyor, Beni kurtarmanı, Adil sözünü yerine getirmeni beklemekten."},{"n":"124","t":"Kuluna sevgin uyarınca davran, Bana kurallarını öğret."},{"n":"125","t":"Ben senin kulunum, bana akıl ver ki, Öğütlerini anlayabileyim."},{"n":"126","t":"Ya RAB, harekete geçmenin zamanıdır, Yasanı çiğniyorlar."},{"n":"127","t":"Bu yüzden senin buyruklarını, Altından, saf altından daha çok seviyorum;"},{"n":"128","t":"Koyduğun koşulların hepsini doğru buluyorum, Her yanlış yoldan tiksiniyorum. (PE)"},{"n":"129","t":"Harika öğütlerin var, Bu yüzden onlara candan uyuyorum."},{"n":"130","t":"Sözlerinin açıklanışı aydınlık saçar, Saf insanlara akıl verir."},{"n":"131","t":"Ağzım açık, soluk soluğayım, Çünkü buyruklarını özlüyorum."},{"n":"132","t":"Bana lütufla bak, Adını sevenlere her zaman yaptığın gibi."},{"n":"133","t":"Adımlarımı pekiştir verdiğin söz uyarınca, Hiçbir suç bana egemen olmasın."},{"n":"134","t":"Kurtar beni insan baskısından, Koşullarına uyabileyim."},{"n":"135","t":"Yüzün aydınlık saçsın kulunun üzerine, Kurallarını öğret bana."},{"n":"136","t":"Oluk oluk yaş akıyor gözlerimden, Çünkü uymuyorlar yasana. (SADE)"},{"n":"137","t":"Sen adilsin, ya RAB, Hükümlerin doğrudur."},{"n":"138","t":"Buyurduğun öğütler doğru Ve tam güvenilirdir."},{"n":"139","t":"Gayretim beni tüketti, Çünkü düşmanlarım unuttu senin sözlerini."},{"n":"140","t":"Sözün çok güvenilirdir, Kulun onu sever."},{"n":"141","t":"Önemsiz ve horlanan biriyim ben, Ama koşullarını unutmuyorum."},{"n":"142","t":"Adaletin sonsuza dek doğrudur, Yasan gerçektir."},{"n":"143","t":"Sıkıntıya, darlığa düştüm, Ama buyrukların benim zevkimdir."},{"n":"144","t":"Öğütlerin sonsuza dek doğrudur; Bana akıl ver ki, yaşayayım. (KOF)"},{"n":"145","t":"Bütün yüreğimle haykırıyorum, Yanıtla beni, ya RAB! Senin kurallarına uyacağım."},{"n":"146","t":"Sana sesleniyorum, Kurtar beni, Öğütlerine uyayım."},{"n":"147","t":"Gün doğmadan kalkıp yardım dilerim, Senin sözüne umut bağladım."},{"n":"148","t":"Verdiğin söz üzerinde düşüneyim diye, Gece boyunca uyku girmiyor gözüme."},{"n":"149","t":"Sevgin uyarınca sesime kulak ver, Hükümlerin uyarınca, ya RAB, yaşam ver bana!"},{"n":"150","t":"Yaklaşıyor kötülük ardınca koşanlar, Yasandan uzaklaşıyorlar."},{"n":"151","t":"Oysa sen yakınsın, ya RAB, Bütün buyrukların gerçektir."},{"n":"152","t":"Çoktan beri anladım Öğütlerini sonsuza dek verdiğini. (REŞ)"},{"n":"153","t":"Çektiğim sıkıntıyı gör, kurtar beni, Çünkü yasanı unutmadım."},{"n":"154","t":"Davamı savun, özgür kıl beni, Sözün uyarınca koru canımı."},{"n":"155","t":"Kurtuluş kötülerden uzaktır, Çünkü senin kurallarına yönelmiyorlar."},{"n":"156","t":"Çok sevecensin, ya RAB, Hükümlerin uyarınca koru canımı."},{"n":"157","t":"Bana zulmedenler, düşmanlarım çok, Yine de sapmadım senin öğütlerinden."},{"n":"158","t":"Tiksinerek bakıyorum hainlere, Çünkü uymuyorlar senin sözüne."},{"n":"159","t":"Bak, ne kadar seviyorum koşullarını, Sevgin uyarınca, ya RAB, koru canımı."},{"n":"160","t":"Sözlerinin temeli gerçektir, Doğru hükümlerinin tümü sonsuza dek sürecektir. (SİN ve ŞİN)"},{"n":"161","t":"Yok yere zulmediyor bana önderler, Oysa yüreğim senin sözünle titrer."},{"n":"162","t":"Ganimet bulan biri gibi Verdiğin sözlerde sevinç bulurum."},{"n":"163","t":"Tiksinir, iğrenirim yalandan, Ama senin yasanı severim."},{"n":"164","t":"Doğru hükümlerin için Seni günde yedi kez överim."},{"n":"165","t":"Yasanı sevenler büyük esenlik bulur, Hiçbir şey sendeletmez onları."},{"n":"166","t":"Ya RAB, kurtarışına umut bağlar, Buyruklarını yerine getiririm."},{"n":"167","t":"Öğütlerine candan uyar, Onları çok severim."},{"n":"168","t":"Öğütlerini, koşullarını uygularım, Çünkü bütün davranışlarımı görürsün sen. (TAV)"},{"n":"169","t":"Feryadım sana erişsin, ya RAB, Sözün uyarınca akıl ver bana!"},{"n":"170","t":"Yalvarışım sana ulaşsın;Verdiğin söz uyarınca kurtar beni!"},{"n":"171","t":"Dudaklarımdan övgüler aksın, Çünkü bana kurallarını öğretiyorsun."},{"n":"172","t":"Dilimde sözün ezgilere dönüşsün, Çünkü bütün buyrukların doğrudur."},{"n":"173","t":"Elin bana yardıma hazır olsun, Çünkü senin koşullarını seçtim ben."},{"n":"174","t":"Kurtarışını özlüyorum, ya RAB, Yasan zevk kaynağımdır."},{"n":"175","t":"Beni yaşat ki, sana övgüler sunayım, Hükümlerin bana yardımcı olsun."},{"n":"176","t":"Kaybolmuş koyun gibi avare dolaşıyordum; Kulunu ara, Çünkü buyruklarını unutmadım ben."}]},{"id":120,"name":"120. MezmurHac ilahisi*fç*","verses":[{"n":"1","t":"Sıkıntıya düşünce RAB'be seslendim; Yanıtladı beni."},{"n":"2","t":"Ya RAB, kurtar canımı yalancı dudaklardan, Aldatıcı dillerden!D Not \"Hac İlahisi\": Fısıh, Hasat, Çardak bayramlarını kutlamak için Yeruşalim'e çıkarken söylenen ezgi."},{"n":"3","t":"Ey aldatıcı dil, RAB ne verecek sana, Daha ne verecek?"},{"n":"4","t":"Yiğidin sivri oklarıyla Retem çalısından alevli korlar!"},{"n":"5","t":"Vay bana, Meşek'te garip kaldım sanki, Kedar çadırları arasında oturdum."},{"n":"6","t":"Fazla kaldım Barıştan nefret edenler arasında."},{"n":"7","t":"Ben barış yanlısıyım, Ama söze başladığımda, Onlar savaşa kalkıyor!"}]},{"id":121,"name":"121. MezmurHac ilahisi","verses":[{"n":"1","t":"Gözlerimi dağlara kaldırıyorum, Nereden yardım gelecek?"},{"n":"2","t":"Yeri göğü yaratan RAB'den gelecek yardım."},{"n":"3","t":"O ayaklarının kaymasına izin vermez, Seni koruyan uyuklamaz."},{"n":"4","t":"İsrail'in koruyucusu ne uyur ne uyuklar."},{"n":"5","t":"Senin koruyucun RAB'dir, O sağ yanında sana gölgedir."},{"n":"6","t":"Gündüz güneş, Gece ay sana zarar vermez."},{"n":"7","t":"RAB her kötülükten seni korur, Esirger canını."},{"n":"8","t":"Şimdiden sonsuza dek RAB koruyacak gidişini, gelişini."}]},{"id":122,"name":"122. MezmurDavut'un hac ilahisi","verses":[{"n":"1","t":"Bana: \"RAB'bin evine gidelim\" dendikçe Sevinirim."},{"n":"2","t":"Ayaklarımız senin kapılarında, Ey Yeruşalim!"},{"n":"3","t":"Bitişik nizamda kurulmuş bir kenttir Yeruşalim!"},{"n":"4","t":"Oymaklar çıkar oraya, RAB'bin oymakları, İsrail'e verilen öğüt uyarınca, RAB'bin adına şükretmek için."},{"n":"5","t":"Çünkü orada yargı tahtları, Davut soyunun tahtları kurulmuştur."},{"n":"6","t":"Esenlik dileyin Yeruşalim'e: \"Huzur bulsun seni sevenler!"},{"n":"7","t":"Surlarına esenlik, Saraylarına huzur egemen olsun!\""},{"n":"8","t":"Kardeşlerim, dostlarım için, \"Esenlik olsun sana!\" derim."},{"n":"9","t":"Tanrımız RAB'bin evi için İyilik dilerim sana."}]},{"id":123,"name":"123. MezmurHac ilahisi","verses":[{"n":"1","t":"Gözlerimi sana kaldırıyorum, Ey göklerde taht kuran!"},{"n":"2","t":"Nasıl kulların gözleri efendilerinin, Hizmetçinin gözleri hanımının eline bakarsa, Bizim gözlerimiz de RAB Tanrımız'a öyle bakar, O bize acıyıncaya dek."},{"n":"3","t":"Acı bize, ya RAB, acı; Gördüğümüz hakaret yeter de artar."},{"n":"4","t":"Rahat yaşayanların alayları, Küstahların hakareti Canımıza yetti."}]},{"id":124,"name":"124. MezmurDavut'un hac ilahisi","verses":[{"n":"1","t":"RAB bizden yana olmasaydı, Desin şimdi İsrail:"},{"n":"2","t":"RAB bizden yana olmasaydı, İnsanlar bize saldırdığında,"},{"n":"3","t":"Diri diri yutarlardı bizi, Öfkeleri bize karşı alevlenince."},{"n":"4","t":"Sular silip süpürürdü bizleri, Seller geçerdi üzerimizden."},{"n":"5","t":"Kabaran sular Aşardı başımızdan."},{"n":"6","t":"Övgüler olsun Bizi onların ağzına yem etmeyen RAB'be!"},{"n":"7","t":"Bir kuş gibi Kurtuldu canımız avcının tuzağından, Kırıldı tuzak, kurtulduk."},{"n":"8","t":"Yeri göğü yaratan RAB'bin adı yardımcımızdır."}]},{"id":125,"name":"125. MezmurHac ilahisi","verses":[{"n":"1","t":"RAB'be güvenenler Siyon Dağı'na benzer, Sarsılmaz, sonsuza dek durur."},{"n":"2","t":"Dağlar Yeruşalim'i nasıl kuşatmışsa, RAB de halkını öyle kuşatmıştır, Şimdiden sonsuza dek."},{"n":"3","t":"Kalmayacak kötülerin asası, Doğruların payına düşen toprakta, Yoksa doğrular haksızlığa el uzatabilir."},{"n":"4","t":"İyilik et, ya RAB, İyilere, yüreği temiz olanlara."},{"n":"5","t":"Ama kendi halkından eğri yollara sapanları, RAB kötü uluslarla birlikte kovacak. İsrail'e esenlik olsun!"}]},{"id":126,"name":"126. MezmurHac ilahisi","verses":[{"n":"1","t":"RAB sürgünleri Siyon'a geri getirince*fd*, Rüya gibi geldi bize.D"},{"n":"1","t":"\"RAB sürgünleri Siyon'a geri getirince\" ya da \"RAB Siyon'u eski gönencine kavuşturunca\"."},{"n":"2","t":"Ağzımız gülüşlerle, Dilimiz sevinç çığlıklarıyla doldu. \"RAB onlar için büyük işler yaptı\" Diye konuşuldu uluslar arasında."},{"n":"3","t":"RAB bizim için büyük işler yaptı, Sevinç doldu içimiz."},{"n":"4","t":"Ya RAB, eski gönencimize kavuştur bizi, Negev'de suya kavuşan vadiler gibi."},{"n":"5","t":"Gözyaşları içinde ekenler, Sevinç çığlıklarıyla biçecek;"},{"n":"6","t":"Ağlayarak tohum çuvalını taşıyıp dolaşan, Sevinç çığlıkları atarak demetlerle dönecek."}]},{"id":127,"name":"127. MezmurSüleyman'ın hac ilahisi","verses":[{"n":"1","t":"Evi RAB yapmazsa, Yapıcılar boşuna didinir. Kenti RAB korumazsa, Bekçi boşuna bekler."},{"n":"2","t":"Boşuna erken kalkıp Geç yatıyorsunuz. Ey zahmetle kazanılan ekmeği yiyenler, RAB sevdiklerinin rahat uyumasını sağlar."},{"n":"3","t":"Çocuklar RAB'bin verdiği bir armağandır, Rahmin ürünü bir ödüldür."},{"n":"4","t":"Yiğidin elinde nasılsa oklar, Öyledir gençlikte doğan çocuklar."},{"n":"5","t":"Ne mutlu ok kılıfı onlarla dolu insana! Kent kapısında*fe* hasımlarıyla tartışırken Utanç duymayacaklar.D"},{"n":"5","t":"\"Kent kapısında\": Eski zamanlarda mahkeme kent kapısında yapılırdı."}]},{"id":128,"name":"128. MezmurHac ilahisi","verses":[{"n":"1","t":"Ne mutlu RAB'den korkana, O'nun yolunda yürüyene!"},{"n":"2","t":"Emeğinin ürününü yiyeceksin, Mutlu ve başarılı olacaksın."},{"n":"3","t":"Eşin evinde verimli bir asma gibi olacak; Çocukların zeytin filizleri gibi sofranın çevresinde."},{"n":"4","t":"İşte RAB'den korkan kişi Böyle kutsanacak."},{"n":"5","t":"RAB seni Siyon'dan kutsasın! Yeruşalim'in gönencini göresin, Bütün yaşamın boyunca!"},{"n":"6","t":"Çocuklarının çocuklarını göresin! İsrail'e esenlik olsun!"}]},{"id":129,"name":"129. MezmurHac ilahisi","verses":[{"n":"1","t":"Gençliğimden beri bana sık sık saldırdılar; Şimdi söylesin İsrail:"},{"n":"2","t":"\"Gençliğimden beri bana sık sık saldırdılar, Ama yenemediler beni."},{"n":"3","t":"Çiftçiler saban sürdüler sırtımda, Upuzun iz bıraktılar.\""},{"n":"4","t":"Ama RAB adildir, Kesti kötülerin bağlarını."},{"n":"5","t":"Siyon'dan nefret eden herkes Utanç içinde geri çekilsin."},{"n":"6","t":"Damlardaki ota, Büyümeden kuruyan ota dönsünler."},{"n":"7","t":"Orakçı avucunu, Demetçi kucağını dolduramaz onunla."},{"n":"8","t":"Yoldan geçenler de, \"RAB sizi kutsasın, RAB'bin adıyla sizi kutsarız\" demezler."}]},{"id":130,"name":"130. MezmurHac ilahisi","verses":[{"n":"1","t":"Derinliklerden sana sesleniyorum, ya RAB,"},{"n":"2","t":"Sesimi işit, ya Rab, Yalvarışıma iyi kulak ver!"},{"n":"3","t":"Ya RAB, sen suçların hesabını tutsan, Kim ayakta kalabilir, ya Rab?"},{"n":"4","t":"Ama sen bağışlayıcısın, Öyle ki senden korkulsun."},{"n":"5","t":"RAB'bi gözlüyorum, Canım RAB'bi gözlüyor, Umut bağlıyorum O'nun sözüne."},{"n":"6","t":"Sabahı gözleyenlerden, Evet, sabahı gözleyenlerden daha çok, Canım Rab'bi gözlüyor."},{"n":"7","t":"Ey İsrail, RAB'be umut bağla! Çünkü RAB'de sevgi, Tam kurtuluş vardır."},{"n":"8","t":"İsrail'i bütün suçlarından Fidyeyle O kurtaracaktır."}]},{"id":131,"name":"131. MezmurDavut'un hac ilahisi","verses":[{"n":"1","t":"Ya RAB, yüreğimde gurur yok, Gözüm yükseklerde değil. Büyük işlerle, Kendimi aşan harika işlerle uğraşmıyorum."},{"n":"2","t":"Tersine, ana kucağında sütten kesilmiş çocuk gibi, Kendimi yatıştırıp huzur buldum, Sütten kesilmiş çocuğa döndüm."},{"n":"3","t":"Ey İsrail, RAB'be umut bağla Şimdiden sonsuza dek!"}]},{"id":132,"name":"132. Mezmur(2Ta.6:41-42)Hac ilahisi","verses":[{"n":"1-2","t":"Ya RAB, Davut'un hatırı için, Çektiği bütün zorlukları, Sana nasıl ant içtiğini, Yakup'un güçlü Tanrısı'na adak adadığını anımsa:"},{"n":"3","t":"\"Evime gitmeyeceğim, Yatağıma uzanmayacağım,"},{"n":"4","t":"Gözlerime uyku girmeyecek, Göz kapaklarım kapanmayacak,"},{"n":"5","t":"RAB'be bir yer, Yakup'un güçlü Tanrısı'na bir konut buluncaya dek.\""},{"n":"6","t":"Antlaşma Sandığı'nın* Efrata'da olduğunu duyduk, Onu Yaar kırlarında bulduk."},{"n":"7","t":"\"RAB'bin konutuna gidelim, Ayağının taburesi önünde tapınalım\" dedik."},{"n":"8","t":"Çık, ya RAB, yaşayacağın yere, Gücünü simgeleyen sandıkla birlikte."},{"n":"9","t":"Kâhinlerin doğruluğu kuşansın, Sadık kulların sevinç çığlıkları atsın."},{"n":"10","t":"Kulun Davut'un hatırı için, Meshettiğin* krala yüz çevirme."},{"n":"11","t":"RAB Davut'a kesin ant içti, Andından dönmez: \"Senin soyundan birini tahtına oturtacağım."},{"n":"12","t":"Eğer oğulların antlaşmama, Vereceğim öğütlere uyarlarsa, Onların oğulları da sonsuza dek Senin tahtına oturacak.\""},{"n":"13","t":"Çünkü RAB Siyon'u seçti, Onu konut edinmek istedi."},{"n":"14","t":"\"Sonsuza dek yaşayacağım yer budur\" dedi, \"Burada oturacağım, çünkü bunu kendim istedim."},{"n":"15","t":"Çok bereketli kılacağım erzağını, Yiyecekle doyuracağım yoksullarını."},{"n":"16","t":"Kurtuluşla donatacağım kâhinlerini; Hep sevinç ezgileri söyleyecek sadık kulları."},{"n":"17","t":"Burada Davut soyundan güçlü bir kral çıkaracağım, Meshettiğim kralın soyunu Işık olarak sürdüreceğim."},{"n":"18","t":"Düşmanlarını utanca bürüyeceğim, Ama onun başındaki taç parıldayacak.\""}]},{"id":133,"name":"133. MezmurDavut'un hac ilahisi","verses":[{"n":"1","t":"Ne iyi, ne güzeldir, Birlik içinde kardeşçe yaşamak!"},{"n":"2","t":"Başa sürülen değerli yağ gibi, Sakaldan, Harun'un sakalından Kaftanının yakasına dek inen yağ gibi."},{"n":"3","t":"Hermon Dağı'na yağan çiy Siyon dağlarına yağıyor sanki. Çünkü RAB orada bereketi, Sonsuz yaşamı buyurdu."}]},{"id":134,"name":"134. MezmurHac ilahisi","verses":[{"n":"1","t":"Ey sizler, RAB'bin bütün kulları, RAB'bin Tapınağı'nda gece hizmet edenler, O'na övgüler sunun!"},{"n":"2","t":"Ellerinizi kutsal yere doğru kaldırıp RAB'be övgüler sunun!"},{"n":"3","t":"Yeri göğü yaratan RAB kutsasın sizi Siyon'dan."}]},{"id":135,"name":"135. Mezmur(Mez.115: 4-11)","verses":[{"n":"1-2","t":"RAB'be övgüler sunun! RAB'bin adına övgüler sunun, Ey RAB'bin kulları! Ey sizler, RAB'bin Tapınağı'nda, Tanrımız'ın Tapınağı'nın avlularında hizmet edenler, Övgüler sunun!"},{"n":"3","t":"RAB'be övgüler sunun, Çünkü RAB iyidir. Adını ilahilerle övün, Çünkü hoştur bu."},{"n":"4","t":"RAB kendine Yakup soyunu, Öz halkı olarak İsrail'i seçti."},{"n":"5","t":"Biliyorum, RAB büyüktür, Rabbimiz bütün ilahlardan üstündür."},{"n":"6","t":"RAB ne isterse yapar, Göklerde, yeryüzünde, Denizlerde, bütün derinliklerde."},{"n":"7","t":"Yeryüzünün dört bucağından bulutlar yükseltir, Yağmur için şimşek çaktırır, Ambarlarından rüzgar estirir."},{"n":"8","t":"İnsanlardan hayvanlara dek Mısır'da ilk doğanları öldürdü."},{"n":"9","t":"Ey Mısır, senin orta yerinde, Firavunla bütün görevlilerine Belirtiler, şaşılası işler gösterdi."},{"n":"10","t":"Birçok ulusu bozguna uğrattı, Güçlü kralları öldürdü:"},{"n":"11","t":"Amorlu kral Sihon'u, Başan Kralı Og'u, Bütün Kenan krallarını."},{"n":"12","t":"Topraklarını mülk, Evet, mülk olarak halkı İsrail'e verdi."},{"n":"13","t":"Ya RAB, adın sonsuza dek sürecek, Bütün kuşaklar seni anacak."},{"n":"14","t":"RAB halkını haklı çıkarır, Kullarına acır."},{"n":"15","t":"Ulusların putları altın ve gümüşten yapılmış, İnsan elinin eseridir."},{"n":"16","t":"Ağızları var, konuşmazlar, Gözleri var, görmezler,"},{"n":"17","t":"Kulakları var, duymazlar, Soluk alıp vermezler."},{"n":"18","t":"Onları yapan, onlara güvenen herkes Onlar gibi olacak!"},{"n":"19","t":"Ey İsrail halkı, RAB'be övgüler sun! Ey Harun soyu, RAB'be övgüler sun!"},{"n":"20","t":"Ey Levi soyu, RAB'be övgüler sun! RAB'be övgüler sunun, ey RAB'den korkanlar!"},{"n":"21","t":"Yeruşalim'de oturan RAB'be Siyon'dan övgüler sunulsun! RAB'be övgüler sunun!"}]},{"id":136,"name":"136. Mezmur","verses":[{"n":"1","t":"Şükredin RAB'be, çünkü O iyidir,Sevgisi sonsuzdur;"},{"n":"2","t":"Şükredin tanrılar Tanrısı'na,Sevgisi sonsuzdur;"},{"n":"3","t":"Şükredin rabler Rabbi'ne,Sevgisi sonsuzdur;"},{"n":"4","t":"Büyük harikalar yapan tek varlığa,Sevgisi sonsuzdur;"},{"n":"5","t":"Gökleri bilgece yaratana,Sevgisi sonsuzdur;"},{"n":"6","t":"Yeri sular üzerine yayana,Sevgisi sonsuzdur;"},{"n":"7","t":"Büyük ışıklar yaratana,Sevgisi sonsuzdur;"},{"n":"8","t":"Gündüze egemen olsun diye güneşi,Sevgisi sonsuzdur;"},{"n":"9","t":"Geceye egemen olsun diye ayı ve yıldızları yaratana,Sevgisi sonsuzdur;"},{"n":"10","t":"Mısır'da ilk doğanları öldürene,Sevgisi sonsuzdur;"},{"n":"11-12","t":"Güçlü eli, kudretli koluylaSevgisi sonsuzdur;İsrail'i Mısır'dan çıkarana,Sevgisi sonsuzdur;"},{"n":"13","t":"Kızıldeniz'i* ikiye bölene,Sevgisi sonsuzdur;"},{"n":"14","t":"İsrail'i ortasından geçirene,Sevgisi sonsuzdur;"},{"n":"15","t":"Firavunla ordusunu Kızıldeniz'e dökene,Sevgisi sonsuzdur;"},{"n":"16","t":"Kendi halkını çölde yürütene,Sevgisi sonsuzdur;"},{"n":"17","t":"Büyük kralları vurana,Sevgisi sonsuzdur;"},{"n":"18","t":"Güçlü kralları öldürene,Sevgisi sonsuzdur;"},{"n":"19","t":"Amorlu kral Sihon'u,Sevgisi sonsuzdur;"},{"n":"20","t":"Başan Kralı Og'u öldürene,Sevgisi sonsuzdur;"},{"n":"21-22","t":"Topraklarını mülk olarak,Sevgisi sonsuzdur; Kulu İsrail'e mülk verene,Sevgisi sonsuzdur;"},{"n":"23","t":"Düşkün günlerimizde bizi anımsayana,Sevgisi sonsuzdur;"},{"n":"24","t":"Düşmanlarımızdan bizi kurtarana,Sevgisi sonsuzdur;"},{"n":"25","t":"Bütün canlılara yiyecek verene,Sevgisi sonsuzdur;"},{"n":"26","t":"Şükredin Göklerin Tanrısı'na,Sevgisi sonsuzdur."}]},{"id":137,"name":"137. Mezmur","verses":[{"n":"1","t":"Babil ırmakları kıyısında oturup Siyon'u andıkça ağladık;"},{"n":"2","t":"Çevredeki kavaklara Lirlerimizi astık."},{"n":"3","t":"Çünkü orada bizi tutsak edenler bizden ezgiler, Bize zulmedenler bizden şenlik istiyor, \"Siyon ezgilerinden birini okuyun bize!\" diyorlardı."},{"n":"4","t":"Nasıl okuyabiliriz RAB'bin ezgisini El toprağında?"},{"n":"5","t":"Ey Yeruşalim, seni unutursam, Sağ elim kurusun."},{"n":"6","t":"Seni anmaz, Yeruşalim'i en büyük sevincimden üstün tutmazsam, Dilim damağıma yapışsın!"},{"n":"7","t":"Yeruşalim'in düştüğü gün, \"Yıkın onu, yıkın temellerine kadar!\" Diyen Edomlular'ın tavrını anımsa, ya RAB."},{"n":"8","t":"Ey sen, yıkılası Babil kızı, Bize yaptıklarını Sana ödetecek olana ne mutlu!"},{"n":"9","t":"Ne mutlu senin yavrularını tutup Kayalarda parçalayacak insana!"}]},{"id":138,"name":"138. MezmurDavut'un mezmuru","verses":[{"n":"1","t":"Bütün yüreğimle sana şükrederim, ya RAB, İlahlar önünde seni ilahilerle överim."},{"n":"2","t":"Kutsal tapınağına doğru eğilir, Adına şükrederim, Sevgin, sadakatin için. Çünkü adını ve sözünü her şeyden üstün tuttun."},{"n":"3","t":"Seslendiğim gün bana yanıt verdin, İçime güç koydun, beni yüreklendirdin."},{"n":"4","t":"Şükretsin sana, ya RAB, yeryüzü krallarının tümü, Çünkü ağzından çıkan sözleri işittiler."},{"n":"5","t":"Yaptığın işleri ezgilerle övsünler, ya RAB, Çünkü çok yücesin."},{"n":"6","t":"RAB yüksekse de, Alçakgönüllüleri gözetir, Küstahları uzaktan tanır."},{"n":"7","t":"Sıkıntıya düşersem, canımı korur, Düşmanlarımın öfkesine karşı el kaldırırsın, Sağ elin beni kurtarır."},{"n":"8","t":"Ya RAB, her şeyi yaparsın benim için. Sevgin sonsuzdur, ya RAB, Elinin eserini bırakma!"}]},{"id":139,"name":"139. MezmurMüzik şefi için - Davut'un mezmuru","verses":[{"n":"1","t":"Ya RAB, sınayıp tanıdın beni."},{"n":"2","t":"Oturup kalkışımı bilirsin, Niyetimi uzaktan anlarsın."},{"n":"3","t":"Gittiğim yolu, yattığım yeri inceden inceye elersin, Bütün yaptıklarımdan haberin var."},{"n":"4","t":"Daha sözü ağzıma almadan, Söyleyeceğim her şeyi bilirsin, ya RAB."},{"n":"5","t":"Beni çepeçevre kuşattın, Elini üzerime koydun."},{"n":"6","t":"Kaldıramam böylesi bir bilgiyi, Başa çıkamam, erişemem."},{"n":"7","t":"Nereye gidebilirim senin Ruhun'dan, Nereye kaçabilirim huzurundan?"},{"n":"8","t":"Göklere çıksam, oradasın, Ölüler diyarına yatak sersem, yine oradasın."},{"n":"9","t":"Seherin kanatlarını alıp uçsam, Denizin ötesine konsam,"},{"n":"10","t":"Orada bile elin yol gösterir bana, Sağ elin tutar beni."},{"n":"11","t":"Desem ki, \"Karanlık beni kaplasın, Çevremdeki aydınlık geceye dönsün.\""},{"n":"12","t":"Karanlık bile karanlık sayılmaz senin için, Gece, gündüz gibi ışıldar, Karanlıkla aydınlık birdir senin için."},{"n":"13","t":"İç varlığımı sen yarattın, Annemin rahminde beni sen ördün."},{"n":"14","t":"Sana övgüler sunarım, Çünkü müthiş ve harika yaratılmışım. Ne harika işlerin var! Bunu çok iyi bilirim."},{"n":"15","t":"Gizli yerde yaratıldığımda, Yerin derinliklerinde örüldüğümde, Bedenim senden gizli değildi."},{"n":"16","t":"Henüz döl yatağındayken gözlerin gördü beni; Bana ayrılan günlerin hiçbiri gelmeden, Hepsi senin kitabına yazılmıştı."},{"n":"17","t":"Hakkımdaki düşüncelerin ne değerli, ey Tanrı, Sayıları ne çok!"},{"n":"18","t":"Kum tanelerinden fazladır saymaya kalksam. Uyanıyorum, hâlâ seninleyim."},{"n":"19","t":"Ey Tanrı, keşke kötüleri öldürsen! Ey eli kanlı insanlar, uzaklaşın benden!"},{"n":"20","t":"Çünkü senin için kötü konuşuyorlar, Adını kötüye kullanıyor düşmanların."},{"n":"21","t":"Ya RAB, nasıl tiksinmem senden tiksinenlerden? Nasıl iğrenmem sana başkaldıranlardan?"},{"n":"22","t":"Onlardan tümüyle nefret ediyor, Onları düşman sayıyorum."},{"n":"23","t":"Ey Tanrı, yokla beni, tanı yüreğimi, Sına beni, öğren kaygılarımı."},{"n":"24","t":"Bak, seni gücendiren bir yönüm var mı, Öncülük et bana sonsuz yaşam yolunda!"}]},{"id":140,"name":"140. MezmurMüzik şefi için - Davut'un mezmuru","verses":[{"n":"1","t":"Ya RAB, kurtar beni kötü insandan, Koru beni zorbadan."},{"n":"2","t":"Onlar yüreklerinde kötülük tasarlar, Savaşı sürekli körükler,"},{"n":"3","t":"Yılan gibi dillerini bilerler, Engerek zehiri var dudaklarının altında. *"},{"n":"4","t":"Ya RAB, sakın beni kötünün elinden, Koru beni zorbadan; Bana çelme takmayı tasarlıyorlar."},{"n":"5","t":"Küstahlar benim için tuzak kurdu, Haydutlar ağ gerdi; Yol kenarına kapan koydular benim için."},{"n":"6","t":"Sana diyorum, ya RAB: \"Tanrım sensin.\" Yalvarışıma kulak ver, ya RAB."},{"n":"7","t":"Ey Egemen RAB, güçlü kurtarıcım, Savaş gününde başımı korudun."},{"n":"8","t":"Kötülerin dileklerini yerine getirme, ya RAB, Tasarılarını ileri götürme! Yoksa gurura kapılırlar."},{"n":"9","t":"Beni kuşatanların başını, Dudaklarından dökülen fesat kaplasın."},{"n":"10","t":"Kızgın korlar yağsın üzerlerine! Ateşe, dipsiz çukurlara atılsınlar, Bir daha kalkamasınlar."},{"n":"11","t":"İftiracılara ülkede hayat kalmasın, Felaket zorbaları amansızca avlasın."},{"n":"12","t":"Biliyorum, RAB mazlumun davasını savunur, Yoksulları haklı çıkarır."},{"n":"13","t":"Kuşkusuz doğrular senin adına şükredecek, Dürüstler senin huzurunda oturacak."}]},{"id":141,"name":"141. MezmurDavut'un mezmuru","verses":[{"n":"1","t":"Seni çağırıyorum, ya RAB, yardımıma koş! Sana yakarınca sesime kulak ver!"},{"n":"2","t":"Duam önünde yükselen buhur gibi, El açışım akşam sunusu gibi kabul görsün!"},{"n":"3","t":"Ya RAB, ağzıma bekçi koy, Dudaklarımın kapısını koru!"},{"n":"4","t":"Yüreğim kötülüğe eğilim göstermesin, Suç işleyenlerin fesadına bulaşmayayım; Onların nefis yemeklerini tatmayayım."},{"n":"5","t":"Doğru insan bana vursa, iyilik sayılır, Azarlasa, başa sürülen yağ gibidir, Başım reddetmez onu. Çünkü duam hep kötülere karşıdır."},{"n":"6","t":"Önderleri kayalardan aşağı atılınca, Dinleyecekler tatlı sözlerimi."},{"n":"7","t":"Sabanla sürülüp yarılmış toprak gibi, Saçılmış kemiklerimiz ölüler diyarının ağzına."},{"n":"8","t":"Ancak gözlerim sende, ey Egemen RAB, Sana sığınıyorum, beni savunmasız bırakma!"},{"n":"9","t":"Koru beni kurdukları tuzaktan, Suç işleyenlerin kapanlarından."},{"n":"10","t":"Ben güvenlik içinde geçip giderken, Kendi ağlarına düşsün kötüler."}]},{"id":142,"name":"142. MezmurDavut'un Maskili - Mağaradayken ettiği dua","verses":[{"n":"1","t":"Yüksek sesle yakarıyorum RAB'be, Yüksek sesle RAB'be yalvarıyorum."},{"n":"2","t":"Önüne döküyorum yakınmalarımı, Önünde anlatıyorum sıkıntılarımı."},{"n":"3","t":"Bunalıma düştüğümde, Gideceğim yolu sen bilirsin. Tuzak kurdular yürüdüğüm yola."},{"n":"4","t":"Sağıma bak da gör, Kimse saymıyor beni, Sığınacak yerim kalmadı, Kimse aramıyor beni."},{"n":"5","t":"Sana haykırıyorum, ya RAB: \"Sığınağım, Yaşadığımız bu dünyada nasibim sensin\" diyorum."},{"n":"6","t":"Haykırışıma kulak ver, Çünkü çok çaresizim; Kurtar beni ardıma düşenlerden, Çünkü benden güçlüler."},{"n":"7","t":"Çıkar beni zindandan, Adına şükredeyim. O zaman doğrular çevremi saracak, Bana iyilik ettiğin için."}]},{"id":143,"name":"143. MezmurDavut'un mezmuru","verses":[{"n":"1","t":"Duamı işit, ya RAB, Yalvarışlarıma kulak ver! Sadakatinle, doğruluğunla yanıtla beni!"},{"n":"2","t":"Kulunla yargıya girme, Çünkü hiçbir canlı senin karşında aklanmaz."},{"n":"3","t":"Düşman beni kovalıyor, Ezip yere seriyor. Çoktan ölmüş olanlar gibi, Beni karanlıklarda oturtuyor."},{"n":"4","t":"Bu yüzden bunalıma düştüm, Yüreğim perişan."},{"n":"5","t":"Geçmiş günleri anıyor, Bütün yaptıklarını derin derin düşünüyor, Ellerinin işine bakıp dalıyorum."},{"n":"6","t":"Ellerimi sana açıyorum, Canım kurak toprak gibi sana susamış. *"},{"n":"7","t":"Çabuk yanıtla beni, ya RAB, Tükeniyorum. Çevirme benden yüzünü, Yoksa ölüm çukuruna inen ölülere dönerim."},{"n":"8","t":"Sabahları duyur bana sevgini, Çünkü sana güveniyorum; Bana gideceğim yolu bildir, Çünkü duam sanadır."},{"n":"9","t":"Düşmanlarımdan kurtar beni, ya RAB; Sana sığınıyorum."},{"n":"10","t":"Bana istemini yapmayı öğret, Çünkü Tanrım'sın benim. Senin iyi Ruhun Düz yolda bana öncülük etsin!"},{"n":"11","t":"Ya RAB, adın uğruna yaşam ver bana, Doğruluğunla kurtar beni sıkıntıdan."},{"n":"12","t":"Sevginden ötürü, Öldür düşmanlarımı, Yok et bütün hasımlarımı, Çünkü senin kulunum ben."}]},{"id":144,"name":"144. MezmurDavut'un mezmuru","verses":[{"n":"1","t":"Ellerime vuruşmayı, Parmaklarıma savaşmayı öğreten Kayam RAB'be övgüler olsun!"},{"n":"2","t":"O'dur benim vefalı dostum, kalem, Kurtarıcım, kulem, Kalkanım, O'na sığınırım; O'dur halkları bana boyun eğdiren!"},{"n":"3","t":"Ya RAB, insan ne ki, onu gözetesin, İnsan soyu ne ki, onu düşünesin?"},{"n":"4","t":"İnsan bir soluğu andırır, Günleri geçici bir gölge gibidir."},{"n":"5","t":"Ya RAB, gökleri yar, aşağıya in, Dokun dağlara, tütsünler."},{"n":"6","t":"Şimşek çaktır, dağıt düşmanı, Savur oklarını, şaşkına çevir onları."},{"n":"7","t":"Yukarıdan elini uzat, kurtar beni; Çıkar derin sulardan, Al eloğlunun elinden."},{"n":"8","t":"Onların ağzı yalan saçar, Sağ ellerini kaldırır, yalan yere ant içerler."},{"n":"9","t":"Ey Tanrı, sana yeni bir ezgi söyleyeyim, Seni on telli çenkle, ilahilerle öveyim."},{"n":"10","t":"Sensin kralları zafere ulaştıran, Kulun Davut'u kötülük kılıcından kurtaran."},{"n":"11","t":"Kurtar beni, özgür kıl Eloğlunun elinden. Onların ağzı yalan saçar, Sağ ellerini kaldırır, yalan yere ant içerler."},{"n":"12","t":"O zaman gençliğinde Sağlıklı yetişen fidan gibi olacak oğullarımız, Sarayın oymalı sütunları gibi olacak kızlarımız."},{"n":"13","t":"Her türlü ürünle dolup taşacak ambarlarımız; Binlerce, on binlerce yavrulayacak Çayırlarda davarlarımız."},{"n":"14","t":"Semiz olacak sığırlarımız; Surlarımıza gedik açılmayacak, İnsanlarımız sürgün edilmeyecek, Meydanlarımızda feryat duyulmayacak!"},{"n":"15","t":"Ne mutlu bunlara sahip olan halka! Ne mutlu Tanrısı RAB olan halka!"}]},{"id":145,"name":"145. MezmurDavut'un övgü ilahisi","verses":[{"n":"1","t":"Ey Tanrım, ey Kral, seni yücelteceğim, Adını sonsuza dek öveceğim."},{"n":"2","t":"Seni her gün övecek, Adını sonsuza dek yücelteceğim."},{"n":"3","t":"RAB büyüktür, yalnız O övgüye yaraşıktır, Akıl ermez büyüklüğüne."},{"n":"4","t":"Yaptıkların kuşaktan kuşağa şükranla anılacak, Güçlü işlerin duyurulacak."},{"n":"5","t":"Düşüneceğim harika işlerini, İnsanlar büyüklüğünü, yüce görkemini konuşacak."},{"n":"6","t":"Yaptığın müthiş işlerin gücünden söz edecekler, Ben de senin büyüklüğünü duyuracağım."},{"n":"7","t":"Eşsiz iyiliğinin anılarını kutlayacak, Sevinç ezgileriyle övecekler doğruluğunu."},{"n":"8","t":"RAB lütufkâr ve sevecendir, Tez öfkelenmez, sevgisi engindir."},{"n":"9","t":"RAB herkese iyi davranır, Sevecenliği bütün yapıtlarını kapsar."},{"n":"10","t":"Bütün yapıtların sana şükreder, ya RAB, Sadık kulların sana övgüler sunar."},{"n":"11","t":"Krallığının yüceliğini anlatır, Kudretini konuşur;"},{"n":"12","t":"Herkes senin gücünü, Krallığının yüce görkemini bilsin diye."},{"n":"13","t":"Senin krallığın ebedi krallıktır, Egemenliğin kuşaklar boyunca sürer. RAB verdiği bütün sözleri tutar, Her davranışı sadıktır."},{"n":"14","t":"RAB her düşene destek olur, İki büklüm olanları doğrultur."},{"n":"15","t":"Herkesin umudu sende, Onlara yiyeceklerini zamanında veren sensin."},{"n":"16","t":"Elini açar, Bütün canlıları doyurursun dilediklerince."},{"n":"17","t":"RAB bütün davranışlarında adil, Yaptığı bütün işlerde sevecendir."},{"n":"18","t":"RAB kendisine yakaran, İçtenlikle yakaran herkese yakındır."},{"n":"19","t":"Dileğini yerine getirir kendisinden korkanların, Feryatlarını işitir, onları kurtarır."},{"n":"20","t":"RAB korur kendisini seven herkesi, Yok eder kötülerin hepsini."},{"n":"21","t":"RAB'be övgüler sunsun ağzım! Bütün canlılar O'nun kutsal adına, Sonsuza dek övgüler dizsin."}]},{"id":146,"name":"146. Mezmur","verses":[{"n":"1","t":"RAB'be övgüler sunun! Ey gönlüm, RAB'be övgüler sun."},{"n":"2","t":"Yaşadıkça RAB'be övgüler sunacak, Var oldukça Tanrım'a ilahiler söyleyeceğim."},{"n":"3","t":"Önderlere, Sizi kurtaramayacak insanlara güvenmeyin."},{"n":"4","t":"O son soluğunu verince toprağa döner, O gün tasarıları da biter."},{"n":"5","t":"Ne mutlu yardımcısı Yakup'un Tanrısı olan insana, Umudu Tanrısı RAB'de olana!"},{"n":"6","t":"Yeri göğü, Denizi ve içindeki her şeyi yaratan, Sonsuza dek sadık kalan,"},{"n":"7","t":"Ezilenlerin hakkını alan, Açlara yiyecek sağlayan O'dur. RAB tutsakları özgür kılar,"},{"n":"8","t":"Körlerin gözünü açar, İki büklüm olanları doğrultur, Doğruları sever."},{"n":"9","t":"RAB garipleri korur, Öksüze, dul kadına yardım eder, Kötülerin yolunuysa saptırır."},{"n":"10","t":"RAB Tanrın sonsuza dek, ey Siyon, Kuşaklar boyunca egemenlik sürecek. RAB'be övgüler sunun!"}]},{"id":147,"name":"147. Mezmur","verses":[{"n":"1","t":"RAB'be övgüler sunun! Ne güzel, ne hoş Tanrımız'ı ilahilerle övmek! O'na övgü yaraşır."},{"n":"2","t":"RAB yeniden kuruyor Yeruşalim'i, Bir araya topluyor İsrail'in sürgünlerini."},{"n":"3","t":"O kırık kalplileri iyileştirir, Yaralarını sarar."},{"n":"4","t":"Yıldızların sayısını belirler, Her birini adıyla çağırır."},{"n":"5","t":"Rabbimiz büyük ve çok güçlüdür, Sınırsızdır anlayışı."},{"n":"6","t":"RAB mazlumlara yardım eder, Kötüleri yere çalar."},{"n":"7","t":"RAB'be şükran ezgileri okuyun, Tanrımız'ı lirle, ilahilerle övün."},{"n":"8","t":"O'dur gökleri bulutlarla kaplayan, Yeryüzüne yağmur sağlayan, Dağlarda ot bitiren."},{"n":"9","t":"O yiyecek sağlar hayvanlara, Bağrışan kuzgun yavrularına."},{"n":"10","t":"Ne atın gücünden zevk alır, Ne de insanın yiğitliğinden*fg* hoşlanır.D"},{"n":"10","t":"\"Yiğitliğinden\": İbranice \"Bacaklarından\"."},{"n":"11","t":"RAB kendisinden korkanlardan, Sevgisine umut bağlayanlardan hoşlanır."},{"n":"12","t":"RAB'bi yücelt, ey Yeruşalim! Tanrın'a övgüler sun, ey Siyon!"},{"n":"13","t":"Çünkü senin kapılarının kol demirlerine güç katar, İçindeki halkı kutsar."},{"n":"14","t":"Sınırlarını esenlik içinde tutar, Seni en iyi buğdayla doyurur."},{"n":"15","t":"Yeryüzüne buyruğunu gönderir, Sözü çarçabuk yayılır."},{"n":"16","t":"Yapağı gibi kar yağdırır, Kırağıyı kül gibi saçar."},{"n":"17","t":"Aşağıya iri iri dolu savurur, Kim dayanabilir soğuğuna?"},{"n":"18","t":"Buyruk verir, eritir buzları, Rüzgarını estirir, sular akmaya başlar."},{"n":"19","t":"Sözünü Yakup soyuna, Kurallarını, ilkelerini İsrail'e bildirir."},{"n":"20","t":"Başka hiçbir ulus için yapmadı bunu, Onlar O'nun ilkelerini bilmezler. RAB'be övgüler sunun!"}]},{"id":148,"name":"148. Mezmur","verses":[{"n":"1","t":"RAB'be övgüler sunun! Göklerden RAB'be övgüler sunun, Yücelerde O'na övgüler sunun!"},{"n":"2","t":"Ey bütün melekleri, O'na övgüler sunun, Övgüler sunun O'na, ey bütün göksel orduları!"},{"n":"3","t":"Ey güneş, ay, O'na övgüler sunun, Övgüler sunun O'na, ey ışıldayan bütün yıldızlar!"},{"n":"4","t":"Ey göklerin gökleri Ve göklerin üstündeki sular, O'na övgüler sunun!"},{"n":"5","t":"RAB'bin adına övgüler sunsunlar, Çünkü O buyruk verince, var oldular;"},{"n":"6","t":"Bozulmayacak bir kural koyarak, Onları sonsuza dek yerlerine oturttu."},{"n":"7","t":"Yeryüzünden RAB'be övgüler sunun, Ey deniz canavarları, bütün enginler,"},{"n":"8","t":"Şimşek, dolu, kar, bulutlar, O'nun buyruğuna uyan fırtınalar,"},{"n":"9","t":"Dağlar, bütün tepeler, Meyve ağaçları, sedir ağaçları,"},{"n":"10","t":"Yabanıl ve evcil hayvanlar, Sürüngenler*, uçan kuşlar,"},{"n":"11","t":"Yeryüzünün kralları, bütün halklar, Önderler, yeryüzünün bütün yöneticileri,"},{"n":"12","t":"Delikanlılar, genç kızlar, Yaşlılar, çocuklar!"},{"n":"13","t":"RAB'bin adına övgüler sunsunlar, Çünkü yalnız O'nun adı yücedir. O'nun yüceliği yerin göğün üstündedir."},{"n":"14","t":"RAB kendi halkını güçlü kıldı, Bütün sadık kullarına, Kendisine yakın olan halka, İsrailliler'e ün kazandırdı. RAB'be övgüler sunun!"}]},{"id":149,"name":"149. Mezmur","verses":[{"n":"1","t":"RAB'be övgüler sunun! RAB'be yeni bir ezgi söyleyin, Sadık kullarının toplantısında O'nu ezgilerle övün!"},{"n":"2","t":"İsrail Yaratıcısı'nda sevinç bulsun, Siyon halkı Kralları'yla coşsun!"},{"n":"3","t":"Dans ederek övgüler sunsunlar O'nun adına, Tef ve lir çalarak O'nu ilahilerle övsünler!"},{"n":"4","t":"Çünkü RAB halkından hoşlanır, Alçakgönüllüleri zafer tacıyla süsler."},{"n":"5","t":"Bu onurla mutlu olsun sadık kulları, Sevinç ezgileri okusunlar yataklarında!"},{"n":"6","t":"Ağızlarında Tanrı'ya yüce övgüler, Ellerinde iki ağızlı kılıçla"},{"n":"7","t":"Uluslardan öç alsınlar, Halkları cezalandırsınlar,"},{"n":"8","t":"Krallarını zincire, Soylularını prangaya vursunlar!"},{"n":"9","t":"Yazılan kararı onlara uygulasınlar! Bütün sadık kulları için onurdur bu. RAB'be övgüler sunun!"}]},{"id":150,"name":"150. Mezmur","verses":[{"n":"1","t":"RAB'be övgüler sunun! Kutsal yerde Tanrı'ya övgüler sunun! Gücünü gösteren göklerde övgüler sunun O'na!"},{"n":"2","t":"Övgüler sunun O'na güçlü işleri için! Övgüler sunun O'na eşsiz büyüklüğüne yaraşır biçimde!"},{"n":"3","t":"Boru çalarak O'na övgüler sunun! Çenkle ve lirle O'na övgüler sunun!"},{"n":"4","t":"Tef ve dansla O'na övgüler sunun! Saz ve neyle O'na övgüler sunun!"},{"n":"5","t":"Zillerle O'na övgüler sunun! Çınlayan zillerle O'na övgüler sunun!"},{"n":"6","t":"Bütün canlı varlıklar RAB'be övgüler sunsun! RAB'be övgüler sunun!"}]}];
